(window.WCD=window.WCD||[]).push(["heros",[["Q1735229",1,"super","Adam Warlock","C","Adam Warlock est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, puis développé de façon significative par les scénaristes Roy Thomas et Jim Starlin, le personnage de fiction apparaît pour la première fois dans le comic book Fantastic Four #66 en septembre 1967.","Adam Warlock est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Adam_Warlock","c:c/ce/SDCC_2012_-_Adam_Warlock_%26_Pip_the_Troll_%287567383358%29.jpg"],["Q48833172",7,"super","Batwoman","C","Kathy Kane est un personnage de fiction créé par Bob Kane et Sheldon Moldoff dans Detective Comics #233 en 1956. Elle porte le costume de Batwoman.","Kathy Kane est un personnage de fiction créé par Bob Kane et Sheldon Moldoff dans Detective Comics #233 en 1956.","fr:Batwoman","c:3/35/Logo_Batwoman.png"],["Q575227",8,"super","Beast Boy","C","Beast Boy ou Changelin est un personnage de fiction, super-héros appartenant à l'univers de DC Comics. Il est connu principalement comme membre des Teen Titans. Créé par le scénariste Arnold Drake et l'artiste Bob Brown, il apparaît pour la première fois dans The Doom Patrol no 99.","Beast Boy ou Changelin est un personnage de fiction, super-héros appartenant à l'univers de DC Comics.","fr:Beast_Boy","c:3/32/New_York_Comic_Con_2016_-_Teen_Titans_%2830069434132%29_%28cropped%29_Beast_Boy.jpg",{"cats":["heros","persos_anim"]}],["Q599124",9,"super","Black Canary","C","Black Canary est une super-héroïne appartenant à l'univers de DC Comics. Créé par le scénariste Robert Kanigher et le dessinateur Carmine Infantino, le personnage de fiction apparaît pour la première fois dans le comic book Flash Comics #86 en août 1947.","Black Canary est une super-héroïne appartenant à l'univers de DC Comics.","fr:Black_Canary","c:2/25/Wondercon_2015-7886_%2817037777676%29.jpg"],["Q885626",11,"super","Blue Beetle","C","Blue Beetle est un super-héros qui a connu plusieurs incarnations et plusieurs éditeurs. Il a été créé par Charles Nicholas Wojtkowski et Will Eisner.","Blue Beetle est un super-héros qui a connu plusieurs incarnations et plusieurs éditeurs.","fr:Blue_Beetle","c:f/fe/Blue_Beetle.jpg"],["Q2267017",12,"super","Cable","PC","Nathan Summers, alias Cable est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont, le personnage de fiction apparaît pour la première fois dans le comic book Uncanny X-Men #201 en janvier 1986.","Nathan Summers, alias Cable est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Cable_(comics)","c:e/ed/Cable_and_Hope_cosplays.jpg"],["Q910204",15,"super","Chose","C","Benjamin « Ben » Grimm, alias la Chose, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Fantastic Four #1 en novembre 1961.",119,"fr:Chose_(comics)","c:5/5c/Fantastic_Four_Cosplays_%28cropped%29.jpg"],["Q60002",17,"super","Colossus","C","Piotr « Peter » Rasputin, alias Colossus, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Len Wein et le dessinateur Dave Cockrum, le personnage de fiction apparaît pour la première fois dans le comic book Giant-Size X-Men #1 en mai 1975.",114,"fr:Colossus_(super-héros)","c:d/dd/Montreal_Comiccon_2015_-_Colossus_%2819267529469%29.jpg"],["Q5342183",22,"super","Diablo","PC","Kurt Wagner, alias Diablo est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Len Wein et le dessinateur Dave Cockrum, le personnage de fiction apparaît pour la première fois dans le comic book Giant-Size X-Men #1 en mai 1975, en compagnie des Nouveaux X-Men.","Kurt Wagner, alias Diablo est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Diablo_(Kurt_Wagner)","c:d/de/2014_Dragon_Con_Cosplay_-_Nightcrawler_%2815123640992%29.jpg"],["Q2519257",24,"super","Dr Manhattan","PC","Le Dr Manhattan est un des personnages du comic Watchmen d'Alan Moore.",null,"fr:Dr_Manhattan","c:f/f6/Dragon_Con_2014_-_Dr_Manhattan_%2815014296223%29.jpg"],["Q898039",25,"super","Drax le Destructeur","C","Arthur Douglas, alias Drax le Destructeur est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Jim Starlin et le dessinateur Mike Friedrich, le personnage de fiction apparaît pour la première fois dans le comic book The Invincible Iron Man #55 en février 1973.",114,"fr:Drax_le_Destructeur","c:a/a1/SDCC_2015_-_Drax_the_Destroyer_%2818974525464%29.jpg"],["Q913359",26,"super","Elektra","C","Elektra Natchios, alias Elektra est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créée par Frank Miller, le personnage de fiction apparaît pour la première fois dans le comic book Daredevil #168 en janvier 1981.",114,"fr:Elektra_(comics)","c:5/52/Elektra_-_Kyllie_Cosplay_-_Renaud_D._Photography.jpg"],["Q672591",27,"super","Faucon","C","Samuel « Sam » Wilson, alias le Faucon est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Gene Colan, le personnage de fiction apparaît pour la première fois dans le comic book Captain America #117 en septembre 1969.",118,"fr:Faucon_(comics)","c:5/59/NYCC_2014_-_Falcon_%2815501191145%29.jpg"],["Q302186",28,"super","Fauve","C","Henry « Hank » McCoy, alias le Fauve est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Uncanny X-Men #1 en septembre 1963.",116,"fr:Fauve_(comics)","c:2/2c/Beast_of_the_X-Men.jpg"],["Q510450",29,"super","Femme invisible","C","Jane Storm, alias l’Invisible puis la Femme invisible, aussi appelée Mme Fantastique, est une super-héroïne évoluant dans l’univers Marvel de la maison d'édition Marvel Comics.",116,"fr:Femme_invisible_(comics)","c:1/17/Cosplay_Invisible_Woman_Dracon_Con_2013.jpg"],["Q2639150",31,"super","Gambit","PC","Remy LeBeau, alias Gambit est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur Jim Lee, le personnage de fiction apparaît pour la première fois dans le comic book Uncanny X-Men Annual #14 en juillet 1990 puis dans Uncanny X-Men #266 en août 1990.","Remy LeBeau, alias Gambit est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Gambit_(comics)","c:3/38/SDCC_2012_-_Gambit_%287574607722%29.jpg"],["Q2721152",32,"super","Gamora","C","Gamora est une super-héroïne extraterrestre appartenant à l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste et dessinateur Jim Starlin, le personnage de fiction apparaît pour la première fois dans le comic book Strange Tales #180 de 1975.","Gamora est une super-héroïne extraterrestre appartenant à l'univers Marvel de la maison d'édition Marvel Comics.","fr:Gamora","c:9/96/Gamora_Cosplayer_at_the_2023_Comic-Con_International.jpg"],["Q868958",33,"super","Ghost Rider","R","Ghost Rider est un super-héros évoluant dans l'univers Marvel de la maison d’édition Marvel Comics. Créé par les scénaristes Roy Thomas et Gary Friedrich, ainsi que le dessinateur Mike Ploog, le personnage de fiction apparaît pour la première fois sous sa forme actuelle dans le comic book Marvel Spotlight #5 en août 1972.","Ghost Rider est un super-héros évoluant dans l'univers Marvel de la maison d’édition Marvel Comics.","fr:Ghost_Rider_(comics)","c:c/cf/2018-03-18_13-03-18_ILCE-6500_DSC06818_DxO_%2841928236592%29.jpg"],["Q648125",37,"super","Guêpe","C","Janet van Dyne, alias la Guêpe est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Tales to Astonish #44 en juin 1963.",113,"fr:Guêpe_(comics)","c:6/69/Riddle_as_the_Wasp_%289333600596%29.jpg"],["Q2345627",38,"super","Hal Jordan","L","Harold « Hal » Jordan est un héros de fiction appartenant à DC Comics. La première apparition du personnage est dans Showcase #22.","Harold « Hal » Jordan est un héros de fiction appartenant à DC Comics.","fr:Hal_Jordan","c:f/f9/New_York_Comic_Con_2014_-_Hal_Jordan_cosplay_%2815344153580%29.jpg"],["Q2359610",39,"super","Hawkman","C","Hawkman est le nom de plusieurs personnages de super-héros appartenant à DC Comics. Il est systématiquement dépeint comme un guerrier réincarné à thématique de faucon, ayant accès au métal Nth fictif qui lui confère une multitude de pouvoirs, et affichant une préférence pour les armes archaïques. Il est souvent associé à sa compagne de réincarnation et amante, Hawkgirl.","Hawkman est le nom de plusieurs personnages de super-héros appartenant à DC Comics.","fr:Hawkman","https://upload.wikimedia.org/wikipedia/en/thumb/3/32/Hawkman_%28DC_Comics%29_001.png/330px-Hawkman_%28DC_Comics%29_001.png"],["Q3785909",41,"super","Hit-Girl","C","Mindy Macready, alias Hit-Girl, est un personnage fictif créé par l'écrivain Mark Millar et l'artiste John Romita, Jr. dans la série de comics Kick-Ass, publiée par Marvel Comics aux États-Unis et Panini en France. C'est une jeune fille formée au combat et à la self-défense par son père Damon McCready dès son très jeune âge pour devenir une super-héroïne. Dans le comics, ce personnage est présenté comme un personnage secondaire qui aide le protagoniste principal, Kick-Ass.","Mindy Macready, alias Hit-Girl, est un personnage fictif créé par l'écrivain Mark Millar et l'artiste John Romita, Jr.","fr:Hit-Girl_(personnage)","c:d/dd/Cosplay_of_Hit-Girl_at_AVA_Expo_2013-1.jpg"],["Q838088",43,"super","Iceberg","C","Robert « Bobby » Drake, alias Iceberg, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book X-Men #1 en septembre 1963.",118,"fr:Iceberg_(comics)","c:8/89/NYCC_2014_-_Iceman_%2815324714370%29.jpg"],["Q1194243",44,"super","Iron Fist","C","Daniel « Danny » Rand, alias Iron Fist est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Roy Thomas et le dessinateur Gil Kane, le personnage de fiction apparaît pour la première fois dans le comic book Marvel Premiere #15 en mai 1974.",118,"fr:Iron_Fist_(comics)","c:e/ec/Ironfist%2C_straight_out_of_the_comics_HDR_C2E2_2013_%288688116326%29_%28cropped%29.jpg"],["Q28006858",47,"super","James Barnes","PC","James Barnes, alias Bucky est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Joe Simon et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Captain America Comics #1 chez Timely Comics en mars 1941.","James Barnes, alias Bucky est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:James_Barnes_(comics)","c:3/3a/Wizard_World_Anaheim_2011_-_Bucky_Barnes.jpg"],["Q2271377",49,"super","Jessica Jones","PC","Jessica Jones est un personnage de fiction de l'univers Marvel créé en 2001 par Brian Michael Bendis et Michael Gaydos. C'est une ancienne super-héroïne. Elle est connue sous d'autres pseudonymes, comme Jewel ou Knightress.","Jessica Jones est un personnage de fiction de l'univers Marvel créé en 2001 par Brian Michael Bendis et Michael Gaydos.","fr:Jessica_Jones","c:c/c4/Jessica_Jones_-_24801301121.jpg"],["Q2663841",50,"super","John Constantine","PC","John Constantine est le personnage de fiction principal de la série de comics Hellblazer publiée par DC Comics. C'est un anti-héros, spécialiste de la magie noire et de l'occulte. Il se caractérise par un style sarcastique et parfois méprisant envers les autres. Sa première apparition a lieu dans le comics Swamp Thing en 1985, sous la plume d'Alan Moore.","John Constantine est le personnage de fiction principal de la série de comics Hellblazer publiée par DC Comics.","fr:John_Constantine","c:5/55/WonderCon_2014_-_Constatine_cosplay_%2813955024943%29_%28cropped%29.jpg"],["Q15208946",52,"super","Kamala Khan","C","Kamala Khan est un personnage de fiction, une super-héroïne de l'univers Marvel de la maison d'édition américaine Marvel Comics. Créé par les éditeurs Sana Amanat et Stephen Wacker, la scénariste G. Willow Wilson et le dessinateur Adrian Alphona, le personnage apparaît pour la première fois dans le comic book Captain Marvel Vol. 7 no 14 d'août 2013, et obtient son premier comics en solo en 2014, intitulé Ms. Marvel. Elle est la cinquième héroïne à prendre le nom de code de Miss Marvel.",113,"fr:Kamala_Khan","c:8/88/Dragon_Con_2015_-_Ms_Marvel_%2821904768165%29.jpg"],["Q6404178",53,"super","Kick-Ass","C","David « Dave » Lizewski, alias Kick-Ass et Nom de Code: Amérique, est le personnage éponyme de la série de comics Kick-Ass, Big Game, et Nemesis: Forever, publiée par Marvel Comics aux États-Unis et par Panini Comics en France. Ce personnage a été créé par l'écrivain Mark Millar et l'artiste John Romita, Jr..",113,"fr:Kick-Ass_(personnage)","c:8/84/Cosplay_of_Kick-Ass_at_AVA_Expo_2013.jpg"],["Q947755",54,"super","Le Fantôme","C","Le Fantôme ou Fantôme ou, occasionnellement, Le Fantôme du Bengale, est une série de bande dessinée américaine créée par Lee Falk. Elle est diffusée sous forme de comic strip depuis le 17 février 1936 pour la bande quotidienne en noir et blanc et depuis le 28 mai 1939 pour la planche dominicale en couleur.",116,"fr:Le_Fantôme_(bande_dessinée)","c:3/3a/The_Phantom%2C_Australian_Woman%27s_Mirror_2.jpg"],["Q1510225",55,"super","Le Frelon vert","C","Le Frelon vert est un justicier masqué créé en 1936 pour la radio américaine, accompagné de son fidèle chauffeur Kato, joué par Bruce Lee dans la série télé.","","en:Green_Hornet","c:5/5a/Van_Williams_as_Green_Hornet_1966_%28cropped%29.JPG"],["Q927354",57,"super","Les Jeunes Titans","PC","Les Jeunes Titans, aussi connus en tant que Teen Titans, The New Teen Titans, The New Titans, et The Titans, est une équipe de super-héros de comics publiée par DC Comics. Comme le nom de l’équipe le suggère, ses membres sont habituellement des adolescents. Beaucoup de ces adolescents ont été des acolytes des super-héros principaux de DC, notamment dans La ligue de justice d'Amérique. Début 2014, DC Comics annonce le lancement d'un nouveau magazine Teen Titans pour juillet 2014.",116,"fr:Les_Jeunes_Titans","https://upload.wikimedia.org/wikipedia/en/thumb/f/f4/Titans_01_2023_cover.jpg/330px-Titans_01_2023_cover.jpg"],["Q2267760",59,"super","Luke Cage","C","Luke Cage, alias Power Man est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par Archie Goodwin, George Tuska, Roy Thomas et John Romita, Sr., le personnage de fiction apparaît pour la première fois dans le comic book Luke Cage, Hero for Hire #1, en juin 1972.","Luke Cage, alias Power Man est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Luke_Cage","c:2/21/Luke_Cage_cosplay.jpg"],["Q838097",60,"super","Malicia","E","Anna Marie, alias Malicia est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur Michael Golden, le personnage de fiction apparaît pour la première fois dans le comic book The Avengers Annual #10 en 1981.","Anna Marie, alias Malicia est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Malicia_(comics)","c:a/a0/Awesome_con_2016_Cosplay_of_Rogue_from_X-Men-_The_Animated_Series.jpg"],["Q59654462",61,"super","Marinette Dupain-Cheng","C","Marinette Dupain-Cheng, aussi appelée Ladybug sous sa forme de super-héroïne, est l'un des deux personnages principaux de la série d'animation Miraculous: Les Aventures de Ladybug et Chat Noir, créée par Thomas Astruc. Collégienne parisienne passionnée de mode et de création, elle se transforme en Ladybug grâce à ses boucles d'oreilles magiques, les Miraculous, et à sa kwami Tikki.",118,"fr:Marinette_Dupain-Cheng","https://upload.wikimedia.org/wikipedia/en/thumb/4/4f/Marinette_Dupain-Cheng.png/330px-Marinette_Dupain-Cheng.png"],["Q3294090",62,"super","Mark Grayson","C","Mark Grayson, alias Invincible, est le personnage principal et éponyme du comic Invincible.",null,"fr:Mark_Grayson","https://upload.wikimedia.org/wikipedia/en/thumb/f/fc/Invincible_52.jpg/330px-Invincible_52.jpg"],["Q1037532",64,"super","Moon Knight","R","Marc Spector, alias Moon Knight est un super-héros évoluant dans l'univers Marvel de la maison d’édition Marvel Comics. Créé par le scénariste Doug Moench et le dessinateur Don Perlin, le personnage de fiction apparaît dans le comic book Werewolf by Night #32 en août 1975, un crossover dans lequel se trouve aussi le personnage de Jack Russel.","Marc Spector, alias Moon Knight est un super-héros évoluant dans l'univers Marvel de la maison d’édition Marvel Comics.","fr:Moon_Knight","c:3/38/San_Diego_Comic-Con_2019_-_Moon_Knight.jpg"],["Q613067",66,"super","Namor","PC","Namor McKenzie, alias Namor, aussi connu comme le Prince des mers est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le dessinateur et scénariste Bill Everett, le personnage de fiction apparaît pour la première fois dans le comic book Motion Picture Funnies Weekly en avril 1939.",118,"fr:Namor","c:0/0a/Namor_%289371515878%29_cropped.jpg"],["Q686623",69,"super","Nightwing","C","Nightwing est l'identité de super-héros adoptée par Dick Grayson, le premier Robin, devenu adulte et sorti de l'ombre de Batman (DC Comics).","","en:Nightwing","https://upload.wikimedia.org/wikipedia/en/thumb/8/8b/Nightwing_Vol_4_137_%282026_Cover_B_David_Nakayama_art.png/330px-Nightwing_Vol_4_137_%282026_Cover_B_David_Nakayama_art.png"],["Q746838",71,"super","Plastic Man","C","Plastic Man est un super-héros de comics, créé par Jack Cole en août 1941, qui a fait sa première apparition dans Police Comics no 1, durant l'Âge d'or des comics.",113,"fr:Plastic_Man","c:d/df/Police_Comics_no._38_%28cover_art%29.jpg"],["Q948668",72,"super","Power Girl","C","Power Girl, de son vrai nom Kara Zor-L, également connue sous les identités civiles de Karen Starr et Paige Stetler, est une super-héroïne créée en janvier 1976 par Gerry Conway, Ric Estrada et Wally Wood pour le compte de DC Comics. Le personnage apparaît pour la première fois dans le numéro 58 du comic book All Star Comics.",116,"fr:Power_Girl","c:6/6a/Japan_Expo_2010_Power_Girl_cosplay.jpg"],["Q333156",73,"super","Power Rangers","E","Power Rangers est une franchise de médias américaine fondée sur une équipe de super-héros. Les Power Rangers sont adaptés des séries japonaises Super sentai, les producteurs américains rachetant les droits d'utilisation des images et les costumes aux producteurs japonais.","Power Rangers est une franchise de médias américaine fondée sur une équipe de super-héros.","fr:Power_Rangers","c:c/c8/Power_Rangers_Samurai.jpg",{"cats":["heros","enfance"]}],["Q838076",74,"super","Professeur Xavier","R","Le professeur Charles Xavier, alias le Professeur Xavier ou le Professeur X, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Uncanny X-Men #1 en septembre 1963.",119,"fr:Professeur_Xavier","c:9/99/SDCC13_-_Professor_X.jpg"],["Q110095070",75,"super","Psylocke","C","Psylocke est une super-héroïne des X-Men (Marvel), télépathe et experte en arts martiaux, capable de créer des lames psychiques.","","en:Psylocke","https://upload.wikimedia.org/wikipedia/en/thumb/7/73/Excalibur_%28Vol._4%29%2C_No._19_%28Textless_Variant%29.jpg/330px-Excalibur_%28Vol._4%29%2C_No._19_%28Textless_Variant%29.jpg"],["Q245928",78,"super","Raven","PC","Raven est une super-héroïne de comics appartenant à l'univers de DC Comics. Raven a été un membre important des New Teen Titans et a récemment rejoint les rangs des Teen Titans modernes. Raven est une empathe, elle peut se téléporter et peut faire sortir son âme dans un corps astral qui peut se battre physiquement.","Raven est une super-héroïne de comics appartenant à l'univers de DC Comics.","fr:Raven_(DC_Comics)","c:5/55/C2E2_2014_-_Raven_%2814085544008%29.jpg",{"cats":["heros","persos_anim"]}],["Q638476",80,"super","Rocket Raccoon","C","Rocket Raccoon est un super-héros extraterrestre appartenant à l'univers Marvel de la maison d'édition Marvel Comics.",null,"fr:Rocket_Raccoon","c:e/e5/Cosplay_de_Rocket_Raccoon_%28marvel%29.jpg"],["Q2346769",81,"super","Rorschach","PC","Rorschach est un personnage de fiction et antihéros de la série de comic book Watchmen. Créé par Alan Moore et Dave Gibbons, il apparaît pour la première fois dans Watchmen #1 en 1986.","Rorschach est un personnage de fiction et antihéros de la série de comic book Watchmen.","fr:Rorschach_(comics)","c:5/51/RorschachCloseUp.jpg"],["Q2262357",82,"super","Shang-Chi","C","Shang-Chi, aussi appelé le Maître du kung-fu est un super-héros évoluant dans l’univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Steve Englehart, le dessinateur Jim Starlin et l'encreur Al Milgrom, le personnage de fiction apparaît pour la première fois dans le comic book Special Marvel Edition #15 en décembre 1973.",117,"fr:Shang-Chi","https://upload.wikimedia.org/wikipedia/en/thumb/6/62/Shang-Chi_Vol_1_%2C1.jpg/330px-Shang-Chi_Vol_1_%2C1.jpg"],["Q929285",84,"super","Sorcière rouge","E","Wanda Maximoff, alias la Sorcière rouge, est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book X-Men #4 en mars 1964.",116,"fr:Sorcière_rouge","c:f/f7/Brasil_Comic_Con_2014_%2815178816243%29.jpg"],["Q18754957",86,"super","Spider-Gwen","C","Spider-Gwen (Ghost-Spider) est une version alternative de Gwen Stacy (Marvel), qui a été mordue par l'araignée à la place de Peter Parker.","","en:Spider-Gwen","https://upload.wikimedia.org/wikipedia/en/thumb/4/42/Spider-Gwen_Vol_1_1.jpg/330px-Spider-Gwen_Vol_1_1.jpg"],["Q59826",88,"super","Spider-Man (Miles Morales)","R","Miles Morales, alias Spider-Man né le 21 juillet 2005 à Brooklyn, est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Brian Michael Bendis et la dessinatrice Sara Pichelli, ce personnage de fiction apparait pour la première fois dans le comic book Ultimate Comics: Fallout #4 en août 2011.",118,"fr:Spider-Man_(Miles_Morales)","c:3/3a/Miles_Morales_cosplay_at_Asia_Comic_Expo_001_2.jpg"],["Q4353353",89,"super","Squirrel Girl","C","Doreen Green, alias Squirrel Girl, est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par l'auteur Will Murray et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book Marvel Super-Heroes #8 en janvier 1992.",117,"fr:Squirrel_Girl","https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Marvel_Logo.svg/330px-Marvel_Logo.svg.png"],["Q427987",91,"super","Starfire","PC","Starfire est le nom de plusieurs héros et personnages. Toutefois, c'est Koriand'r qui est officiellement Starfire, créé en 1980 par Mark Wolfman et George Pérez dans DC Comics Presents no 26.","Starfire est le nom de plusieurs héros et personnages.","fr:Starfire","c:2/22/WonderCon_2012_-_Starfire_from_Teen_Titans_%287019136731%29.jpg"],["Q4354752",92,"super","Static","C","Static est un super-héros de DC Comics créé en 1993, un adolescent capable de contrôler l'électricité. Il a eu sa propre série animée, Static Choc.","","en:Static_(DC_Comics)","https://upload.wikimedia.org/wikipedia/en/thumb/d/de/Static_%28Virgil_Hawkins%29.png/330px-Static_%28Virgil_Hawkins%29.png"],["Q1427625",96,"super","Swamp Thing","PC","La Créature du marais ou La Créature des marais est le personnage principal de la série de bande dessinée américaine du même nom créée dans les années 1970 par Len Wein et Berni Wrightson.",119,"fr:Swamp_Thing","c:a/a3/Swamp_Thing_and_Len_Wein.jpg"],["Q584585",98,"super","Torche humaine","C","Jonathan « Johnny » Storm, alias la Torche humaine est un super-héros évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Fantastic Four #1 en novembre 1961.",113,"fr:Torche_humaine","c:3/3b/Dragon_Con_2013_-_Human_Torch_%289694709273%29.jpg"],["Q632212",99,"super","Tornade","PC","Ororo Munroe, alias Tornade est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Len Wein et le dessinateur Dave Cockrum, le personnage de fiction apparaît pour la première fois dans le comic book Giant-Size X-Men #1 en mai 1975.","Ororo Munroe, alias Tornade est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Tornade_(comics)","c:0/09/Anime_Expo_2011_-_Storm_close-up_%285892747839%29.jpg"],["Q1381762",100,"super","Tortues Ninja","E","Les Tortues Ninja sont des personnages de fiction créés par Kevin Eastman et Peter Laird en 1984 dans le comics du même nom.",119,"fr:Tortues_Ninja","https://upload.wikimedia.org/wikipedia/fr/thumb/b/b6/Tortues_Ninja.png/330px-Tortues_Ninja.png"],["Q860922",106,"super","Zatanna","C","Zatanna Zatara est un personnage de fiction appartenant à l'univers de DC Comics. Créé par le scénariste Gardner Fox et le dessinateur Murphy Anderson, elle apparaît pour la première fois dans le comic book Hawkman vol. 1 #4 en 1964. Zatanna est la fille d'un grand magicien qui a, dans le passé, appris à Bruce Wayne nombre de ses tours. Zatanna et Bruce ont eu une brève histoire d'amour avant qu'elle ne doive partir pour suivre son père et que Bruce ne devienne Batman.","Zatanna Zatara est un personnage de fiction appartenant à l'univers de DC Comics.","fr:Zatanna","c:f/f5/San_Diego_Comic-Con_2019_-_Zatanna.jpg"],["Q2085488",107,"mechant","Agent Smith","C","L'Agent Smith est un personnage de fiction apparaissant dans la série de films Matrix et joué par l'acteur Hugo Weaving dans Matrix, Matrix Reloaded et Matrix Revolutions, puis par Jonathan Groff et Yahya Abdul-Mateen II dans Matrix Resurrections. Il est un agent, c'est-à-dire un programme qui parcourt la Matrice pour en assurer la sécurité et lutter contre les humains qui la piratent.",119,"fr:Agent_Smith","c:b/bf/Warner_Brothers_VIP_studio_tour_-_Matrix_mannequins_%282862323128%29.jpg"],["Q1146291",108,"mechant","Albert Wesker","E","Albert Wesker est un personnage de fiction et l'un des principaux antagonistes de la série de jeux vidéo Resident Evil créé par Capcom.",118,"fr:Albert_Wesker","",{"cats":["heros","horreur","persos_jv"]}],["Q1628095",111,"mechant","Annie Wilkes","C","Annie Wilkes est l'infirmière psychopathe du roman Misery de Stephen King (1987), qui séquestre son écrivain préféré. Kathy Bates a remporté l'Oscar pour ce rôle.","","en:Annie_Wilkes","https://upload.wikimedia.org/wikipedia/en/thumb/3/3e/KathyWilkins1212.jpg/330px-KathyWilkins1212.jpg",{"cats":["heros","horreur"]}],["Q4775712",112,"mechant","Anton Chigurh","R","Anton Chigurh est le tueur implacable de No Country for Old Men (Cormac McCarthy), armé d'un pistolet d'abattage. Javier Bardem a remporté l'Oscar pour ce rôle.","","en:Anton_Chigurh","https://upload.wikimedia.org/wikipedia/en/thumb/4/41/Anton_Chigurh.jpg/330px-Anton_Chigurh.jpg"],["Q2071805",113,"mechant","Apocalypse","R","En Sabah Nur, alias Apocalypse est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par la scénariste Louise Simonson et le dessinateur Jackson Guice, le personnage de fiction apparaît pour la première fois dans le comic book X-Factor #5 en juin 1986.","En Sabah Nur, alias Apocalypse est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Apocalypse_(comics)","c:c/cf/San_Diego_Comic_Con_2014-1323_%2814571754679%29.jpg"],["Q924817",114,"mechant","Auric Goldfinger","C","Auric Goldfinger est un ennemi de James Bond, méchant principal du roman et du film Goldfinger.",null,"fr:Auric_Goldfinger","https://upload.wikimedia.org/wikipedia/en/thumb/4/47/Goldfinger_by_Gert_Fr%C3%B6be.jpg/330px-Goldfinger_by_Gert_Fr%C3%B6be.jpg"],["Q2537674",117,"mechant","Biff Tannen","C","Biff Tannen est un personnage de fiction créé par Robert Zemeckis et Bob Gale et interprété par Thomas F. Wilson dans la trilogie Retour vers le futur.","Biff Tannen est un personnage de fiction créé par Robert Zemeckis et Bob Gale et interprété par Thomas F.","fr:Biff_Tannen","https://upload.wikimedia.org/wikipedia/en/thumb/1/15/BiffTannenBackToTheFuture1985.jpg/330px-BiffTannenBackToTheFuture1985.jpg"],["Q391161",118,"mechant","Black Adam","C","Black Adam est un personnage fictif de DC Comics créé en 1945 par Otto Binder et C. C. Beck comme une version maléfique du super-héros Shazam. Sa personnalité a évolué au fil des années et aujourd'hui, elle oscille entre le bien et le mal.","Black Adam est un personnage fictif de DC Comics créé en 1945 par Otto Binder et C.","fr:Black_Adam","c:f/fa/Logo_Black_Adam.png"],["Q2538991",119,"mechant","Black Manta","C","Black Manta est un personnage de fiction, un super-vilain de DC Comics créé par Bob Haney & Nick Cardy dans Aquaman #35 en septembre 1967. C'est l'ennemi juré du super-héros Aquaman.",119,"fr:Black_Manta","https://upload.wikimedia.org/wikipedia/en/thumb/5/5f/Black_Manta_Aquaman.webp/330px-Black_Manta_Aquaman.webp"],["Q51790",120,"mechant","Boba Fett","C","Boba Fett est un personnage de la saga cinématographique Star Wars.",null,"fr:Boba_Fett","c:3/38/Boba_Fett_-_A_Fett_to_Remember.jpg"],["Q735721",121,"mechant","Bouffon vert","C","Le Bouffon vert ou le Gobelin vert au Québec est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #14 en juillet 1964.",118,"fr:Bouffon_vert","c:c/c2/Greengoblincosplayercopiz.jpg"],["Q592909",122,"mechant","Brainiac","PC","Brainiac est un personnage de fiction de DC Comics et un ennemi de Superman, créé par Otto Binder & Al Plastino dans Action Comics #242 en juillet 1958.",116,"fr:Brainiac_(comics)","c:5/51/New_York_Comic_Con_2015_-_Brainiac_%2821442078224%29.jpg"],["Q1753328",123,"mechant","Carnage","C","Cletus Kasady, alias Carnage, est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste David Michelinie et le dessinateur Mark Bagley, le personnage de fiction apparaît pour la première fois dans le comic book Amazing Spider-Man #361 en avril 1992.","Cletus Kasady, alias Carnage, est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Carnage_(comics)","c:7/7e/Wondercon_2016_-_Carnage_Cosplay_%2825808079300%29.jpg"],["Q6569036",126,"mechant","Personnages d'Hercule","C","Les personnages d'Hercule (Disney, 1997) réunissent le héros Hercule, Mégara, le satyre Philoctète, le cheval ailé Pégase et le dieu des Enfers Hadès.","","en:List_of_Disney's_Hercules_characters","https://upload.wikimedia.org/wikipedia/en/thumb/7/76/Disney%27s_Hercules_characters.jpg/330px-Disney%27s_Hercules_characters.jpg"],["Q2620997",127,"mechant","Cheetah","C","Cheetah est un personnage de fiction créé par William Moulton Marston. Il est apparu dans plusieurs œuvres liés à l'univers de DC Comics. Il s'agit de la pire ennemie de Wonder Woman.","Cheetah est un personnage de fiction créé par William Moulton Marston.","fr:Cheetah_(DC_Comics)","c:5/51/Long_Beach_Comic_Expo_2011_-_Cheetah_%285648076127%29.jpg"],["Q520812",128,"mechant","Claude Frollo","C","Claude Frollo est un des personnages centraux du roman Notre-Dame de Paris de Victor Hugo.",null,"fr:Claude_Frollo","c:3/3a/Gustave_Brion_-_Claude_Frollo.jpg"],["Q51727",129,"mechant","Comte Dooku","C","Le comte Dooku, alias Dark Tyranus, ou Darth Tyranus, est un personnage de fiction de la saga Star Wars. Membre de la maison Serenno qui dirige la planète du même nom, il est abandonné par sa famille, effrayée par sa sensibilité à la Force, et recueilli par l'ordre Jedi. Il devient au cours de sa formation le padawan de Yoda puis, une fois devenu chevalier, forme Qui-Gon Jinn.","Le comte Dooku, alias Dark Tyranus, ou Darth Tyranus, est un personnage de fiction de la saga Star Wars.","fr:Comte_Dooku","c:d/d8/Dooku.jpg"],["Q51766",131,"mechant","Dark Maul","PC","Dark Maul, ou plus simplement Maul, Darth Maul dans la version originale en anglais et la traduction québécoise, est un personnage de fiction de l'univers de Star Wars qui apparaît dans l'épisode I, dans la série Star Wars: The Clone Wars aux côtés de son frère, Savage Opress, dans la série Star Wars Rebels, Solo: A Star Wars Story, et enfin dans Maul: Seigneur de l'ombre. C'est un Zabrak originaire de la planète Dathomir. Ce personnage a été créé par l'illustrateur Iain Mccaig pour Industrial Light & Magic.",119,"fr:Dark_Maul","c:8/86/Darth_Maul_Cosplayer_at_MCM_Comic_Con_October_2016.jpg"],["Q1181328",133,"mechant","Deathstroke","PC","Deathstroke de son vrai nom Slade Wilson est un personnage de l'univers de DC Comics. Il s'agit d'un mercenaire-assassin, essentiellement connu comme un ennemi des Teen Titans, et plus particulièrement, dans la série animée, de leur leader Robin. Mais il est aussi un anti-héros, qui a eu le droit en certaines occasions à sa propre série. On l'appelle l'Assassin Romain.","Deathstroke de son vrai nom Slade Wilson est un personnage de l'univers de DC Comics.","fr:Deathstroke","c:1/1c/C2E2_2014_-_Deathstroke_%2814268417541%29.jpg"],["Q431862",134,"mechant","Dents-de-sabre","PC","Victor Creed, alias Dents-de-sabre est un super-vilain évoluant dans l’univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur John Byrne, le personnage de fiction apparaît pour la première fois dans le comic book Iron Fist #14 en août 1977.",115,"fr:Dents-de-sabre","c:e/ef/SDCC_2012_-_Sabretooth_%287573786874%29.jpg"],["Q716941",137,"mechant","Dolores Ombrage","PC","Dolores Jane Ombrage est un personnage fictif issu de la saga Harry Potter. Elle est une sous-secrétaire d'État auprès du ministre de la Magie, Cornelius Fudge. Issue de la bureaucratie du ministère de la Magie, c'est une femme malsaine, bornée et particulièrement perverse, hypocrite. Elle est prête à tous les moyens, pour imposer sa loi à l'école de sorcellerie Poudlard et ainsi obliger Harry Potter à ne plus annoncer au monde des sorciers le retour de Voldemort.","Dolores Jane Ombrage est un personnage fictif issu de la saga Harry Potter.","fr:Dolores_Ombrage","c:4/4e/Dolores_Ombrage.jpg"],["Q126680",138,"mechant","Doomsday","PC","Doomsday est un super-vilain appartenant à l'univers de DC Comics. Il est apparu pour la première fois dans Superman: The Man of Steel #17 en novembre 1992. C'est un ennemi de Superman, il est connu pour l'avoir tué dans Superman #75: La Mort de Superman publié en janvier 1993, et plus récemment dans le long-métrage Batman V Superman: L'Aube de la Justice.","Doomsday est un super-vilain appartenant à l'univers de DC Comics.","fr:Doomsday_(DC_Comics)","c:d/d4/NYCC_2018_-_Doomsday_Cosplayer.jpg"],["Q2066394",139,"mechant","Dormammu","C","Dormammu est un super-vilain et une entité interdimensionnelle évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book Strange Tales #126 en novembre 1964.",116,"fr:Dormammu","https://upload.wikimedia.org/wikipedia/en/thumb/8/80/Dormammu.png/330px-Dormammu.png"],["Q3266236",141,"mechant","Dracula","E","Le comte Dracula est un personnage de fiction créé par l'écrivain Bram Stoker dans son roman épistolaire Dracula publié le 26 mai 1897.",119,"fr:Dracula_(personnage)","c:9/90/Bela_Lugosi_as_Dracula%2C_anonymous_photograph_from_1931%2C_Universal_Studios.jpg",{"cats":["heros","horreur"]}],["Q2297886",142,"mechant","Electro","C","Maxwell « Max » Dillon, alias Electro est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #9 en février 1964.",118,"fr:Electro_(comics)","c:6/6e/2014_Dragon_Con_Cosplay_-_Electro_%2814937271268%29.jpg"],["Q1104987",143,"mechant","Ernst Stavro Blofeld","R","Ernst Stavro Blofeld est un personnage fictif dans la série de romans James Bond, écrits par Ian Fleming. Blofeld est le chef du SPECTRE, redoutable organisation criminelle dont le siège se trouve originellement à Paris.","Ernst Stavro Blofeld est un personnage fictif dans la série de romans James Bond, écrits par Ian Fleming.","fr:Ernst_Stavro_Blofeld","c:1/11/ChristophWaltz82AAMar10.jpg"],["Q1162210",144,"mechant","Fantômas","C","Fantômas est un personnage de fiction français créé en 1911 par Pierre Souvestre et Marcel Allain. Sévissant dans la France de la Belle Époque, ce criminel est l'archétype du génie du mal, insaisissable et mystérieux. Défiant les forces de l'ordre, et en particulier le commissaire Juve et le journaliste Jérôme Fandor, Fantômas poursuit ses activités criminelles grâce à son art du déguisement et de l'évasion.","Fantômas est un personnage de fiction français créé en 1911 par Pierre Souvestre et Marcel Allain.","fr:Fantômas","c:1/10/Fantomas_1911.jpg"],["Q841372",145,"mechant","Fléau","PC","Cain Marko, alias le Fléau est un personnage de fiction, au départ un super-vilain, évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, il apparaît pour la première fois dans le comic book X-Men #12 en juillet 1965.",117,"fr:Fléau_(comics)","c:0/00/Cosplay_Juggernaut_2012.jpg"],["Q2269136",148,"mechant","Gaston","C","Gaston est un personnage de fiction et principal antagoniste du long métrage d'animation La Belle et la Bête, des studios Disney par Gary Trousdale et Kirk Wise, sorti en 1991.",113,"fr:Gaston_(Disney)","https://upload.wikimedia.org/wikipedia/en/thumb/a/a7/Gaston%28BeautyandtheBeast%29.png/330px-Gaston%28BeautyandtheBeast%29.png"],["Q605125",149,"mechant","GLaDOS","PC","GLaDOS est un personnage fictif qui apparaît dans les jeux vidéo Portal et Portal 2. Elle a été créée par Erik Wolpaw et Kim Swift. Ellen McLain la double en version originale; Scarlett Perdereau en version française.","GLaDOS est un personnage fictif qui apparaît dans les jeux vidéo Portal et Portal 2.","fr:GLaDOS","https://upload.wikimedia.org/wikipedia/en/thumb/b/bf/Glados.png/330px-Glados.png",{"cats":["heros","persos_jv"]}],["Q719748",151,"mechant","Grinch","C","Le Grinch est une créature verte et grincheuse imaginée par le Dr Seuss en 1957, qui déteste Noël et décide de le voler aux habitants de Chouville.","","en:Grinch","https://upload.wikimedia.org/wikipedia/en/thumb/7/73/The_Grinch.png/330px-The_Grinch.png"],["Q2260732",152,"mechant","Général Zod","C","Le Général Zod est un personnage de fiction de comics appartenant à l'univers DC. Il s'agit d'un ennemi de Superman. Créé par Robert Bernstein et George Papp, il est apparu dans Adventure Comics #283 en avril 1961.","Le Général Zod est un personnage de fiction de comics appartenant à l'univers DC.","fr:Général_Zod","c:b/b1/New_York_Comic_Con_2014_-_General_Zod_%2815519505971%29.jpg"],["Q833933",153,"mechant","HAL 9000","PC","HAL 9000 est un personnage de fiction, un supercalculateur doté d'intelligence artificielle. Il a été conçu pour gérer de manière autonome les fonctions vitales du vaisseau spatial Discovery One, en mission dans l'espace vers la planète Jupiter.","HAL 9000 est un personnage de fiction, un supercalculateur doté d'intelligence artificielle.","fr:HAL_9000","https://upload.wikimedia.org/wikipedia/commons/thumb/f/f6/HAL9000.svg/330px-HAL9000.svg.png"],["Q18545687",155,"mechant","Hans Gruber","C","Hans Gruber est le méchant du film Piège de cristal (1988), un voleur élégant qui prend en otage une tour de Los Angeles. Il est incarné par Alan Rickman.","","en:Hans_Gruber","https://upload.wikimedia.org/wikipedia/en/thumb/8/8b/HansGruber.jpeg/330px-HansGruber.jpeg"],["Q3043221",157,"mechant","Hela","C","Hela est une divinité et une super-vilaine évoluant dans l’univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Journey into Mystery #102 en mars 1964.","Hela est une divinité et une super-vilaine évoluant dans l’univers Marvel de la maison d'édition Marvel Comics.","fr:Hela_(Marvel_Comics)","c:9/90/Hela_%283953996709%29.jpg"],["Q1049890",158,"mechant","Homme-sable","C","William Baker, alias l'Homme-sable est un super-vilain évoluant dans l'univers Marvel de la maison d’édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #4 en septembre 1963.",115,"fr:Homme-sable","c:3/35/NYCC_2016_-_Sandman_%2829954188370%29.jpg"],["Q7070198",159,"mechant","Infirmière Ratched","PC","L'infirmière Ratched, également connue sous le nom de Mildred Ratched au cinéma et à la télévision et surnommée Big Nurse en version originale, est un personnage de fiction créé par Ken Kesey dans le roman Vol au-dessus d'un nid de coucou en 1962.",115,"fr:Infirmière_Ratched","c:8/89/Louise_Fletcher_1959_crop.jpg"],["Q366957",161,"mechant","Jason Voorhees","M","Jason Voorhees est un personnage fictif né avec une tête hydrocéphale adapté au cinéma par Victor Miller, Ron Kurz, Sean S. Cunningham et Tom Savini dans le film Vendredi 13 réalisé par Sean S. Cunningham en 1980. Il est le fils d'une cuisinière du camp Crystal Lake et devenu meurtrier. Jason Voorhees a également été représenté dans de nombreux romans, bandes dessinées, et un crossover avec un autre personnage des films d'horreur, Freddy Krueger.",115,"fr:Jason_Voorhees","c:2/2c/Jason_-_Zombie_Walk_2014_-_16112014_%2815683501399%29.jpg",{"cats":["heros","horreur"]}],["Q1985548",162,"mechant","Jigsaw","PC","John Kramer, ou Jigsaw, est un personnage de fiction, à la fois personnage central et principal antagoniste de la série de films d'horreur Saw créée par James Wan et Leigh Whannell.",119,"fr:Jigsaw_(personnage)","c:9/9e/Bell%2C_Tobin_%282007%29.jpg",{"cats":["heros","horreur"]}],["Q2053078",164,"mechant","Julius No","C","Le Docteur Julius No est un personnage de la série James Bond, que celui-ci affronte dans le roman de 1958 Docteur No et son adaptation cinématographique de 1962, James Bond 007 contre Dr No, le premier film issu d'un roman d'Ian Fleming.",117,"fr:Julius_No","https://upload.wikimedia.org/wikipedia/en/thumb/6/6c/DrJuliusNo.jpg/330px-DrJuliusNo.jpg"],["Q1982051",165,"mechant","Kang le conquérant","R","Nathaniel Richards, alias Kang le conquérant est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Jack Kirby, le personnage de fiction apparaît pour la première fois dans le comic book Fantastic Four #19 en octobre 1963.",118,"fr:Kang_le_conquérant","c:4/44/Dragon_Con_2013_-_Kang_the_Conqueror_%289697497164%29.jpg"],["Q974336",166,"mechant","Killer Croc","C","Killer Croc est un personnage de fiction, super-vilain de l'univers de DC Comics. Créé par Gerry Conway et Don Newton, il apparaît pour la première fois dans le comic Detective Comics #523 en 1983. Sa véritable identité est Waylon Jones, un homme atteint d'une maladie de peau qui recouvre son corps d'écailles. Par la suite, sa physionomie évolue pour s'approcher de celle d'un crocodile anthropomorphe de grande taille.","Killer Croc est un personnage de fiction, super-vilain de l'univers de DC Comics.","fr:Killer_Croc","c:f/f3/Killer_Croc_%28Cosplay_March_29_2014%29.jpg"],["Q654588",167,"mechant","Kraven le chasseur","R","Serguei Kravinoff, alias Kraven le chasseur est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #15 en août 1964.",117,"fr:Kraven_le_chasseur_(Serguei_Kravinoff)","c:3/3b/SDCC_-_Kraven_the_Hunter_Cosplay_%2835308456084%29.jpg"],["Q21515016",168,"mechant","Kylo Ren","PC","Ben Solo, alias Kylo Ren, est un personnage de fiction de l'univers de Star Wars, apparu pour la première fois dans le film Le Réveil de la Force, premier épisode de la troisième trilogie. Il y fait office de principal antagoniste en tant que leader des Chevaliers de Ren, puis Suprême leader du Premier Ordre, statut qui fait de lui le successeur de Dark Vador, méchant emblématique de la trilogie originale — qui n'est autre que son grand-père.",118,"fr:Kylo_Ren","c:f/f2/Cosplay_of_Kylo_Ren_at_Japan_Expo_2023_%2853056183168%29.jpg"],["Q104880994",169,"mechant","Le Protecteur","R","John Gillman, alias Le Protecteur, est le principal antagoniste de la série de bandes dessinées The Boys ainsi que de la franchise associée, créée par Garth Ennis et Darick Robertson. Chef des « Sept », un groupe de super-héros corrompus et hédonistes financés par Vought International, le Protecteur est un personnage narcissique, égoïste et sadique qui se masque sous une image publique de héros noble et altruiste.",117,"fr:Le_Protecteur_(comics)","c:d/da/Homelander_in_Mortal_Kombat_1.png"],["Q1647348",170,"mechant","Leatherface","E","Leatherface est un personnage de fiction créé par Tobe Hooper et Kim Henkel dans le film Massacre à la tronçonneuse en 1974.",118,"fr:Leatherface","c:b/bf/Leatherface_1974.jpg",{"cats":["heros","horreur"]}],["Q19382",173,"mechant","Lézard","C","Curtis « Curt » Connors, alias le Lézard est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #6 en novembre 1963.",114,"fr:Lézard_(comics)","c:c/cb/SDCC_2012_cosplay_%287574223270%29.jpg"],["Q31378",174,"mechant","M. Bison","L","M. Bison, surnommé Dictator en tournoi et Vega au Japon, est l'un des personnages et antagonistes principaux issus de la franchise Street Fighter, éditée par Capcom. Boss final des opus 2, alpha 3 et 5, il exploite à mauvais escient les pouvoirs extraordinaires de télékinésie dont il est doté.","M.","fr:M._Bison","c:5/5e/Wondercon_2016_-_M._Bison_Cosplay_%2826014569031%29.jpg"],["Q2021531",177,"mechant","Monstre de Frankenstein","R","Le Monstre de Frankenstein ou la créature de Frankenstein est un personnage de fiction qui apparaît pour la première fois en 1818 dans le roman de Mary Shelley Frankenstein ou le Prométhée moderne. Il s'agit d'un être artificiel créé par le savant Victor Frankenstein à l'aide d'un assemblage de cadavres ramené ensuite à la vie.",116,"fr:Monstre_de_Frankenstein","c:a/a7/Frankenstein%27s_monster_%28Boris_Karloff%29.jpg",{"cats":["heros","horreur"]}],["Q18152783",178,"mechant","Mère Gothel","C","Mère Gothel est la méchante de Raiponce (Disney, 2010), qui enlève la princesse pour profiter du pouvoir de jouvence de ses cheveux magiques.","","en:Mother_Gothel","https://upload.wikimedia.org/wikipedia/en/thumb/f/fc/Gothel.png/330px-Gothel.png"],["Q737236",180,"mechant","Mystique","PC","Raven Darkhölme, alias Mystique, est une super-vilaine évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur Jim Mooney, le personnage de fiction apparaît pour la première fois dans le comic book Ms. Marvel #17 en juin 1978.",115,"fr:Mystique_(comics)","c:f/f3/Brasil_Game_Show_2016_%2829381528591%29.jpg"],["Q2283843",181,"mechant","Mystério","C","Mystério est le nom de plusieurs super-vilains successifs évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book Amazing Spider-Man #13 en juin 1964.",118,"fr:Mystério","c:e/e3/New_York_Comic_Con_2013_-_Mysterio_%2810275729573%29.jpg"],["Q828473",182,"mechant","Mégatron","C","Megatron est le chef des Decepticons, les principaux antagonistes de la franchise Transformers.",null,"fr:Mégatron","c:e/e4/Cosplay_of_Megatron_at_Animagic_2007.jpg",{"cats":["heros","persos_anim"]}],["Q3352056",184,"mechant","Omni-Man","C","Omni-Man est un personnage du comic Invincible. Il est 93e du classement IGN des Super-vilains.","Omni-Man est un personnage du comic Invincible.","fr:Omni-Man","c:e/eb/Omni-Man_in_Mortal_Kombat_1.png"],["Q51770",185,"mechant","Palpatine","R","Sheev Palpatine, alias Dark Sidious, ou Darth Sidious dans les versions originale et québécoise, est un personnage de fiction, seigneur noir des Sith, homme politique et antagoniste principal de la saga Star Wars créée par George Lucas. D'abord sénateur de Naboo, Palpatine réussit à se faire élire Chancelier suprême de la galaxie, avant de fomenter un auto-coup d'État qui lui permet de devenir Empereur de l'Empire galactique pendant vingt-cinq ans.",117,"fr:Palpatine","c:6/61/MCM_2013_-_Emperor_Palpatine_%288979536884%29.jpg"],["Q203927",186,"mechant","Patrick Bateman","PC","Patrick Bateman est le personnage principal et le narrateur du roman American Psycho de Bret Easton Ellis.",null,"fr:Patrick_Bateman","c:1/1e/ChristianBaleJun09.jpg"],["Q2518973",188,"mechant","Pinhead","L","Pinhead est un personnage de fiction créé par Clive Barker dans le roman Hellraiser en 1986. Il est l'une des plus grandes icônes du cinéma d'horreur.","Pinhead est un personnage de fiction créé par Clive Barker dans le roman Hellraiser en 1986.","fr:Pinhead","c:4/43/Special_Edition_NYC_2015_-_Pinhead_%2818519207906%29.jpg",{"cats":["heros","horreur"]}],["Q844794",190,"mechant","Predator","C","Les Predators ou Prédateurs au Québec, également appelés Yautja dans des romans, constituent une espèce extraterrestre fictive caractérisée par la pratique rituelle de la chasse aux trophées d'autres formes de vie. Initialement imaginée par les scénaristes Jim et John Thomas et conçue par l'artiste d'effets spéciaux Stan Winston, l'espèce fait sa première apparition en tant qu'antagoniste dans le film de science-fiction et d'action Predator de 1987, réalisé par John McTiernan.",118,"fr:Predator_(créature)","c:3/35/The_Predator.jpg"],["Q283111",191,"mechant","Professeur Moriarty","PC","Le professeur James Moriarty est un personnage de fiction, connu pour être le plus redoutable ennemi de Sherlock Holmes. Considéré comme l'un des premiers génies du mal de la littérature, Moriarty est un cerveau criminel que Holmes décrit comme le « Napoléon du crime ».","Le professeur James Moriarty est un personnage de fiction, connu pour être le plus redoutable ennemi de Sherlock Holmes.","fr:Professeur_Moriarty","c:5/50/Moriarty_-_Sidney_Paget.jpg"],["Q1085009",192,"mechant","Pyramid Head","R","Pyramid Head est un monstre emblématique de la série de jeux d'horreur Silent Hill, reconnaissable à son énorme casque triangulaire et à son grand couteau.","","en:Pyramid_Head","https://upload.wikimedia.org/wikipedia/en/thumb/4/4c/Pyramid_Head.jpg/330px-Pyramid_Head.jpg",{"cats":["heros","horreur","persos_jv"]}],["Q252044",194,"mechant","Reine-sorcière","C","La Reine-sorcière est un personnage de fiction, principal antagoniste du long métrage d'animation Blanche-Neige et les Sept Nains, adapté du conte éponyme des frères Grimm paru en 1812.",118,"fr:Reine-sorcière","c:6/6a/Evil_Queen_in_Disney_trailer.png"],["Q2361723",195,"mechant","Requin","C","Requin est un personnage fictif des romans, films et jeux vidéo de James Bond et un ennemi récurrent de ce dernier. Incarné au cinéma par l'acteur américain Richard Kiel, il apparaît notamment dans les films L'Espion qui m'aimait et Moonraker, ainsi que dans le jeu vidéo Quitte ou double.","Requin est un personnage fictif des romans, films et jeux vidéo de James Bond et un ennemi récurrent de ce dernier.","fr:Requin_(James_Bond)","c:8/8a/Eegah-RichardKiel2.jpg"],["Q2354107",196,"mechant","Reverse-Flash","C","Reverse-Flash est l'ennemi juré de Flash chez DC Comics : un speedster maléfique venu du futur, souvent incarné par Eobard Thawne.","","en:Reverse-Flash",""],["Q572626",197,"mechant","Rhino","C","Aleksei Sytsevich, alias le Rhino est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur John Romita, Sr., le personnage de fiction apparaît pour la première fois dans le comic book The Amazing Spider-Man #41 en octobre 1966.",114,"fr:Rhino_(comics)","c:d/dd/Rhino_cosplay_marvel.jpg"],["Q2596301",198,"mechant","Sadako Yamamura","PC","Sadako Yamamura est un personnage de fiction issu du roman Ring de l'écrivain japonais Kōji Suzuki. Elle apparaît également dans les adaptations cinématographiques du roman, ainsi que dans les adaptations en manga, anime, dramas, et a inspiré ses équivalents dans les remakes américains et coréens du film.","Sadako Yamamura est un personnage de fiction issu du roman Ring de l'écrivain japonais Kōji Suzuki.","fr:Sadako_Yamamura","https://upload.wikimedia.org/wikipedia/en/thumb/a/ad/Sadako_Yamamura_in_Ringu.png/330px-Sadako_Yamamura_in_Ringu.png",{"cats":["heros","horreur"]}],["Q649546",201,"mechant","Séphiroth","C","Séphiroth est un personnage de fiction du jeu de rôle Final Fantasy VII développé par Squaresoft. Présenté comme l'antagoniste principal, le character designer Tetsuya Nomura voulait que son rôle dans l'histoire soit différent des autres ennemis de la série Final Fantasy en faisant de son apparence un contraste avec le héros du jeu Cloud Strife.","Séphiroth est un personnage de fiction du jeu de rôle Final Fantasy VII développé par Squaresoft.","fr:Séphiroth_(Final_Fantasy)","c:9/90/Cosplay_of_Sephiroth_at_GEMA_2022.jpg",{"cats":["heros","jv","persos_jv"]}],["Q1654161",202,"mechant","Shao Kahn","C","Shao Kahn est un personnage fictif de jeu vidéo dans la série des jeux de combat Mortal Kombat.",null,"fr:Shao_Kahn","https://upload.wikimedia.org/wikipedia/en/thumb/b/b2/Shao_Kahn_2011.png/330px-Shao_Kahn_2011.png"],["Q2305638",203,"mechant","Shere Khan","C","Shere Khan est un tigre fictif, personnage du roman Le Livre de la jungle de Rudyard Kipling, ainsi que du long métrage d'animation de Walt Disney. Shere Khan est un tigre du Bengale dont le nom veut dire « seigneur tigre » en hindi/ourdou. Il est le pire ennemi de Mowgli, le héros de l'histoire.",119,"fr:Shere_Khan","c:3/38/Becque_-_Livre_de_la_jungle%2C_p35.jpeg"],["Q252662",204,"mechant","Shredder","C","Shredder, de son vrai nom Oroku Saki, est un personnage de la bande dessinée américaine des Tortues Ninja. Il s'agit aussi du chef de l'organisation connu comme le Clan des Foot. Il est l'ennemi le plus acharné des Tortues Ninja et est inlassablement repris comme tel dans toutes les incarnations de la bande dessinée depuis ses débuts.","Shredder, de son vrai nom Oroku Saki, est un personnage de la bande dessinée américaine des Tortues Ninja.","fr:Shredder","c:2/2b/San_Diego_Comic-Con_2019_-_Shredder.jpg",{"cats":["heros","persos_anim"]}],["Q2279525",205,"mechant","Sinestro","E","Sinestro est un super-vilain et un extra-terrestre originaire de Korugar appartenant à l'univers de fiction de DC Comics. Il est apparu pour la première fois dans Green Lantern Vol. 2 #7, créé par John Broome & Gil Kane.",113,"fr:Sinestro","c:6/61/WonderCon_2014_-_Sinestro_Cosplay_%2813954947165%29.jpg"],["Q127111",206,"mechant","Skeletor","C","Skeletor est un personnage fictif du dessin animé Les Maîtres de l'univers.",null,"fr:Skeletor","c:c/c0/NYCC_2018_Cosplay_of_Skeletor.jpg",{"cats":["heros","persos_anim"]}],["Q3973228",209,"mechant","Steppenwolf","C","Steppenwolf est un personnage de fiction et un super-vilain appartenant à l'univers DC. Il est créé par Jack Kirby et fait sa première apparition dans New Gods vol. 1 #7.","Steppenwolf est un personnage de fiction et un super-vilain appartenant à l'univers DC.","fr:Steppenwolf_(DC_Comics)","https://upload.wikimedia.org/wikipedia/en/thumb/9/98/Steppenwolf_Earth_2_1.png/330px-Steppenwolf_Earth_2_1.png"],["Q2327890",210,"mechant","T-1000","C","Le T-1000 est un personnage de fiction créé par James Cameron et William Wisher Jr. dans le film Terminator 2: Le Jugement dernier en 1991.","Le T-1000 est un personnage de fiction créé par James Cameron et William Wisher Jr.","fr:T-1000",""],["Q2474195",214,"mechant","Ultron","E","Ultron est un super-vilain robotique évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Roy Thomas et le dessinateur John Buscema, le personnage de fiction apparaît pour la première fois dans le comic book Avengers #54 en juillet 1968.","Ultron est un super-vilain robotique évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Ultron","c:1/18/Dragon_Con_2013_-_Ultron_%289694672339%29.jpg"],["Q2296291",215,"mechant","Vautour","C","Adrian Toomes, alias le Vautour est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Stan Lee et le dessinateur Steve Ditko, le personnage de fiction apparaît pour la première fois dans le comic book Amazing Spider-Man #2 en mai 1963.","Adrian Toomes, alias le Vautour est un super-vilain évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Vautour_(comics)","c:b/b6/NYCC_2016_-_Daredevil%2C_Scorpion_%26_Vulture_%2830235176245%29.jpg"],["Q1358109",219,"film","Aladdin","C","Aladdin est un personnage de fiction qui est apparu pour la première fois en 1992 chez Disney, dans le long métrage d'animation Aladdin. Il est inspiré du personnage homonyme, héros du conte des Mille et Une Nuits, Aladin et la Lampe merveilleuse. Le personnage apparaît dans les suites du film sorties directement en vidéo: Le Retour de Jafar et Aladdin et le Roi des voleurs, ainsi que dans plusieurs séries télévisées, dont Aladdin, et des bandes dessinées.",115,"fr:Aladdin_(Disney)","c:b/b0/Jasmine%2C_Elizabeth_and_Aladdin.jpg"],["Q15614636",220,"film","Anna","C","Anna d'Arendelle est un personnage de fiction qui est apparu pour la première fois dans le 53e Classique d'animation des studios Disney, La Reine des neiges. Elle est interprétée en version originale par Kristen Bell, et doublée par Emmylou Homs en français, et par Véronique Claveau en français canadien.",116,"fr:Anna_(Disney)","c:7/7b/Anna_Frozen_meet-and-greets_at_Disneyland%2C_November_2013.jpg"],["Q2559332",223,"film","Cendrillon","C","Cendrillon est un personnage de fiction inspiré par le personnage du conte Cendrillon ou la Petite pantoufle de verre de Charles Perrault issu de Histoires ou Contes du Temps Passé. Walt Disney avait déjà adapté le conte dans un court-métrage d'animation Cinderella de 1922, produit avec son ancienne société de production Laugh-O-Gram. Disney décide de l'adapter en long métrage d'animation Cendrillon, sorti en 1950.",117,"fr:Cendrillon_(Disney)","c:1/14/Disney070817_070.jpg"],["Q857000",231,"film","Harold et les Dragons","C","Harold et les Dragons est une série de livres pour enfants de Cressida Cowell, chez les Vikings. Elle a été adaptée en films d'animation par DreamWorks avec Harold et son dragon Krokmou.","","en:How_to_Train_Your_Dragon_(novel_series)","https://upload.wikimedia.org/wikipedia/en/thumb/7/77/How_to_Train_Your_Dragon_%282003_book_cover%29.jpg/330px-How_to_Train_Your_Dragon_%282003_book_cover%29.jpg"],["Q73823",232,"film","Harry Callahan","C","Harold Francis « Dirty Harry » Callahan est un inspecteur fictif de la police de San Francisco dans les films de la saga L'Inspecteur Harry.",115,"fr:Harry_Callahan_(personnage)","c:9/92/Dirty_Harry_USA.jpg"],["Q2708262",235,"film","Jack Skellington","R","Jack Skellington est le personnage principal du film L'Étrange Noël de monsieur Jack, inspiré de Jack-o'-lantern, sous forme d'épouvantail. Inspiré également de Jack Pumpkinhead personnage de Return to Oz, en 1985.",118,"fr:Jack_Skellington","c:7/78/NYCC_2011_-_Jack_Skellington_%286253155660%29.jpg"],["Q2071301",242,"film","Katniss Everdeen","PC","Katniss Everdeen est un personnage de fiction, héroïne et narratrice de la trilogie Hunger Games écrite par Suzanne Collins. Elle est interprétée par Jennifer Lawrence dans son adaptation cinématographique.",115,"fr:Katniss_Everdeen","c:2/2c/Katniss_Everdeen%2C_Hunger_Games.jpg"],["Q748427",244,"film","L'Âne","C","L'Âne est un âne de fiction doué de la parole et l'un des personnages principaux de la série de films Shrek. Il a 30 ans possède une compagne, une dragonne et six enfants, mi-ânes mi-dragons, surnommés les dranons.","L'Âne est un âne de fiction doué de la parole et l'un des personnages principaux de la série de films Shrek.","fr:L'Âne_(Shrek)","c:2/25/Shrek_Esel_auf_dem_Eselsbrunnen_in_Halle_Saale_-_Alter_Markt_Stra%C3%9Fenkunst_-_panoramio.jpg"],["Q2283527",245,"film","Le Chat potté","C","Le Chat Potté, ou simplement Potté est un personnage d'animation apparaissant dans les films: Shrek 2, Shrek le troisième, Shrek 4: Il était une fin et deux spin-offs consacrés à son personnage, Le Chat potté, et Le Chat potté 2: La Dernière Quête.",111,"fr:Le_Chat_potté","c:f/f3/Chat_pott%C3%A9.jpg"],["Q3735317",250,"film","Mary Poppins","C","Mary Poppins est un personnage créé par l'écrivaine australienne Pamela L. Travers et popularisé par les studios Disney dans les films Mary Poppins avec Julie Andrews dans le rôle-titre, et Le Retour de Mary Poppins de Rob Marshall avec Emily Blunt dans le rôle de Mary Poppins. Elle est apparue pour la première fois dans le roman éponyme paru en 1934. Elle est reconnaissable grâce à son célèbre parapluie.","Mary Poppins est un personnage créé par l'écrivaine australienne Pamela L.","fr:Mary_Poppins_(personnage)","c:c/c8/MaryPoppins-perfect.jpg"],["Q2442950",251,"film","Max Rockatansky","C","Maximilian Rockatansky, dit Max Rockatansky, est un personnage de fiction créé par George Miller, Byron Kennedy et James McCausland, apparaissant pour la première fois dans le film Mad Max réalisé par George Miller. Il est interprété par Mel Gibson dans les trois premiers films de la saga sortis en 1979, 1981 et 1985, puis par Tom Hardy dans Mad Max: Fury Road.",114,"fr:Max_Rockatansky","c:8/80/Long_Beach_Comic_%26_Horror_Con_2011_-_Mad_Max_%286301702996%29.jpg"],["Q835154",252,"film","Michael Corleone","PC","Michael Corleone est un personnage de fiction dans les romans de Mario Puzo et dans la trilogie de films Le Parrain réalisée par Francis Ford Coppola avec la collaboration de cet auteur. Il est interprété au cinéma par Al Pacino. Michael est le plus jeune fils de Vito Corleone, parrain d'une des cinq familles mafieuses régnant sur le crime organisé aux États-Unis.",115,"fr:Michael_Corleone","c:5/56/Al_Pacino_-_Hummel.jpg"],["Q1750842",253,"film","Morpheus","C","Morpheus est un personnage fictif de la saga cinématographique Matrix, incarné dans les trois premiers épisodes de la saga par Laurence Fishburne.",117,"fr:Morpheus_(Matrix)","c:0/05/Laurence_Fishburne_2009_-_cropped.jpg"],["Q246838",254,"film","Mulan","C","Fa Mulan, ou simplement Mulan, est un personnage de fiction qui est apparu pour la première fois dans le long métrage d'animation Mulan, en 1998.",117,"fr:Mulan_(Disney)","c:a/ae/Disneyland_meet-and-greet_Mulan.jpg"],["Q3307548",258,"film","Po Ping","C","Po Ping est un personnage de fiction apparaissant dans l'univers de Kung Fu Panda, le film d'animation américain sorti en 2008. Il est le personnage principal des quatre films.",118,"fr:Po_Ping","c:f/f9/%E5%8C%97%E4%BA%AC%E7%8E%AF%E7%90%83%E5%BD%B1%E5%9F%8E%E5%8A%9F%E5%A4%AB%E7%86%8A%E7%8C%AB%E7%9B%96%E4%B8%96%E4%B9%8B%E5%9C%B0%E5%86%85%E7%9A%84%E9%98%BF%E5%AE%9D.jpg"],["Q4902053",260,"film","Raiponce","C","La princesse Raiponce est un personnage de fiction inspiré par le personnage du conte Raiponce des frères Grimm. Elle apparut pour la première fois dans le long métrage d'animation Raiponce, en 2010. Elle fait partie de la franchise Princesses Disney.","La princesse Raiponce est un personnage de fiction inspiré par le personnage du conte Raiponce des frères Grimm.","fr:Raiponce_(Disney)","c:4/42/Raiponce_-_20150803_16h45_%2810812%29.jpg"],["Q21772117",261,"film","Rey","PC","Rey est un personnage de fiction de l'univers Star Wars. Lors de sa première apparition, dans Star Wars, épisode VII: Le Réveil de la Force, où elle tient le rôle principal, elle est une jeune pilleuse d'épaves solitaire vivant sur la planète Jakku où elle a été abandonnée enfant. Rey attend le retour de ses parents, qu'elle ne connaît pas.","Rey est un personnage de fiction de l'univers Star Wars.","fr:Rey_(Star_Wars)","c:b/b7/Rey_Palpatine_at_Madame_Tussauds_London.jpg"],["Q496437",263,"film","Sarah Connor","C","Sarah Connor est un personnage de fiction créé par James Cameron pour son film Terminator sorti en 1984. Elle est aussi l'un des personnages centraux d'autres films de la franchise Terminator: Terminator 2: Le Jugement dernier, Terminator Genisys et Terminator: Dark Fate et de la série télévisée Terminator: Les Chroniques de Sarah Connor.","Sarah Connor est un personnage de fiction créé par James Cameron pour son film Terminator sorti en 1984.","fr:Sarah_Connor_(Terminator)","c:6/6c/Linda_Hamilton_by_Gage_Skidmore.jpg"],["Q52401",264,"film","Shrek","PC","Shrek est le personnage fictif et principal de la série de films Shrek, qui contient quatre longs métrages: Shrek, Shrek 2, Shrek le troisième et Shrek 4: Il était une fin et six courts métrages: Shrek 3D, Joyeux Noël Shrek !, Shrek, fais-moi peur !, Le Cochon qui criait au loup-garou, Le Noël Shrektaculaire de l'Âne et La Star de Fort Fort Lointain. Il est présenté comme un ogre vert, qui vit seul, isolé dans son marais, jusqu'à sa rencontre avec l'Âne.",114,"fr:Shrek_(personnage)","c:a/a4/Happy_Shrek.jpg"],["Q17510536",265,"film","Blanche-Neige (Disney)","C","Blanche-Neige est la princesse du conte des frères Grimm, héroïne du premier long métrage d'animation de Disney, Blanche-Neige et les Sept Nains (1937).","","en:Snow_White_(franchise)","c:0/0f/Snow_White_2025_film_logo.png"],["Q246835",267,"film","Trinity","E","Trinity est un des personnages principaux de la saga cinématographique Matrix.",null,"fr:Trinity_(Matrix)","c:4/45/Carrie-Anne_Moss_07_TIFF.jpg"],["Q21233695",268,"film","Vaiana","C","Vaiana de Motunui est le personnage principal du film d'animation Vaiana des studios Walt Disney, sorti en 2016.",null,"en:Moana_(character)","https://upload.wikimedia.org/wikipedia/en/thumb/5/56/Moana_%28character%29.png/330px-Moana_%28character%29.png"],["Q20749440",270,"film","WALL·E","C","WALL·E est le petit robot nettoyeur solitaire du film de Pixar (2008), resté seul sur une Terre recouverte de déchets, qui tombe amoureux de la robot EVE.","","en:WALL-E_(character)","https://upload.wikimedia.org/wikipedia/en/thumb/6/68/WALL-E_%28character%29.png/330px-WALL-E_%28character%29.png"],["Q738747",271,"film","Willy Wonka","R","Willy Wonka, est un personnage de fiction du roman Charlie et la Chocolaterie de Roald Dahl, de sa suite Charlie et le Grand Ascenseur de verre et de leurs adaptations cinématographiques.",118,"fr:Willy_Wonka","c:5/5b/Willy_Wonka_cosplay.jpg"],["Q209515",273,"litterature","Aladin ou la Lampe merveilleuse","PC","Aladin ou la Lampe merveilleuse, également intitulé Histoire d’Aladdin, ou la Lampe merveilleuse d'après son titre complet ou Aladin et la Lampe merveilleuse d'après une traduction erronée, voire simplement Aladin, est un conte traditionnel arabo-perse. Conte orphelin, il ne figure pas dans les manuscrits les plus anciens du recueil Les Mille et Une Nuits. Il y a été associé à partir du XVIIIe siècle avec la traduction française du recueil par Antoine Galland qui l'augmente de plusieurs contes.",114,"fr:Aladin_ou_la_Lampe_merveilleuse","c:3/38/Aladdin_in_the_Magic_Garden_-_Project_Gutenberg_eText_14221.jpg"],["Q58190302",275,"litterature","Ali Baba et les Quarante Voleurs","PC","Ali Baba et les Quarante Voleurs est un conte oriental mis par écrit pour la première fois par Antoine Galland en 1701, lorsqu'il a traduit en français Les Mille et Une Nuits, et incorporé dans ce recueil, alors qu'il n'a jamais été présent dans les manuscrits initiaux mais à leurs côtés oralement.",119,"fr:Ali_Baba_et_les_Quarante_Voleurs","c:c/ce/Robida_-_Alibaba_couverture.jpg"],["Q1269082",276,"litterature","Alice","C","Alice est un personnage de fiction britannique qui est le protagoniste du roman pour enfants de Lewis Carroll Les Aventures d'Alice au pays des merveilles et de sa suite De l'autre côté du miroir. Enfant, à l'ère victorienne, Alice se lance involontairement dans une aventure souterraine après être accidentellement tombée par un trou de lapin dans le pays des merveilles. Par la suite, elle traverse un miroir et entre dans un monde alternatif.",113,"fr:Alice_(Alice_au_pays_des_merveilles)","c:6/63/Alice_par_John_Tenniel_04.png"],["Q944201",277,"litterature","Alonso Quichano","C","Alonso Quijano, francisé Alonso Quichano, est le véritable nom de l'hidalgo Don Quichotte, personnage de fiction espagnol du roman Don Quichotte.",112,"fr:Alonso_Quichano","c:9/9b/202_112_quijote_cap44.jpg"],["Q461606",278,"litterature","Arsène Lupin","L","Arsène Lupin est un personnage de fiction français créé par Maurice Leblanc. Ce gentleman cambrioleur est particulièrement connu pour son talent consistant à user de déguisements, à se grimer et à prendre des identités multiples pour commettre ses délits et résoudre des énigmes criminelles.","Arsène Lupin est un personnage de fiction français créé par Maurice Leblanc.","fr:Arsène_Lupin","c:0/0a/Tourn%C3%A9e_de_l%27Ath%C3%A9n%C3%A9e_-_Ars%C3%A8ne_Lupin.jpg"],["Q525777",279,"litterature","Atticus Finch","C","Atticus Finch est l'avocat intègre du roman Ne tirez pas sur l'oiseau moqueur d'Harper Lee (1960), qui défend un homme noir injustement accusé dans l'Alabama des années 1930.","","en:Atticus_Finch","c:b/b7/Gregory_Peck_To_Kill_a_Mockingbird_still.jpg"],["Q751417",281,"litterature","Big Brother","PC","Big Brother, prononcé en français, est un personnage de fiction du roman 1984 de George Orwell. L'expression « Big Brother » est depuis utilisée pour qualifier toutes les institutions ou pratiques portant atteinte aux libertés fondamentales et à la vie privée des populations ou des individus.","Big Brother, prononcé en français, est un personnage de fiction du roman 1984 de George Orwell.","fr:Big_Brother","https://upload.wikimedia.org/wikipedia/commons/thumb/7/75/1984_Social_Classes_alt.svg/330px-1984_Social_Classes_alt.svg.png"],["Q913841",283,"litterature","Bridget Jones","C","Bridget Jones est un personnage de fiction, créé par Helen Fielding. Elle apparaît en 1996 dans le roman Le Journal de Bridget Jones, puis dans ses suites, Bridget Jones: L'Âge de raison, Bridget Jones: Folle de lui et Bridget Jones Baby: Le Journal qui est un préquel du troisième livre.","Bridget Jones est un personnage de fiction, créé par Helen Fielding.","fr:Bridget_Jones","c:9/91/Miss_Potter_Premiere_%282%29.jpg"],["Q215894",284,"litterature","Candide","R","Candide ou l'Optimisme est un conte philosophique de Voltaire paru à Genève en janvier 1759. Il a été réédité vingt fois du vivant de l’auteur, ce qui en fait l'un des plus grands succès littéraires francophones. Seulement un mois après sa parution, six mille exemplaires avaient été vendus, nombre considérable pour l'époque.","Candide ou l'Optimisme est un conte philosophique de Voltaire paru à Genève en janvier 1759.","fr:Candide","c:4/4c/Candide1759.jpg"],["Q2630009",285,"litterature","Capitaine Achab","PC","Le capitaine Achab est un personnage de fiction, et le principal protagoniste du roman Moby Dick d’Herman Melville. C’est le capitaine monomaniaque du baleinier Pequod. Lors d’un précédent voyage, la baleine blanche Moby Dick a dévoré une jambe d’Achab, le laissant unijambiste, avec une prothèse faite d'ivoire. La chasse à la baleine du Pequod devient une chasse vengeresse contre Moby Dick, Achab incitant son équipage à le seconder dans sa mission fanatique.","Le capitaine Achab est un personnage de fiction, et le principal protagoniste du roman Moby Dick d’Herman Melville.","fr:Capitaine_Achab","c:8/8b/Moby_Dick_final_chase.jpg"],["Q1046049",286,"litterature","Capitaine Nemo","C","Le capitaine Nemo est un personnage de fiction créé par Jules Verne dans le roman Vingt Mille Lieues sous les mers. Il en est le personnage principal en tant que commandant du sous-marin Nautilus. Il est aussi l'un des personnages secondaires de L'Île mystérieuse et réapparaît sous les traits de Maître Volsius dans la pièce Voyage à travers l'impossible.","Le capitaine Nemo est un personnage de fiction créé par Jules Verne dans le roman Vingt Mille Lieues sous les mers.","fr:Capitaine_Nemo","c:9/9d/%27Twenty_Thousand_Leagues_Under_the_Sea%27_by_Neuville_and_Riou_027.jpg"],["Q864751",287,"litterature","Chapelier fou","C","Le Chapelier fou — ou Chapelier toqué selon certaines traductions — est un personnage de fiction qui apparaît pour la première fois lors d'un thé dans Les Aventures d'Alice au pays des merveilles de Lewis Carroll. Un personnage dessiné sous ses traits par John Tenniel apparaît sous le nom de « Hatta » dans la suite de l'histoire, De l'autre côté du miroir.",117,"fr:Chapelier_fou_(Alice_au_pays_des_merveilles)","c:0/01/%22Alice%27s_Adventures_in_Wonderland%22_by_Lewis_Carroll%2C_1907_book_cover_%28cropped%29.jpg"],["Q934013",288,"litterature","Chat du Cheshire","PC","Le chat du Cheshire est un chat tigré de fiction, qui apparaît dans le roman Les Aventures d'Alice au pays des merveilles de Lewis Carroll. Son nom est un hommage de Lewis Carroll au comté de Cheshire dans lequel il est né. Il est parfois appelé chat de Chester, d'après le nom de la capitale du comté. Il est souvent représenté avec un grand sourire.",110,"fr:Chat_du_Cheshire","c:a/ab/Tennel_Cheshire_proof.png"],["Q830561",289,"litterature","Commissaire Maigret","PC","Le commissaire Jules Maigret est un personnage de fiction, protagoniste et héros de 75 romans policiers et 28 nouvelles de Georges Simenon, publiés entre 1931 et 1972.",119,"fr:Commissaire_Maigret","c:1/12/SimenonMaigret-StudioHarcourt-1952.png"],["Q2453276",290,"litterature","Cosette","C","Cosette, surnom d'Euphrasie, est l'un des personnages du roman de Victor Hugo, Les Misérables.",null,"fr:Cosette","c:4/40/Cosette-sweeping-les-miserables-emile-bayard-1862.jpg"],["Q1048916",291,"litterature","Cyrano de Bergerac","R","Cyrano de Bergerac est l'une des pièces les plus populaires du théâtre français, et la plus célèbre de son auteur, Edmond Rostand. Librement inspirée de la vie et de l'œuvre de l'écrivain libertin Savinien de Cyrano de Bergerac, elle est représentée pour la première fois le 28 décembre 1897, au théâtre de la Porte-Saint-Martin, à Paris.",114,"fr:Cyrano_de_Bergerac_(Rostand)","c:a/a7/Coquelin_ain%C3%A9.jpg"],["Q744183",292,"litterature","D'Artagnan","C","Charles de Batz de Castelmore, dit d'Artagnan, est un mousquetaire français né entre 1611 et 1615 au château de Castelmore, près de Lupiac, en Gascogne et mort à Maastricht durant le siège de cette ville le 25 juin 1673, pendant la guerre de Hollande.",111,"fr:D'Artagnan","c:9/9a/D%E2%80%99Artagnan_-_1704.png"],["Q187349",293,"litterature","Docteur Watson","C","Le docteur Watson /ˈwat͡sən/ est un personnage de fiction créé par l'écrivain Arthur Conan Doyle. Watson est le meilleur ami du détective Sherlock Holmes et narrateur de presque toutes ses aventures, dans lesquelles il joue le plus souvent un rôle actif.","Le docteur Watson /ˈwat͡sən/ est un personnage de fiction créé par l'écrivain Arthur Conan Doyle.","fr:Docteur_Watson","c:7/77/Sherlock_Holmes_%26_Watson_-_The_Greek_Interpreter_-_Sidney_Paget.jpg"],["Q2583524",294,"litterature","Dorothy Gale","C","Dorothy Gale, aussi appelée Dorothée Gale en français, est un personnage de fiction de l'univers imaginaire d'Oz, inventé par l'auteur américain L. Frank Baum. Elle apparaît dès son premier roman, The Wonderful Wizard of Oz, et réapparaît dans nombre de ses suites. Elle est aussi le personnage principal de l'adaptation cinématographique, The Wizard of Oz, réalisée par Victor Fleming en 1939. Dans ce film, elle est incarnée par Judy Garland.",113,"fr:Dorothy_Gale","c:1/1a/Dorothy_Gale_with_silver_shoes.jpg"],["Q1952877",296,"litterature","Edmond Dantès","C","Edmond Dantès est un personnage de fiction français, héros du roman Le Comte de Monte-Cristo d'Alexandre Dumas.",null,"fr:Edmond_Dantès","c:6/61/%D0%94%D1%8E%D0%BC%D0%B0_%D0%93%D0%B0%D0%B2%D0%B0%D1%80%D0%BD%D0%B8_%D0%94%D0%B0%D0%BD%D1%82%D0%B5%D1%81_%D0%B2_1829.JPG"],["Q404121",298,"litterature","Edward Hyde","C","Edward Hyde, 1er comte de Clarendon, homme d'État et historien anglais;",null,"fr:Edward_Hyde",""],["Q6668",299,"litterature","Fifi Brindacier","R","Fifi Brindacier, de son nom complet Fifilolotte Victuaille Cataplasme Tampon Fille d'Efraïm Brindacier, est le personnage principal d'une série de romans pour enfants écrits à partir de 1945 par la romancière suédoise Astrid Lindgren.",110,"fr:Fifi_Brindacier","c:9/92/Pippi_Langkous_in_Nederland_1_%28crop%29.jpg"],["Q599351",300,"litterature","Gavroche","PC","Gavroche est un personnage du roman Les Misérables de Victor Hugo, qui prend les traits d'un enfant des rues parisien.",null,"fr:Gavroche","c:d/d5/Victor_hugo_gavroche_a_11_ans.jpg"],["Q2447542",301,"litterature","Hamlet","C","Hamlet est un protagoniste et le rôle-titre de la tragédie de William Shakespeare Hamlet. Il est Prince de Danemark, neveu de Claudius et fils du Roi Hamlet précédent roi de Danemark.","Hamlet est un protagoniste et le rôle-titre de la tragédie de William Shakespeare Hamlet.","fr:Hamlet_(personnage)","c:c/c2/Pedro_Am%C3%A9rico_-_Vis%C3%A3o_de_Hamlet.jpg"],["Q11829",302,"litterature","Hansel et Gretel","R","Hansel et Gretel, parfois intitulé Jeannot et Margot, est un conte populaire figurant parmi ceux recueillis par les frères Grimm dans le premier volume des Contes de l'enfance et du foyer.",115,"fr:Hansel_et_Gretel","c:d/d1/Hansel-and-gretel-rackham.jpg"],["Q170534",304,"litterature","Hercule Poirot","R","Hercule Poirot est un détective belge de fiction créé par la romancière anglaise Agatha Christie. Avec Miss Marple, c'est l'un des personnages les plus célèbres de la romancière, apparaissant dans 38 romans, 51 nouvelles, et deux pièces de théâtres, publiés depuis 1920. Depuis 2014, il continue ses aventures sous la plume de Sophie Hannah.","Hercule Poirot est un détective belge de fiction créé par la romancière anglaise Agatha Christie.","fr:Hercule_Poirot","c:b/b3/2011-07-26_Belgique_-_Ellezelles_-_Hercule_Poirot_002.jpg"],["Q720235",306,"litterature","Holden Caulfield","PC","Holden Caulfield est un personnage de fiction, créé par l'écrivain américain J. D. Salinger. Devenu populaire avec le roman L'Attrape-cœurs paru en 1951, il est considéré comme l'un des personnages les plus marquants de la littérature du XXe siècle.","Holden Caulfield est un personnage de fiction, créé par l'écrivain américain J.","fr:Holden_Caulfield","https://upload.wikimedia.org/wikipedia/en/thumb/5/5e/Holden_Caulfield.png/330px-Holden_Caulfield.png"],["Q2585477",307,"litterature","Javert","PC","Javert est l'un des personnages du roman Les Misérables de Victor Hugo. Cet inspecteur de police est l'ennemi juré de l’ex-forçat Jean Valjean en rupture de ban, qu'il pourchasse sans trêve. Il se suicide quand il comprend que Jean Valjean est un homme bon qui a tout fait pour se racheter, regrettant de l’avoir traqué.","Javert est l'un des personnages du roman Les Misérables de Victor Hugo.","fr:Javert","c:7/73/Javert.jpg"],["Q7048121",308,"litterature","Jay Gatsby","C","Jay Gatsby est le personnage de fiction éponyme de Gatsby le Magnifique, roman de Francis Scott Fitzgerald publié en 1925.",116,"fr:Jay_Gatsby","c:3/35/Warner_Baxter_as_Jay_Gatsby_in_The_Great_Gatsby_%281926%29_Retouched_Cropped.jpg"],["Q1156620",309,"litterature","Jean Valjean","R","Jean Valjean est l'un des principaux personnages du roman Les Misérables de Victor Hugo.",null,"fr:Jean_Valjean","c:f/fd/Monsieur_Madeleine_par_Gustave_Brion.jpg"],["Q1092632",310,"litterature","Juliette Capulet","C","Juliette Capulet est un des personnages titres de la tragédie Roméo et Juliette de William Shakespeare, l’autre protagoniste étant Roméo. Elle est la fille de 13 ans de Capulet, chef de la maison Capulet à Vérone. Le personnage a une longue histoire qui précède celle de Shakespeare.",111,"fr:Juliette_Capulet","c:7/73/John_William_Waterhouse_-_Juliet.jpg"],["Q161138",311,"litterature","La Barbe bleue","R","La Barbe bleue est un conte populaire communément dénommé Barbe bleue, dont la version la plus célèbre est celle de Charles Perrault, parue en 1697 dans Les Contes de ma mère l'Oye. C'est également le nom du personnage central du récit.",115,"fr:La_Barbe_bleue","c:9/96/Barbebleue1.jpg"],["Q661491",312,"litterature","La Esmeralda","C","La Esmeralda est l'un des principaux personnages du roman de Victor Hugo Notre-Dame de Paris, paru en 1831.",null,"fr:La_Esmeralda_(personnage)","c:f/fc/Merson_-_esmeralda-and-quasimodo-1905%281%29.jpg"],["Q11834",313,"litterature","Le Maître chat ou le Chat botté","PC","Le Maître chat ou le Chat botté est un conte franco-italien en prose racontant l'histoire d'un chat qui utilise la ruse et la tricherie pour offrir le pouvoir, la fortune et la main d'une princesse à son maître mal-né et sans-le-sou. L'auteur italien Giovanni Francesco Straparola semble avoir transcrit la plus ancienne version connue de cette histoire dans son livre Les Nuits facétieuses. La version classique de ce conte est écrite à la fin du XVIIe siècle par Charles Perrault.",119,"fr:Le_Maître_chat_ou_le_Chat_botté","c:2/24/Puss-in-Boots-1695.jpg"],["Q11838",314,"litterature","Le Petit Chaperon rouge","E","Le Petit Chaperon rouge est un conte de tradition orale d'origine française, classifié comme le conte-type 333 dans la classification Aarne-Thompson.",118,"fr:Le_Petit_Chaperon_rouge","c:9/97/Little_Red_Riding_Hood_by_Henry_Leverseege.jpg"],["Q1068229",315,"litterature","Lemuel Gulliver","C","Lemuel Gulliver est le héros et narrateur des Voyages de Gulliver de Jonathan Swift (1726), qui découvre le pays des minuscules Lilliputiens.","","en:Lemuel_Gulliver","c:4/43/Gullivers_travels.jpg"],["Q215410",316,"litterature","Les Aventures de Huckleberry Finn","PC","Les Aventures de Huckleberry Finn est un roman picaresque de l'Américain Mark Twain, paru à Londres le 4 décembre 1884 sous le titre The Adventures of Huckleberry Finn, puis à New York en février de l'année suivante sous le titre Adventures of Huckleberry Finn.",118,"fr:Les_Aventures_de_Huckleberry_Finn","c:6/61/Huckleberry_Finn_book.JPG",{"cats":["heros","livres"]}],["Q1191282",317,"litterature","Lisbeth Salander","C","Lisbeth Salander est l’une des héroïnes de la série de romans policiers Millénium de l'écrivain suédois Stieg Larsson parue en Suède dès 2005. La série est ensuite prolongée par David Lagercrantz.",117,"fr:Lisbeth_Salander","https://upload.wikimedia.org/wikipedia/en/thumb/5/5a/Noomi_Rapace_as_Lisbeth_Salander.jpg/330px-Noomi_Rapace_as_Lisbeth_Salander.jpg"],["Q193531",318,"litterature","Miss Marple","PC","Jane Marple, plus connue sous le nom de Miss Marple, est un personnage de fiction créé par la romancière Agatha Christie et l'héroïne de douze romans policiers et de vingt-sept nouvelles.",111,"fr:Miss_Marple","c:8/8b/Dame_Agatha_Mary_Clarissa_Christie_%2812438790945%29.png"],["Q19399931",319,"litterature","Moby Dick","C","Moby Dick est le cachalot blanc géant du roman d'Herman Melville (1851), traqué avec obsession par le capitaine Achab.","","en:Moby_Dick_(whale)","c:7/7b/Moby_Dick_p510_illustration.jpg"],["Q3822980",320,"litterature","Méchante sorcière de l'Ouest","C","La méchante sorcière de l'Ouest est un personnage fictif créé par l'auteur américain L. Frank Baum comme le plus important antagoniste de son roman Le Magicien d'Oz publié en 1900. Dans les romans de Baum, elle n'a pas de nom; elle est seulement appelée « sorcière » ou « méchante sorcière ». Par la suite, elle reçut plusieurs dénominations:","La méchante sorcière de l'Ouest est un personnage fictif créé par l'auteur américain L.","fr:Méchante_sorcière_de_l'Ouest","c:8/83/Wickedwitchofwest.JPG"],["Q7087902",321,"litterature","Oliver Twist","C","Oliver Twist est l'orphelin héros du roman de Charles Dickens (1838), qui tombe dans une bande de jeunes pickpockets à Londres.","","en:Oliver_Twist_(character)","c:c/cd/George_Cruikshank_Oliver_Twist.gif"],["Q3899725",322,"litterature","Percy Jackson","PC","Persée « Percy » Jackson est un personnage de fiction de la série de romans fantasy Percy Jackson créée par Rick Riordan. Il est le héros et le narrateur de l'histoire, et également un des personnages principaux de la série Héros de l'Olympe. Il apparait aussi dans la série Les Travaux d'Apollon ainsi que dans Magnus Chase et les Dieux d'Asgard. Il est interprété par Logan Lerman dans les films et par Walker Scobell dans la série.",112,"fr:Percy_Jackson_(personnage)","c:4/4d/Walker_Scobell_by_Gage_Skidmore.jpg"],["Q1500073",323,"litterature","Pere Ubu","C","Pere Ubu est un groupe américain de rock parfois improprement présenté comme jouant du art rock avant-gardiste, originaire de Cleveland dans l'Ohio.",111,"fr:Pere_Ubu","c:e/e6/Pere_Ubu_Live_Vienna_2009.jpg"],["Q2587533",324,"litterature","Phileas Fogg","C","Phileas Fogg est le héros du Tour du monde en quatre-vingts jours, roman de Jules Verne paru en 1872.",null,"fr:Phileas_Fogg","c:0/05/%27Around_the_World_in_Eighty_Days%27_by_Neuville_and_Benett_04.jpg"],["Q6502703",325,"litterature","Pinocchio","R","Pinocchio est un personnage de fiction italien, héros du roman pour enfants Les Aventures de Pinocchio, écrit en 1881 par le journaliste et écrivain Carlo Collodi",117,"fr:Pinocchio","c:6/65/Pinocchio.jpg"],["Q1750634",326,"litterature","Quasimodo","PC","Quasimodo est le personnage principal du roman Notre-Dame de Paris de Victor Hugo, publié en 1831.",null,"fr:Quasimodo_(personnage)","c:1/14/Quasimodo_%28Livre_I%2C_Chapitre_V%29%2C_2019.3.1.jpg"],["Q673361",327,"litterature","Roméo Montaigu","C","Roméo Montaigu est l'un des deux personnages principaux de Roméo et Juliette, pièce de William Shakespeare écrite en 1594 - 1595.",116,"fr:Roméo_Montaigu","c:5/55/Romeo_and_juliet_brown.jpg"],["Q928202",329,"litterature","Rouletabille","C","Joseph Joséphin, surnommé Rouletabille, est un personnage récurrent de roman policier créé par Gaston Leroux dans son roman Le Mystère de la chambre jaune publié en 1907.",117,"fr:Rouletabille","c:4/4d/Le_Myst%C3%A8re_de_la_chambre_jaune_%28couverture%29.JPG"],["Q630823",331,"litterature","Sancho Panza","C","Sancho Panza, dont le nom est orthographié dans certaines langues Sancho Pança, est un personnage de roman. C'est l'écuyer et compagnon d'aventures d'Alonso Quichano dans le livre Don Quichotte de Miguel de Cervantes.","Sancho Panza, dont le nom est orthographié dans certaines langues Sancho Pança, est un personnage de roman.","fr:Sancho_Panza","c:5/55/Monumento_a_Cervantes_%28Madrid%29_10b.jpg"],["Q4653",333,"litterature","Sherlock Holmes","L","Sherlock Holmes est un personnage de fiction britannique créé par Sir Arthur Conan Doyle dans le roman policier Une étude en rouge en 1887.",115,"fr:Sherlock_Holmes","c:4/4a/Adventures_with_Sherlock_Holmes_TD_Gallery_Jan_5-Mar_10%2C_2012.jpg"],["Q122018",334,"litterature","Sinbad le marin","PC","Sinbad le marin, en persan Sindibad (aussi épelé « Sindbad » du persan: سندباد), est un conte surtout connu grâce au recueil Les Mille et Une Nuits, dans lequel il est généralement présent. Il narre les aventures de son personnage éponyme, un marin de la ville de Bagdad du temps de la dynastie des Abbassides. Durant ses voyages dans les mers de l'est de l'Afrique et du sud de l'Asie, Sinbad vit de nombreuses aventures fantastiques.",116,"fr:Sinbad_le_marin","c:9/90/Sinbad_1.jpg"],["Q170241",335,"litterature","Tarzan","PC","Tarzan est un personnage de fiction représentant l’enfant sauvage archétypal élevé par des Grands Singes dans la jungle africaine. Ce personnage est créé par Edgar Rice Burroughs en 1912 dans le roman Tarzan of the Apes, publié pour la première fois en France en 1926 chez Fayard, sous le titre Tarzan chez les singes. 26 volumes sont sortis entre 1912 et 1995.",119,"fr:Tarzan","c:6/61/Tarzan_of_the_Apes.jpg"],["Q6787521",336,"litterature","Matilda Wormwood","C","Matilda Wormwood est la petite fille surdouée du roman Matilda de Roald Dahl (1988), qui développe des pouvoirs de télékinésie face à des adultes odieux.","","en:Matilda_Wormwood","https://upload.wikimedia.org/wikipedia/en/thumb/3/39/Matilda-Mara-Wilson.webp/330px-Matilda-Mara-Wilson.webp"],["Q944203",337,"litterature","Tom Sawyer","C","Tom Sawyer est un personnage de fiction que Mark Twain a fait apparaître en 1876 dans Les Aventures de Tom Sawyer et dans plusieurs autres œuvres ultérieures. Inspiré de la jeunesse de l'auteur et du nom de son ami Tom Sawyer Spivey, c'est un personnage qui est devenu un symbole de liberté dans la culture populaire, mais que Twain a dépeint de manière contrastée et parfois critique.",116,"fr:Tom_Sawyer","c:1/1d/Tom_Sawyer_1876_frontispiece.jpg"],["Q62879",338,"litterature","Un chant de Noël","R","Un chant de Noël, également publié en français sous les titres Cantique de Noël, Chanson de Noël ou Conte de Noël, est le premier et le plus célèbre des contes écrits par Charles Dickens. Rédigé en même temps que Martin Chuzzlewit et paru en décembre 1843 chez Chapman & Hall avec des illustrations de John Leech, il est considéré comme « son œuvre la plus parfaite ». Aussitôt, Thackeray le salue comme un « bienfait national ». Salué par les critiques comme par le public, sa popularité n'a jamais faibli.",118,"fr:Un_chant_de_Noël","c:9/99/Charles_Dickens-A_Christmas_Carol-Title_page-First_edition_1843.jpg",{"cats":["heros","livres"]}],["Q2320164",339,"litterature","Victor Frankenstein","PC","Victor Frankenstein est un personnage de fiction apparu pour la première fois dans le roman Frankenstein ou le Prométhée moderne de Mary Shelley en 1818. Il apparaît par la suite dans de nombreuses œuvres dérivées du roman.",110,"fr:Victor_Frankenstein","c:8/8d/The_Curse_Of_Frankenstein_%281957%29_trailer_-_Peter_Cushing_with_magnifying_glass.png"],["Q226822",340,"litterature","Zorro","R","Zorro — surnom qui signifie « renard » en espagnol — est un héros de fiction américain créé en 1919 par Johnston McCulley. Il apparaît pour la première fois dans le roman-feuilleton Le Fléau de Capistrano, aussi connu sous le titre Le signe de Zorro.",112,"fr:Zorro","c:a/a2/El_Zorro_y_su_parecido_en_primer_plano.jpg"],["Q53737957",341,"jeu","Aloy","C","Aloy est la protagoniste des jeux vidéo Horizon Zero Dawn sorti en 2017 et Horizon Forbidden West en 2022. Elle nait le 4 avril 3021 et est élevée par un paria du nom de Rost dans un monde post-apocalyptique luxuriant. Il l'entraîne afin qu'elle devienne une guerrière talentueuse, ce qui doit lui permettre de gagner l'Éclosion, une compétition rituelle organisée par la tribu des Noras, et de découvrir l'identité de sa mère.","Aloy est la protagoniste des jeux vidéo Horizon Zero Dawn sorti en 2017 et Horizon Forbidden West en 2022.","fr:Aloy","c:7/7a/Aloy_from_The_Frozen_Wilds_trailer.jpg",{"cats":["heros","persos_jv"]}],["Q935079",343,"jeu","Bob l'éponge","R","Bob l'éponge, communément appelé Bob, est un personnage de la série télévisée d'animation du même nom. Il apparaît pour la première fois dans l'épisode intitulé Bienvenue à bord ! diffusé aux États-Unis le 1er mai 1999. Il est doublé dans la version originale par Tom Kenny et par Sébastien Desjours en français. Bob l'éponge est conçu et réalisé par le biologiste et animateur Stephen Hillenburg peu après l'annulation à l'antenne de sa série Rocko's Modern Life en 1996.","Bob l'éponge, communément appelé Bob, est un personnage de la série télévisée d'animation du même nom.","fr:Bob_l'éponge_(personnage)","c:7/7a/SpongeBob_SquarePants_character.png"],["Q847571",344,"jeu","Bulbizarre et ses évolutions","E","Bulbizarre et ses évolutions, Herbizarre et Florizarre, sont trois espèces de Pokémon de la première génération.",null,"fr:Bulbizarre","c:6/64/Cosplay_of_Bulbasaur%2C_Anime_Expo_2010_%284837249076%29.jpg",{"cats":["heros","pokemon"]}],["Q845294",345,"jeu","Carapuce et ses évolutions","R","Carapuce et ses évolutions, Carabaffe et Tortank, sont trois espèces de Pokémon de la première génération.",null,"fr:Carapuce","c:f/fb/Bahnhof_Altbach_37.jpg",{"cats":["heros","pokemon"]}],["Q2722692",346,"jeu","Duke Nukem","C","Duke Nukem est un personnage de jeu vidéo, protagoniste d'une série de jeux d'action homonyme, créée par Todd Replogle, George Broussard, Allen Blum et Scott Miller, développeurs chez 3D Realms.",119,"fr:Duke_Nukem","c:4/45/Duke_Nukem_cosplay_at_WonderCon_2013_%288602096431%29.jpg"],["Q2250743",347,"jeu","Fantominus et ses évolutions","R","Fantominus et ses évolutions, Spectrum et Ectoplasma, sont trois espèces de Pokémon de la première génération.",null,"fr:Ectoplasma","https://upload.wikimedia.org/wikipedia/en/thumb/b/bf/Pok%C3%A9mon_Gengar_art.png/330px-Pok%C3%A9mon_Gengar_art.png",{"cats":["heros","pokemon"]}],["Q2480066",348,"jeu","Goinfrex et Ronflex","R","Goinfrex et son évolution Ronflex sont deux espèces de Pokémon.",null,"fr:Ronflex","c:4/49/MAGFest_IMG_8541_%2832102985541%29.jpg",{"cats":["heros","pokemon"]}],["Q840368",349,"jeu","Jill Valentine","E","Jill Valentine est un personnage de la série vidéo-ludique Resident Evil, née en 1974.",null,"fr:Jill_Valentine","c:9/93/Julia_Voth_as_Jill_Valentine_crop.jpg",{"cats":["heros","horreur","persos_jv"]}],["Q904189",350,"jeu","Knuckles","PC","Knuckles the Echidna est un personnage de jeu vidéo de la série Sonic the Hedgehog. C'est un échidné rouge de 16 ans doté de dreadlocks. Knuckles est le gardien de l'île flottante d'Angel Island et de l'émeraude mère. Il possède des gants à pointes, ce qui lui permet de détruire certaines choses comme des piliers de pierre, mais aussi de grimper dans les murs. Il est ami et aussi rival de Sonic dans certains jeux.","Knuckles the Echidna est un personnage de jeu vidéo de la série Sonic the Hedgehog.","fr:Knuckles","c:c/c4/Knuckles_sculpture_in_Cin%C3%A9polis.png",{"cats":["heros","persos_jv"]}],["Q223684",351,"jeu","Lara Croft","E","Lara Croft est un personnage de fiction et la protagoniste de la série de jeux vidéo Tomb Raider et de sa série dérivée Lara Croft, dont la franchise appartient à Crystal Dynamics, et anciennement Eidos Interactive puis Square Enix. Lara Croft est présentée comme une archéologue belle, intelligente et athlétique, qui s'aventure de par le monde dans d'anciennes tombes ou ruines pleines de danger.",119,"fr:Lara_Croft","c:c/cd/Alison_Carroll_20080926_Festival_du_jeu_video_01.jpg",{"cats":["heros","jv","persos_jv"]}],["Q26183101",352,"jeu","Personnages de Peppa Pig","C","Les personnages de Peppa Pig, série d'animation britannique pour les tout-petits, réunissent Peppa, son petit frère George, Papa et Maman Pig et leurs amis animaux.","","en:List_of_Peppa_Pig_characters","c:8/84/PeppaPigAldridge2009.jpg"],["Q12379",353,"jeu","Mario","E","Mario est un personnage de jeu vidéo devenu la mascotte de Nintendo, facilement reconnaissable à sa moustache, à sa salopette bleue, à ses gants blancs et à sa casquette rouge marquée d'un M rouge inscrit dans un cercle blanc.",115,"fr:Mario_(personnage)","c:1/1f/JR-West_323_USJ_Super_Nintendo_World.jpg",{"cats":["heros","jv","persos_jv"]}],["Q2141803",354,"jeu","Mewtwo","E","Mewtwo est une espèce de Pokémon, créature de fiction appartenant à la franchise médiatique japonaise Pokémon. Sorte de « boss de fin » de la première génération de la franchise, il en est demeuré un symbole charismatique.","Mewtwo est une espèce de Pokémon, créature de fiction appartenant à la franchise médiatique japonaise Pokémon.","fr:Mewtwo","c:b/b4/Cosplay_of_Mewto_from_Pok%C3%A9mon_at_Anime_North_2013_%288860470787%29.jpg",{"cats":["heros","pokemon"]}],["Q9351",356,"jeu","Pikachu","M","Pikachu est une espèce de Pokémon, une créature de fiction issue de la franchise médiatique Pokémon de Nintendo. Il apparaît la première fois au Japon en 1996, dans les jeux vidéo Pokémon Bleu et Pokémon Rouge, créés par Satoshi Tajiri. Initialement conçu comme un personnage secondaire, Pikachu devient la mascotte de l'univers Pokémon après avoir été choisi comme personnage principal dans l'adaptation télévisuelle du jeu, aux côtés de son dresseur Sacha.","Pikachu est une espèce de Pokémon, une créature de fiction issue de la franchise médiatique Pokémon de Nintendo.","fr:Pikachu","c:a/a3/Cosplay_of_Pikachu%2C_Fanime_2015_%2818125488996%29.jpg",{"cats":["heros","jv","pokemon","persos_jv"]}],["Q72769780",357,"jeu","Sans","PC","Sans est un squelette farceur du jeu Undertale (2015), frère de Papyrus. Paresseux et blagueur en apparence, il cache un des combats les plus redoutables du jeu.","","en:Sans_(Undertale)","https://upload.wikimedia.org/wikipedia/en/thumb/3/3e/Undertale_Sans.png/330px-Undertale_Sans.png",{"cats":["heros","indie"]}],["Q120986062",358,"jeu","Ratchet et Clank","C","Ratchet et Clank sont le duo héros de la série de jeux vidéo d'Insomniac Games lancée en 2002 : un Lombax mécanicien et son petit robot intelligent.","","en:Ratchet_and_Clank_(characters)","https://upload.wikimedia.org/wikipedia/en/thumb/c/c0/Ratchet_%26_Clank_%282021%29.png/330px-Ratchet_%26_Clank_%282021%29.png"],["Q1154303",359,"jeu","Riolu et Lucario","R","Riolu et son évolution Lucario sont deux espèces de Pokémon de quatrième génération.",null,"fr:Lucario","c:e/e1/Lucario_Cosplay.png",{"cats":["heros","pokemon"]}],["Q844940",360,"jeu","Salamèche et ses évolutions","R","Salamèche et ses évolutions, Reptincel et Dracaufeu, sont trois espèces de Pokémon de première génération.",null,"fr:Dracaufeu","c:5/58/Anime_Expo_2013_-_Charmander_Cosplay_%289228423198%29.jpg",{"cats":["heros","pokemon"]}],["Q3178753",361,"jeu","Dracaufeu","R","Salamèche et ses évolutions, Reptincel et Dracaufeu, sont trois espèces de Pokémon de première génération.",null,"fr:Salamèche","c:5/58/Anime_Expo_2013_-_Charmander_Cosplay_%289228423198%29.jpg",{"cats":["heros","pokemon"]}],["Q901323",362,"jeu","Scooby-Doo","PC","Scoobert-Doo, dit Scooby-Doo, est un personnage de fiction créé en 1969 par Iwao Takamoto, Joe Ruby et Ken Spears pour les studios Hanna-Barbera.",118,"fr:Scooby-Doo_(personnage)","c:5/51/Scooby_Doo_and_Daphne_Dancing.gif",{"cats":["heros","persos_anim"]}],["Q191626",364,"jeu","Sonic","E","Sonic, ou Sonic le Hérisson, est le personnage principal de la série de jeux vidéo Sonic the Hedgehog éditée par Sega. C'est un hérisson bleu qui a le pouvoir de courir à une vitesse supersonique et de se recroqueviller en une boule pour attaquer ses ennemis.","Sonic, ou Sonic le Hérisson, est le personnage principal de la série de jeux vidéo Sonic the Hedgehog éditée par Sega.","fr:Sonic","c:6/6e/Modern_Sonic.png",{"cats":["heros","jv","persos_jv"]}],["Q1753198",365,"jeu","Toudoudou et ses évolutions","R","Toudoudou et ses évolutions Rondoudou et Grodoudou sont trois espèces de Pokémon.",null,"fr:Rondoudou","c:0/00/View_of_Jigglypuff_street_art_on_Nile_Street_-_geograph.org.uk_-_6804560.jpg",{"cats":["heros","pokemon"]}],["Q15622224",366,"jeu","Trevor Philips","R","Trevor Philips est un personnage du jeu Grand Theft Auto V, figurant parmi les trois protagonistes du cinquième épisode de la série Grand Theft Auto.",119,"fr:Trevor_Philips","c:7/78/Steven_Ogg.png",{"cats":["heros","persos_jv"]}],["Q598503",367,"jeu","Vil Coyote","C","Vil Coyote est un personnage de dessin animé de la série Looney Tunes et Merrie Melodies, créé par Chuck Jones en septembre 1949. Le personnage apparaît pour la première fois dans le court-métrage Vite fait, mal fait aux côtés de son éternelle proie Bip-Bip.",113,"fr:Vil_Coyote","",{"cats":["heros","persos_anim"]}],["Q1263559",368,"jeu","Évoli et ses évolutions","R","Évoli et ses évolutions, Aquali, Voltali, Pyroli, Mentali, Noctali, Phyllali, Givrali et Nymphali, parfois désignés ensemble comme les évolitions, sont neuf espèces de Pokémon.",115,"fr:Évoli","c:7/7b/Pokemon_Eevee_Cosplayers_at_Animefest_2016.jpg",{"cats":["heros","pokemon"]}],["Q2349069",369,"film","Addison Forbes-Montgomery","E","Dr Addison Adrianne Forbes-Montgomery est un personnage de la série télévisée américaine Grey's Anatomy, puis dans son spin-off: Private Practice. C'est une obstétricienne renommée et titulaire. Elle fait sa première apparition dans le final de la saison 1 de Grey's Anatomy quand elle surprend Derek Sheperd et Meredith Grey.",118,"fr:Addison_Forbes-Montgomery","c:4/40/Kate_Walsh_2011_crop.jpg"],["Q22283579",370,"film","Adonis Creed","PC","Adonis Johnson Creed est un personnage fictif de la saga Creed, dérivée de la saga Rocky. Il est interprété par Michael B. Jordan.","Adonis Johnson Creed est un personnage fictif de la saga Creed, dérivée de la saga Rocky.","fr:Adonis_Creed","https://upload.wikimedia.org/wikipedia/en/thumb/c/c1/Donnie_Creed.jpg/330px-Donnie_Creed.jpg"],["Q2463192",371,"film","Adriana La Cerva","E","Adriana La Cerva, interprétée par Drea de Matteo, est un personnage fictif de la série télévisée d'HBO Les Soprano.",null,"fr:Adriana_La_Cerva","c:2/2b/Adriana_La_Cerva_%28The_Sopranos_Family_Tree%29.jpg"],["Q3390587",372,"film","Agent J","C","L'agent J est l'un des deux héros de la saga Men in Black. Recruté par l'agent K, ce policier plein d'énergie devient agent des MIB, chargés de surveiller les extraterrestres sur Terre. Il est joué par Will Smith.","L'agent J est l'un des deux héros de la saga Men in Black.","en:Agent_J","https://upload.wikimedia.org/wikipedia/en/thumb/e/ee/Agent_J_MIB11.jpg/330px-Agent_J_MIB11.jpg"],["Q2071077",373,"film","Agent K","C","Kevin \"K\" Brown, alias Agent K, est un personnage de fiction apparaissant dans Men in Black.",null,"fr:Agent_K","https://upload.wikimedia.org/wikipedia/en/thumb/9/95/Tommy-lee-jones-as-agent-k-in-men-in-black.jpg/330px-Tommy-lee-jones-as-agent-k-in-men-in-black.jpg"],["Q2543708",374,"film","Alan Grant","C","Le Dr Alan Grant est un personnage de fiction de la franchise Jurassic Park.",null,"fr:Alan_Grant_(Jurassic_Park)","c:6/61/Sam_Neill_2010.jpg"],["Q2483201",375,"film","Alex Karev","E","Alex Karev est un personnage de fiction issu de la série télévisée américaine, Grey's Anatomy. Il est interprété par l'acteur américain Justin Chambers. Il est présent de la saison 1 jusqu'au milieu de la saison 16. Son départ de la série fut une surprise pour les téléspectateurs.","Alex Karev est un personnage de fiction issu de la série télévisée américaine, Grey's Anatomy.","fr:Alex_Karev","c:3/3c/JustinChambersMay09.jpg"],["Q2340324",376,"film","Alexander Harris","C","Alexander Lavelle Harris est un personnage de fiction de la série télévisée Buffy contre les vampires, interprété par l'acteur Nicholas Brendon et doublé en version française par Mark Lesser. C'est l'un des personnages les plus importants de la série, étant au générique de tous les épisodes et apparaissant dans tous, à l'exception de Connivences.",117,"fr:Alexander_Harris","c:5/55/Nicholas_Brendon_Aug_2004.jpg"],["Q621798",377,"film","Alexander Mahone","C","Alexander Mahone est un agent du FBI, joué par William Fichtner. C'est un personnage fictif du feuilleton télévisé Prison Break. Il fait sa première apparition dans le premier épisode de la deuxième saison et est apparu dans tous les épisodes jusqu'à la quatrième saison, jouant un rôle important dans la série. Mahone travaille depuis quatorze ans au FBI.","Alexander Mahone est un agent du FBI, joué par William Fichtner.","fr:Alexander_Mahone","c:4/45/William_fichtner.jpg"],["Q104842117",378,"film","Alfie Solomons","PC","Alfie Solomons est un personnage de la série britannique Peaky Blinders, joué par Tom Hardy. Chef d'un gang juif de Camden Town et distillateur de rhum, il est aussi imprévisible que dangereux pour Tommy Shelby.","Alfie Solomons est un personnage de la série britannique Peaky Blinders, joué par Tom Hardy.","en:Alfie_Solomons","https://upload.wikimedia.org/wikipedia/en/thumb/3/35/Alfie_Solomons.jpg/330px-Alfie_Solomons.jpg"],["Q2706099",379,"film","Alia Atréides","E","Alia Atréides est un personnage de fiction issu du cycle de Dune de l'écrivain Frank Herbert.",null,"fr:Alia_Atréides","https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Atreides_Hawk..svg/330px-Atreides_Hawk..svg.png"],["Q10853873",380,"film","Alison DiLaurentis","C","Alison DiLaurentis est un personnage des romans Pretty Little Liars de Sara Shepard et de leur adaptation télévisée. Reine de la bande, elle disparaît mystérieusement, et ses amies commencent alors à recevoir des messages de « A ».","Alison DiLaurentis est un personnage des romans Pretty Little Liars de Sara Shepard et de leur adaptation télévisée.","fr:Alison_DiLaurentis","https://upload.wikimedia.org/wikipedia/en/thumb/1/1c/AlisonDiLaurentis.png/330px-AlisonDiLaurentis.png"],["Q1064680",381,"film","Allison Cameron","C","Allison Cameron est un personnage de fiction de la série médicale de la Fox, Dr House, qui est interprété par l'actrice américaine Jennifer Morrison. Elle est immunologiste.",119,"fr:Allison_Cameron","https://upload.wikimedia.org/wikipedia/en/thumb/b/b7/Allisoncameronpromoseason6.jpg/330px-Allisoncameronpromoseason6.jpg"],["Q3614737",382,"film","Amy Farrah Fowler","R","Amy Farrah Fowler est un personnage de fiction de la série télévisée The Big Bang Theory, interprété par Mayim Bialik.",null,"fr:Amy_Farrah_Fowler","c:5/54/Mayim_Bialik%2C_March_2018_%284116%29_%28cropped%29.jpg"],["Q967064",383,"film","Amy Pond","C","Amelia Jessica Pond, dite Amy Pond et plus tard appelée Amy Williams, est un personnage de la série télévisée britannique de science-fiction Doctor Who interprété par Karen Gillan, et par Caitlin Blackwood lorsque le personnage avait 7 ans. Amy est la première compagne du Docteur dans sa onzième incarnation.",109,"fr:Amy_Pond","c:1/1a/Karen_Gillan_by_Gage_Skidmore.jpg"],["Q128138",384,"film","Andrea Harrison","C","Andrea Harrison est un personnage de fiction apparaissant dans la série de comics The Walking Dead de Robert Kirkman, interprété par Laurie Holden dans la série télévisée éponyme. Son nom de famille est dévoilé dans le jeu vidéo The Walking Dead: Survival Instinct. Le personnage apparaît pour la première fois en 2004 dans le deuxième tome de la série de comics.",117,"fr:Andrea_Harrison","c:4/49/Laurie_Holden_2023_Publicity_Photo.jpg"],["Q768434",385,"film","Andrew Van de Kamp","C","Andrew Van de Kamp est un personnage de fiction du feuilleton Desperate Housewives. Il est joué par Shawn Pyfrom.","Andrew Van de Kamp est un personnage de fiction du feuilleton Desperate Housewives.","fr:Andrew_Van_de_Kamp","c:8/8b/Shawn_Pyfrom_at_2007_GLAAD_Awards.jpg"],["Q2860154",386,"film","Archie Andrews","PC","Archibald Andrews, surnommé Archie, est un personnage de comics de l'éditeur Archie Comics.",null,"fr:Archie_Andrews","https://upload.wikimedia.org/wikipedia/fr/thumb/5/5e/Archie_%28logo_original%29.png/330px-Archie_%28logo_original%29.png"],["Q4790146",387,"film","Aria Montgomery","C","Aria Marie Montgomery est l'un des quatre personnages principaux de la série de romans Les Menteuses, de Sara Shepard.",null,"fr:Aria_Montgomery","https://upload.wikimedia.org/wikipedia/en/thumb/f/f8/Aria_Montgomery.jpg/330px-Aria_Montgomery.jpg"],["Q2470173",388,"film","Bard","C","Bard ou Barde, surnommé « l'Archer », est un personnage du roman Le Hobbit de J. R. R. Tolkien. Cet Homme du Bourg-du-Lac, descendant des anciens seigneurs du Val, réussit l'exploit de tuer le dragon Smaug et devient par la suite le roi de la cité reconstruite du Val.","Bard ou Barde, surnommé « l'Archer », est un personnage du roman Le Hobbit de J.","fr:Bard_(Terre_du_Milieu)","https://upload.wikimedia.org/wikipedia/en/thumb/7/7e/Bard_the_Bowman.webp/330px-Bard_the_Bowman.webp"],["Q51281",389,"film","Benjamin Linus","C","Benjamin « Ben » Linus est un personnage du feuilleton télévisé Lost: Les Disparus interprété par Michael Emerson.",null,"fr:Benjamin_Linus","c:d/df/Benjamin_Linus.jpg"],["Q2900232",390,"film","Betty Cooper","PC","Elizabeth Cooper, surnommée Betty, est un personnage de comics de l'éditeur Archie Comics.",null,"fr:Betty_Cooper","https://upload.wikimedia.org/wikipedia/fr/thumb/6/6b/Betty_%28logo_original%29.png/330px-Betty_%28logo_original%29.png"],["Q2706202",391,"film","Bib Fortuna","C","Bib Fortuna est un personnage fictif de Star Wars. Originaire de Ryloth, il sert de majordome à Jabba, à Tatooine. Par la suite, il lui succède en tant que daimyo, jusqu'à ce que Boba Fett ne le tue.","Bib Fortuna est un personnage fictif de Star Wars.","fr:Bib_Fortuna","https://upload.wikimedia.org/wikipedia/en/thumb/6/65/Bib_Fortuna_%28screenshot%29.jpg/330px-Bib_Fortuna_%28screenshot%29.jpg"],["Q105198654",392,"film","Billy Butcher","PC","Billy Butcher est l'un des héros de The Boys, d'abord dans la bande dessinée de Garth Ennis et Darick Robertson puis dans la série, où il est joué par Karl Urban. Chef des Boys, il voue une haine féroce aux super-héros, et surtout au Protecteur.",116,"en:Billy_Butcher","https://upload.wikimedia.org/wikipedia/en/thumb/b/b7/Billy_Butcher.jpg/330px-Billy_Butcher.jpg"],["Q1785006",393,"film","Blair Waldorf","PC","Blair Waldorf est l'une des héroïnes de Gossip Girl, d'abord dans les romans de Cecily von Ziegesar puis dans la série télévisée, où elle est jouée par Leighton Meester. Reine autoproclamée de l'Upper East Side, elle est connue pour ses serre-têtes et ses manigances.",118,"en:Blair_Waldorf","https://upload.wikimedia.org/wikipedia/en/thumb/b/b4/GGBlaircover.jpg/330px-GGBlaircover.jpg"],["Q104215396",394,"film","Bo-Katan Kryze","C","Bo-Katan Kryze est un personnage de Star Wars. Originaire de Mandalore, elle se joint au clan appelé « Death Watch » alors que la République galactique vit un temps de crise. Elle s'oppose ensuite à l'Empire galactique et prend le contrôle de Mandalore. Après la chute de l'Empire, elle s'allie à Din Djarin face à Moff Gideon. Le personnage est interprété par Katee Sackhoff, qui lui prête sa voix dans les séries d'animation, puis apparaît en prises de vues réelles dans The Mandalorian.","Bo-Katan Kryze est un personnage de Star Wars.","fr:Bo-Katan_Kryze","c:8/8f/Cosplay_of_Bo-Katan_Kryze_at_GalaxyCon_San_Jose_2024_-_01.jpg"],["Q3643599",395,"film","Brandon Stark","C","Brandon Stark, dit Bran, est l'un des personnages principaux de la saga Le Trône de fer écrite par George R. R. Martin. Il est le fils cadet de Lord Eddard Stark et de Lady Catelyn Tully. C'est un enfant de sept ans, au début de la saga, qui rêve de devenir un jour un grand chevalier et d'intégrer la Garde royale. Son loup se nomme Été.","Brandon Stark, dit Bran, est l'un des personnages principaux de la saga Le Trône de fer écrite par George R.","fr:Brandon_Stark","c:7/76/Isaac_Hempstead_Wright_by_Gage_Skidmore_3.jpg"],["Q601836",396,"film","Bree Van de Kamp","R","Bree Van de Kamp est l'un des personnages principaux du feuilleton télévisé Desperate Housewives, interprété par Marcia Cross.",119,"fr:Bree_Van_de_Kamp","c:d/d5/Life_Ball_2014_red_carpet_080_Marcia_Cross.jpg"],["Q19803416",397,"film","Brian O'Conner","R","Brian O'Conner est un personnage de fiction et l'un des protagonistes principaux de la franchise Fast and Furious. Interprété par Paul Walker, il apparaît pour la première fois au cinéma aux côtés de l'autre protagoniste, Dominic Toretto, dans Fast and Furious. Le personnage est créé par le scénariste Gary Scott Thompson, qui s'inspire d'un article sur les courses de rue illégales paru dans le numéro de mai 1998 du magazine Vibe. C'est le réalisateur Rob Cohen qui propose directement le rôle à Paul Walker.","Brian O'Conner est un personnage de fiction et l'un des protagonistes principaux de la franchise Fast and Furious.","fr:Brian_O'Conner","c:0/07/Paul_Walker.jpg"],["Q1799459",398,"film","Buffy Summers","PC","Buffy Summers est le personnage de fiction principal du film Buffy, tueuse de vampires, de la série télévisée Buffy contre les vampires et de nombreux produits dérivés tels que romans, comics et jeux vidéo. Figure centrale de la série, qui est le principal facteur de popularité du personnage, Buffy est une lycéenne tueuse de vampires, une élue à qui des puissances mystiques ont accordé une force surnaturelle pour combattre les forces démoniaques.",115,"fr:Buffy_Summers","c:a/a0/Sarah_Michelle_Gellar_Comic-Con_2%2C_2011.jpg"],["Q2397174",399,"film","Callie Torres","R","Calliope Iphigenia Torres est un personnage de fiction de la série télévisée Grey's Anatomy interprété par Sara Ramirez. Elle apparaît pour la première fois lors de l'épisode 19 de la saison 2. Elle se spécialise en chirurgie orthopédique et son personnage se démarque assez souvent pour utiliser des techniques novatrices dans le domaine. Dans la saison 11, elle mènera avec le Dr. Owen Hunt un programme pour le vétérans de l'armée américaine concernant des membres bioniques.","Calliope Iphigenia Torres est un personnage de fiction de la série télévisée Grey's Anatomy interprété par Sara Ramirez.","fr:Callie_Torres","c:4/42/Sara_Ram%C3%ADrez3.jpg"],["Q5040238",400,"film","Carl Grimes","PC","Carl Grimes est un des personnages principaux de la série télévisée The Walking Dead. Il est interprété par Chandler Riggs et doublé en version française par Gwenaëlle Jegou, puis par Hervé Grull.","Carl Grimes est un des personnages principaux de la série télévisée The Walking Dead.","fr:Carl_Grimes","c:b/b8/Chandler_Riggs_-_2018077122146_2018-03-18_Walker_Stalker_Con_-_Sven_-_1D_X_MK_II_-_605_-_AK8I9646_%28cropped%29.jpg"],["Q674394",401,"film","Carlos Solis","C","Carlos Solis est un personnage fictif du feuilleton Desperate Housewives, interprété par Ricardo Antonio Chavira.",null,"fr:Carlos_Solis","c:8/80/Ricardo_Chavira_Cannes.jpg"],["Q2609353",402,"film","Carmela Corleone","C","Carmela Corleone est la femme de Vito Corleone et la mère de Sonny, Fredo, Michael et Connie dans Le Parrain de Mario Puzo. Dans les films de Coppola, elle est jouée par la chanteuse Morgana King.",117,"fr:Carmela_Corleone","https://upload.wikimedia.org/wikipedia/en/thumb/0/02/Carmela_Corleone.png/330px-Carmela_Corleone.png"],["Q2463185",403,"film","Carmela Soprano","R","Carmela Soprano née DeAngelis, interprétée par Edie Falco, est un personnage fictif de la série télévisée d'HBO Les Soprano.",115,"fr:Carmela_Soprano","c:c/c1/Carmela_Soprano_%28The_Sopranos_Family_Tree%29.jpg"],["Q5044499",404,"film","Carol Peletier","PC","Carol Peletier, également connue au Royaume sous le nom de \"Reine\" Carol, est un personnage principal de la bande dessinée The Walking Dead et de la série télévisée The Walking Dead où elle est interprétée par Melissa McBride et doublée en version française par Françoise Rigal. Le personnage apparaît dans le troisième numéro du premier volume de la bande dessinée et dans le troisième épisode de la première saison de la série télévisée.",113,"fr:Carol_Peletier","c:6/69/Melissa_McBride_40th_Saturn_Awards_%28cropped%29.jpg"],["Q608408",405,"film","Caroline Reynolds","C","Caroline Reynolds, jouée par Patricia Wettig, est un personnage fictif du feuilleton télévisé Prison Break.",null,"fr:Caroline_Reynolds","c:6/69/Patricia_Wettig_1989_%283%29.jpg"],["Q116761482",406,"film","Cassie Howard","C","Cassie Howard est un personnage de la série Euphoria, sur HBO, jouée par Sydney Sweeney. Lycéenne en quête d'amour, elle se retrouve au cœur de nombreux drames avec ses amies.","Cassie Howard est un personnage de la série Euphoria, sur HBO, jouée par Sydney Sweeney.","en:Cassie_Howard","https://upload.wikimedia.org/wikipedia/en/thumb/2/21/Sydney_Sweeney_as_Cassie_Howard.jpg/330px-Sydney_Sweeney_as_Cassie_Howard.jpg"],["Q2453550",407,"film","Castiel","PC","Castiel, surnommé « Cas », est un ange du Seigneur dans la série américaine Supernatural, où il est joué par Misha Collins. Apparu dans la saison 4, il devient l'un des plus fidèles alliés des frères Winchester.",114,"en:Castiel_(Supernatural)","https://upload.wikimedia.org/wikipedia/en/thumb/c/cd/Castiel_%28supernatural%29.jpg/330px-Castiel_%28supernatural%29.jpg"],["Q2941743",408,"film","Catelyn Stark","C","Catelyn Stark est l'un des personnages principaux de la saga Le Trône de fer écrite par George R. R. Martin. Elle est l'épouse de lord Eddard Stark avec qui elle a cinq enfants, Robb, Sansa, Arya, Bran et Rickon.","Catelyn Stark est l'un des personnages principaux de la saga Le Trône de fer écrite par George R.","fr:Catelyn_Stark","c:f/fe/Michelle_Fairley.jpg"],["Q860244",409,"film","Charles Patoshik","C","Charles Patoshik dit « le Disjoncté » est un personnage de la série télévisée américaine Prison Break. Interprété par Silas Weir Mitchell, il apparaît pour la première fois dans le troisième épisode de la première saison.","Charles Patoshik dit « le Disjoncté » est un personnage de la série télévisée américaine Prison Break.","fr:Charles_Patoshik","c:a/ae/Silas_Weir_Mitchell_at_Comic-Con_2012.jpg"],["Q51334",410,"film","Charlie Pace","C","Charlie Hieronymus Pace est un personnage fictif du feuilleton télévisé Lost: Les Disparus interprété par Dominic Monaghan.",113,"fr:Charlie_Pace","c:d/d9/Dominic_Monaghan_2003_crop.jpg"],["Q5092694",411,"film","Cheryl Blossom","C","Cheryl Blossom est un personnage de l'univers d'Archie Comics. Riche héritière à la chevelure rousse flamboyante, elle est l'une des reines du lycée dans la série Riverdale, où elle est jouée par Madelaine Petsch.","Cheryl Blossom est un personnage de l'univers d'Archie Comics.","en:Cheryl_Blossom",""],["Q1998072",412,"film","Chris Halliwell","C","Chris Halliwell est un personnage de fiction issu de la série télévisée Charmed. Il est interprété par Drew Fuller.","Chris Halliwell est un personnage de fiction issu de la série télévisée Charmed.","fr:Chris_Halliwell","c:5/59/Drew_Fuller.jpg"],["Q2336506",413,"film","Chuck Bass","C","Chuck Bass est un personnage de Gossip Girl, joué par Ed Westwick dans la série télévisée. Fils d'un riche homme d'affaires de Manhattan, d'abord simple méchant, il devient un antihéros et forme avec Blair Waldorf l'un des couples les plus célèbres de la série.","Chuck Bass est un personnage de Gossip Girl, joué par Ed Westwick dans la série télévisée.","en:Chuck_Bass","https://upload.wikimedia.org/wikipedia/en/thumb/a/a2/Chuck_Bass_Season_3.jpg/330px-Chuck_Bass_Season_3.jpg"],["Q1765307",414,"film","Clara Oswald","PC","Clara Oswald est un personnage de la série télévisée britannique de science-fiction Doctor Who interprété par Jenna Coleman. Clara est la seconde compagne du Docteur dans sa onzième incarnation, et la première de sa douzième incarnation.",115,"fr:Clara_Oswald","c:6/66/Jenna_Coleman_Peabody_2013_%28cropped%29.jpg"],["Q30111022",415,"film","Clay Jensen","C","Clay Jensen est un personnage fictif créé par l'auteur Jay Asher. Il est le personnage principal de Thirteen Reasons Why, un roman écrit pour les adolescents dans lequel une fille nommée Hannah Baker se suicide. Clay est l'un des personnages les plus importants de la série télévisée Netflix, une adaptation du roman d'Asher, intitulée 13 Reasons Why. Son rôle est interprété par l'acteur Dylan Minnette.","Clay Jensen est un personnage fictif créé par l'auteur Jay Asher.","fr:Clay_Jensen","c:0/0e/Dylan_Minnette_4_%28cropped%29.jpg"],["Q2338698",416,"film","Connie Corleone","PC","Connie Corleone est la fille cadette de Vito Corleone dans Le Parrain de Mario Puzo et dans la trilogie de Francis Ford Coppola. Elle est jouée par Talia Shire, la sœur du réalisateur, qui sera aussi Adrian dans Rocky.",119,"fr:Connie_Corleone","https://upload.wikimedia.org/wikipedia/en/thumb/4/46/Connie_Corleone.jpg/330px-Connie_Corleone.jpg"],["Q2292469",417,"film","Cordelia Chase","C","Cordelia Chase est un personnage fictif créé par Joss Whedon pour les séries télévisées Buffy contre les vampires et Angel, interprété par l'actrice Charisma Carpenter et doublé en version française par Malvina Germain. Il s'agit d'un des personnages principaux des trois premières saisons de Buffy ainsi que des quatre premières saisons d’Angel. La dernière apparition du personnage à la télévision date du centième épisode d’Angel, Le Retour de Cordelia. Cordelia apparaît aussi dans les romans et comics dérivés.",116,"fr:Cordelia_Chase","c:f/f6/Charisma_Carpenter_on_Veronica_Mars_panel_2005.jpg"],["Q14429969",418,"film","Coriolanus Snow","L","Coriolanus Snow, appelé couramment Président Snow, est un personnage de fiction de la série littéraire et cinématographique Hunger Games. Il est le personnage principal du préquel Hunger Games: La Ballade du serpent et de l'oiseau chanteur, qui raconte sa jeunesse.",105,"fr:Coriolanus_Snow","c:0/0f/Pr%C3%A9sident_Snow.webp"],["Q2339290",419,"film","Cristina Yang","R","Cristina Yang est un personnage de fiction issu de la série télévisée américaine, Grey's Anatomy qui est interprété par Sandra Oh. Elle apparait dès la première saison où elle commence son internat avec George O'Malley, Izzie Stevens, Alex Karev et Meredith Grey, qui devient sa meilleure amie. Le docteur Yang se spécialise en chirurgie cardio-thoracique, spécialité qu'elle vise dès le début de son internat.",119,"fr:Cristina_Yang","c:f/fc/Sandra_Oh_2011.jpg"],["Q55520758",420,"film","Daemon Targaryen","PC","Daemon Targaryen, surnommé « le Prince rebelle », est un personnage de l'univers du Trône de fer de George R. R. Martin. Dans la série House of the Dragon, il est joué par Matt Smith.","Daemon Targaryen, surnommé « le Prince rebelle », est un personnage de l'univers du Trône de fer de George R.","en:Daemon_Targaryen","https://upload.wikimedia.org/wikipedia/en/thumb/7/76/Daemon_Targaryen.png/330px-Daemon_Targaryen.png"],["Q5210486",421,"film","Dale Horvath","C","Dale Horvath est un personnage principal de la série télévisée The Walking Dead. Il est interprété par Jeffrey DeMunn et doublé en version française par Jean-Luc Kayser.","Dale Horvath est un personnage principal de la série télévisée The Walking Dead.","fr:Dale_Horvath","c:d/d7/Jeffrey_DeMunn_2014.jpg"],["Q2724114",422,"film","Dame Jessica","R","Dame Jessica est un personnage de fiction issu du cycle de Dune de l'écrivain Frank Herbert, apparaissant dans les romans Dune et Les Enfants de Dune.",114,"fr:Dame_Jessica","https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Atreides_Hawk..svg/330px-Atreides_Hawk..svg.png"],["Q641424",423,"film","Damon Salvatore","R","Damon Salvatore est un personnage de fiction créé par L.J. Smith dans sa série de romans le Journal d'un vampire. Il est incarné par Ian Somerhalder, dans la série télévisée éponyme.","Damon Salvatore est un personnage de fiction créé par L.J.","fr:Damon_Salvatore","c:2/26/Ian_Somerhalder_%289116499515%29_%28cropped%29.jpg"],["Q937569",424,"film","Dan Humphrey","C","Dan Humphrey est un personnage de Gossip Girl, joué par Penn Badgley dans la série. Garçon de Brooklyn et écrivain en herbe, il cache bien des secrets dans le monde doré de l'Upper East Side.","Dan Humphrey est un personnage de Gossip Girl, joué par Penn Badgley dans la série.","en:Dan_Humphrey","https://upload.wikimedia.org/wikipedia/en/thumb/8/88/Dan_Humphrey_Season_1_Promo.jpg/330px-Dan_Humphrey_Season_1_Promo.jpg"],["Q902565",425,"film","David Apolskis","C","David Apolskis, dit « l'Acrobate », est un personnage fictif de la série télévisée Prison Break joué par Lane Garrison. Il apparaît pour la première fois dans le neuvième épisode de la première saison.","David Apolskis, dit « l'Acrobate », est un personnage fictif de la série télévisée Prison Break joué par Lane Garrison.","fr:David_Apolskis",""],["Q511769",426,"film","Deadshot","PC","Deadshot est un personnage de DC Comics et un ennemi de Batman. Créé en 1959 par Bob Kane, David Vern Reed et Lew Schwartz dans Batman #59. Deadshot connait sa propre série de novembre 1998 à février 1999. Il est également membre de l'équipe de super-vilains Suicide Squad et l'un des personnages principaux du film homonyme sorti en 2016, sous les traits de Will Smith.","Deadshot est un personnage de DC Comics et un ennemi de Batman.","fr:Deadshot","c:f/fb/Fan_Expo_Canada_2016_IMG_0213.jpg"],["Q903006",427,"film","Dean Winchester","R","Dean Winchester est l'un des deux héros de la série américaine Supernatural, avec son petit frère Sam. Chasseur de démons, de fantômes et de monstres en tout genre, il sillonne les États-Unis au volant de son Impala noire de 1967. Il est interprété par Jensen Ackles.","Dean Winchester est l'un des deux héros de la série américaine Supernatural, avec son petit frère Sam.","en:Dean_Winchester","https://upload.wikimedia.org/wikipedia/en/thumb/4/45/Jensen_Ackles_as_Dean_Winchester.png/330px-Jensen_Ackles_as_Dean_Winchester.png"],["Q2309267",428,"film","Debra Morgan","PC","Debra Morgan est un des personnages principaux créé par Jeff Lindsay dans ses romans autour du personnage de Dexter Morgan. Elle est la sœur adoptive de ce dernier et la fille de Harry Morgan. Elle est agent à la police de Miami. Dans la série Dexter et sa suite dérivée Dexter: New Blood, elle est interprétée par Jennifer Carpenter. Molly Brown reprend ensuite le rôle dans la série Dexter: Original Sin, préquelle sur la jeunesse de Dexter.",115,"fr:Debra_Morgan","c:f/fb/Jennifer_Carpenter_2010.jpg"],["Q941961",429,"film","Derek Shepherd","L","Derek Christopher Shepherd, surnommé parfois Dr Mamour, est un chirurgien de fiction mis en scène dans la série télévisée américaine Grey's Anatomy et interprété par l'acteur Patrick Dempsey.",111,"fr:Derek_Shepherd","c:c/c2/Patrick_Dempsey_in_Madrid_%28Spain%29_01.jpg"],["Q51287",430,"film","Desmond Hume","C","Desmond David Hume est un personnage fictif du feuilleton télévisé Lost: Les Disparus. Il est interprété par l'acteur Henry Ian Cusick.","Desmond David Hume est un personnage fictif du feuilleton télévisé Lost: Les Disparus.","fr:Desmond_Hume","c:4/44/Henryiancusick.jpg"],["Q120262580",431,"film","Dewey Riley","R","Dwight « Dewey » Riley est un personnage de fiction et un des protagonistes de la franchise Scream. Dewey apparaît pour la première fois dans Scream en tant qu'un policier adjoint maladroit qui fait de son mieux pour gérer le premier massacre de Woodsboro. Il a été créé par Kevin Williamson et interprété par David Arquette.","Dwight « Dewey » Riley est un personnage de fiction et un des protagonistes de la franchise Scream.","fr:Dewey_Riley","c:3/36/David_Arquette_2010.jpg"],["Q2656347",432,"film","Dixième Docteur","PC","Le Dixième Docteur est la dixième incarnation du Docteur, personnage principal de la série télévisée britannique de science-fiction Doctor Who, produite par la BBC. Il est interprété par David Tennant, qui a tenu ce rôle de 2005 à 2010. Il est le deuxième écossais à jouer ce rôle, le premier étant Sylvester McCoy, qui a joué le septième Docteur entre 1987 et 1989 puis en 1996.",115,"fr:Dixième_Docteur","c:3/31/2009_07_31_David_Tennant_smile_09.jpg"],["Q54161627",433,"film","Dolores Abernathy","C","Dolores Abernathy est l'héroïne de la série de science-fiction Westworld, jouée par Evan Rachel Wood. Androïde d'un parc d'attractions sur le thème du Far West, elle prend peu à peu conscience de sa condition.","Dolores Abernathy est l'héroïne de la série de science-fiction Westworld, jouée par Evan Rachel Wood.","en:Dolores_Abernathy","https://upload.wikimedia.org/wikipedia/en/thumb/6/64/DoloresAbernathy.png/330px-DoloresAbernathy.png"],["Q2987625",434,"film","Donna Noble","C","Donna Noble est un personnage fictif de la série télévisée de science-fiction britannique Doctor Who, interprété par Catherine Tate. Ses parents sont Geoffrey et Sylvia Noble, son grand-père Wilfred Mott. Secrétaire dans le district de Chiswick à Londres, elle est l'un des compagnons du Docteur, apparaissant dans la dernière scène du dernier épisode de la deuxième saison, intitulé Adieu Rose, et dans l'épisode spécial de Noël Mariage de Noël.",116,"fr:Donna_Noble","c:7/75/Catherine_Tate_crop.jpg"],["Q14460218",435,"film","Douzième Docteur","PC","Le Douzième Docteur est la douzième incarnation du Docteur, personnage principal de la série télévisée de science-fiction Doctor Who. Il est incarné par l'acteur Peter Capaldi entre 2014 et 2017, succédant ainsi à Matt Smith, l'interprète du Onzième Docteur, lors de l'épisode de Noël L'Heure du Docteur en 2013. Il est, avec le Premier Docteur, l'incarnation la plus âgée physiquement du Docteur.",105,"fr:Douzième_Docteur","c:7/74/Peter_Capaldi_as_Doctor_Who_filming_in_Cardiff_June_2014_%28cropped%29.jpg"],["Q911563",436,"film","Duncan Idaho","R","Duncan Idaho est un personnage de fiction issu du cycle de Dune de l'écrivain Frank Herbert.",null,"fr:Duncan_Idaho","https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Atreides_Hawk..svg/330px-Atreides_Hawk..svg.png"],["Q65503952",437,"film","Dustin Henderson","C","Dustin Henderson est un personnage de la série Stranger Things de Netflix, joué par Gaten Matarazzo. Membre de la bande de Hawkins, il est drôle, malin et passionné de sciences.","Dustin Henderson est un personnage de la série Stranger Things de Netflix, joué par Gaten Matarazzo.","en:Dustin_Henderson","https://upload.wikimedia.org/wikipedia/en/thumb/b/b3/Dustin_Season_4.webp/330px-Dustin_Season_4.webp"],["Q648219",438,"film","Edie Britt","C","Edie Williams est le nom d'un personnage du feuilleton Desperate Housewives, interprété par Nicollette Sheridan.",null,"fr:Edie_Britt","c:7/71/Nicollette_Sheridan_at_the_Beowulf_premiere.jpg"],["Q2602422",439,"film","Egon Spengler","R","Egon Spengler est l'un des chasseurs de fantômes de la saga SOS Fantômes (Ghostbusters). Scientifique génial et un peu dans la lune, il est le cerveau des inventions de l'équipe. Il était joué par Harold Ramis.","Egon Spengler est l'un des chasseurs de fantômes de la saga SOS Fantômes (Ghostbusters).","en:Egon_Spengler","https://upload.wikimedia.org/wikipedia/en/thumb/3/37/Harold_Ramis_as_Egon_Spengler.jpg/330px-Harold_Ramis_as_Egon_Spengler.jpg"],["Q908634",440,"film","Elena Gilbert","PC","Elena Gilbert-Salvatore est un des personnages principaux de la série télévisée américaine Vampire Diaries, interprété par Nina Dobrev. Simple humaine, il sera révélé qu'Elena est un double de Petrova, ou Doppelgänger, un symbole complexe de la mythologie de la série. Elle se transformera en vampire à la fin de la troisième saison. Sensible, courageuse, honnête et loyale, l'évolution et la complexité d'Elena, aussi bien morale qu'amoureuse, font partie des thèmes principaux de Vampire Diaries.",118,"fr:Elena_Gilbert","c:5/5e/Nina_Dobrev_by_Gage_Skidmore_2.jpg"],["Q14916141",441,"film","Ellie Sattler","C","Le Dr Ellie Sattler est un personnage de fiction de la franchise Jurassic Park.",null,"fr:Ellie_Sattler","c:a/ae/LauraDernDec09.jpg"],["Q458019",442,"film","Emilio Barzini","C","Emilio Barzini est le grand méchant du roman Le Parrain de Mario Puzo et du film de 1972, où il est joué par Richard Conte. Chef d'une famille mafieuse rivale, il complote contre les Corleone.",116,"en:Emilio_Barzini","https://upload.wikimedia.org/wikipedia/en/thumb/a/a7/Don_emilio_barzini.jpg/330px-Don_emilio_barzini.jpg"],["Q5372163",443,"film","Emily Fields","C","Emily Catherine Fields est l'un des quatre personnages principaux de la série de romans Les Menteuses de Sara Shepard.",null,"fr:Emily_Fields","c:c/c7/Shay_Mitchell_2019_by_Glenn_Francis.jpg"],["Q2331685",444,"film","Emmett Cullen","C","Emmett Cullen est un personnage de fiction de la saga Twilight de Stephenie Meyer. Il apparaît dans les livres Fascination, Tentation, Hésitation et Révélation, ainsi que dans son roman encore inachevé Midnight Sun, et dans les films Twilight, chapitre I: Fascination, Twilight, chapitre II: Tentation, Twilight, chapitre III: Hésitation et Twilight, chapitres IV et V: Révélation.","Emmett Cullen est un personnage de fiction de la saga Twilight de Stephenie Meyer.","fr:Emmett_Cullen","c:a/a4/Kellan_Lutz%2C_2012.jpg"],["Q136264459",445,"film","Enid Sinclair","C","Enid Sinclair est un personnage de la série Mercredi de Netflix, jouée par Emma Myers. Louve-garou joyeuse et colorée, elle partage la chambre de Mercredi Addams à l'académie Nevermore et devient sa meilleure amie.","Enid Sinclair est un personnage de la série Mercredi de Netflix, jouée par Emma Myers.","en:Enid_Sinclair","https://upload.wikimedia.org/wikipedia/en/thumb/5/5a/Enid_Sinclair.png/330px-Enid_Sinclair.png"],["Q2419636",446,"film","Faith Lehane","C","Faith Lehane est un personnage fictif créé par Joss Whedon pour les séries Buffy contre les vampires, dont l'action se situe dans la ville fictive de Sunnydale, et sa série dérivée, Angel quant à elle centrée sur Los Angeles. Faith est interprétée par Eliza Dushku. C'est une Tueuse de vampires qui apparaît pour la première fois dans la saison 3 de Buffy contre les vampires. Le personnage sert à la fois de faire-valoir et d'antagoniste à l'héroïne, Buffy Summers, elle aussi Tueuse de vampires.",118,"fr:Faith_Lehane","c:e/e5/Eliza_Dushku_lk.jpg"],["Q1779543",447,"film","Felix Leiter","PC","Felix Leiter est un personnage secondaire de fiction dans les romans de James Bond écrits par Ian Fleming, ainsi que dans les films qui en sont dérivés.",116,"fr:Felix_Leiter",""],["Q2468873",448,"film","Feyd-Rautha","R","Feyd-Rautha Harkonnen, anciennement Feyd-Rautha Rabban, est un personnage de fiction issu du cycle de Dune de l'écrivain Frank Herbert, apparaissant dans le roman Dune.",109,"fr:Feyd-Rautha","https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/HarkonnenHeraldic.svg/330px-HarkonnenHeraldic.svg.png"],["Q931582",449,"film","Fredo Corleone","R","Frederico « Fredo » Corleone est un personnage de fiction du roman de Mario Puzo Le Parrain.",null,"fr:Fredo_Corleone","https://upload.wikimedia.org/wikipedia/en/thumb/e/e7/FredoCorleone.jpg/330px-FredoCorleone.jpg"],["Q20647453",450,"film","Furiosa","C","Furiosa est un personnage de fiction créé par George Miller et apparaissant la première fois dans le film Mad Max: Fury Road, dans lequel elle est interprétée par Charlize Theron.",119,"fr:Furiosa","https://upload.wikimedia.org/wikipedia/en/thumb/0/03/Furiosa_2015.jpg/330px-Furiosa_2015.jpg"],["Q846155",451,"film","Gabrielle Solis","R","Gabrielle Solis est le nom d'un personnage fictif du feuilleton Desperate Housewives, interprété par Eva Longoria.",null,"fr:Gabrielle_Solis","c:6/65/Eva_Longoria_2%2C_2011.jpg"],["Q5518297",452,"film","Gale Weathers","PC","Gale Weathers est une journaliste de la saga d'horreur Scream, jouée par Courteney Cox. Ambitieuse et sans scrupules au début, elle traque Ghostface de film en film aux côtés de Sidney Prescott.","Gale Weathers est une journaliste de la saga d'horreur Scream, jouée par Courteney Cox.","en:Gale_Weathers","https://upload.wikimedia.org/wikipedia/en/thumb/0/00/Gale_Weathers%2C_Scream_4.png/330px-Gale_Weathers%2C_Scream_4.png"],["Q2293323",453,"film","George O'Malley","E","George O'Malley est un personnage de fiction de la série Grey's Anatomy, interprété par T.R. Knight","George O'Malley est un personnage de fiction de la série Grey's Anatomy, interprété par T.R.","fr:George_O'Malley","c:d/d2/TR_Knight_cropped.jpg"],["Q5569065",454,"film","Glenn Rhee","PC","Glenn Rhee est un des personnages principaux du comic book The Walking Dead et de la série télévisée The Walking Dead. Il est interprété par Steven Yeun. Deuxième personnage que rencontre le héros Rick Grimes dès le premier album du comic et le deuxième épisode de la série, c'est un ancien livreur de pizza qui se caractérise par son intrépidité et sa faculté à se sortir des situations dangereuses.","Glenn Rhee est un des personnages principaux du comic book The Walking Dead et de la série télévisée The Walking Dead.","fr:Glenn_Rhee","c:1/1e/Steven_Yeun_2016.jpg"],["Q500477",455,"film","Gomez Addams","E","Gomez Addams est le père de la famille Addams, créée par le dessinateur Charles Addams pour le magazine The New Yorker. Excentrique et passionné, il est fou amoureux de sa femme Morticia. Il a été joué notamment par John Astin et Raúl Juliá.","Gomez Addams est le père de la famille Addams, créée par le dessinateur Charles Addams pour le magazine The New Yorker.","en:Gomez_Addams","c:5/5c/Addams-family-john-astin-gomez-press-1.jpg"],["Q2572443",456,"film","Gorge profonde","C","Gorge profonde est un personnage fictif de la série de science-fiction X-Files. Il sert d'informateur à l'agent spécial du FBI Fox Mulder, lui divulguant des informations pour l'aider dans ses enquêtes sur les cas paranormaux, appelés les « affaires non classées ». Introduit dans l'épisode homonyme, le personnage est tué au cours de l'épisode final de la première saison, Les Hybrides; cependant, il fait plusieurs apparitions plus tard par le biais de flashbacks et de visions.","Gorge profonde est un personnage fictif de la série de science-fiction X-Files.","fr:Gorge_profonde_(personnage_de_X-Files)","https://upload.wikimedia.org/wikipedia/en/thumb/8/81/DeepThroatx.jpg/330px-DeepThroatx.jpg"],["Q384546",457,"film","Gurney Halleck","R","Gurney Halleck est un personnage de fiction issu du cycle de Dune de l'écrivain Frank Herbert.",null,"fr:Gurney_Halleck","https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Atreides_Hawk..svg/330px-Atreides_Hawk..svg.png"],["Q29389300",458,"film","Hannah Baker","C","Hannah Baker est l'héroïne du roman Treize raisons de Jay Asher, adapté par Netflix dans la série 13 Reasons Why. Avant de mourir, elle enregistre des cassettes adressées aux personnes qu'elle tient pour responsables.","Hannah Baker est l'héroïne du roman Treize raisons de Jay Asher, adapté par Netflix dans la série 13 Reasons Why.","en:Hannah_Baker","https://upload.wikimedia.org/wikipedia/en/thumb/7/77/Katherine_Langford_as_Hannah_Baker.jpg/330px-Katherine_Langford_as_Hannah_Baker.jpg"],["Q973694",459,"film","Henry Pope","C","Henry Pope, interprété par Stacy Keach, est un personnage du feuilleton télévisé Prison Break.",null,"fr:Henry_Pope","c:5/52/StacyKeachMay07.jpg"],["Q687726",460,"film","Honeychile Rider","C","Honeychile « Honey » Rider est le personnage féminin du roman de James Bond: Docteur No.",null,"fr:Honeychile_Rider","https://upload.wikimedia.org/wikipedia/en/thumb/8/82/Ursula_Andress_in_Dr._No.jpg/330px-Ursula_Andress_in_Dr._No.jpg"],["Q2708105",461,"film","Howard the Duck","PC","Howard le Canard est un personnage de fiction créé par le scénariste Steve Gerber et le dessinateur Val Mayerik, appartenant à l'univers de Marvel Comics. Il apparaît pour la première fois dans Adventure into Fear no 19, publié en décembre 1973. Il est ensuite devenu le protagoniste de plusieurs séries de bandes dessinées et a été adapté au cinéma et à la télévision.",112,"fr:Howard_the_Duck","https://upload.wikimedia.org/wikipedia/en/thumb/4/4a/Howard_the_Duck.png/330px-Howard_the_Duck.png"],["Q784892",462,"film","Howard Wolowitz","PC","Howard Joel Wolowitz est un personnage de fiction de la série télévisée américaine The Big Bang Theory, diffusée depuis 2007 sur le réseau CBS; il est joué par l'acteur américain Simon Helberg. Son nom est inspiré de celui d'un programmeur connu du cocréateur de la série, Bill Prady.",119,"fr:Howard_Wolowitz","c:e/ef/Simon_Helberg_at_PaleyFest_2013.jpg"],["Q106771114",463,"film","Hughie Campbell","C","Hughie Campbell est l'un des héros de The Boys, d'abord dans la bande dessinée puis dans la série, où il est joué par Jack Quaid. Jeune homme ordinaire, il rejoint les Boys après la mort de sa petite amie, tuée par un super-héros.",117,"en:Hughie_Campbell","https://upload.wikimedia.org/wikipedia/en/thumb/6/64/Jack-Quaid-as-Hughie-Campbell.webp/330px-Jack-Quaid-as-Hughie-Campbell.webp"],["Q51333",464,"film","Hugo Reyes","C","Hugo « Hurley » Anthony Reyes est un personnage du feuilleton télévisé Lost: Les Disparus. Il est interprété par l'acteur Jorge Garcia.","Hugo « Hurley » Anthony Reyes est un personnage du feuilleton télévisé Lost: Les Disparus.","fr:Hugo_Reyes","c:d/d0/Jorgegfdl.PNG"],["Q14916129",465,"film","Ian Malcolm","C","Le Pr Ian Malcolm est un personnage de fiction dans Jurassic Park, roman de Michael Crichton paru en 1990, puis dans Le Monde perdu, la suite parue en 1995. Il est mathématicien, spécialisé dans la théorie du chaos. Prévenant du danger de ressusciter les dinosaures, il devient la principale opposition de John Hammond. Il a aussi un faible pour le Dr Ellie Sattler. C'est du reste le seul personnage qui apparaît dans les deux romans.",119,"fr:Ian_Malcolm_(Jurassic_Park)","c:d/df/Jeff_Goldblum.jpg"],["Q1067723",466,"film","Inspecteur Lestrade","C","L'inspecteur Lestrade est un personnage de fiction qui apparaît dans les romans et les nouvelles où Sir Arthur Conan Doyle met en scène les aventures de Sherlock Holmes. On ignore son prénom mais, dans la nouvelle intitulée La Boîte en carton, son initiale est un G,. Dans la série Sherlock, épisode 2 saison 2, il est appelé Greg et dans la série Elementary, il est appelé Gareth.",116,"fr:Inspecteur_Lestrade","c:2/2f/The_Adventure_of_the_Cardboard_Box_06_-_Lestrade.jpg"],["Q1407875",467,"film","Irulan","E","La princesse Irulan est un personnage de fiction issu du cycle de Dune de l'écrivain Frank Herbert.",null,"fr:Irulan","https://upload.wikimedia.org/wikipedia/commons/thumb/d/d7/CorrinoHeraldic.svg/330px-CorrinoHeraldic.svg.png"],["Q1779558",468,"film","Irène Adler","R","Irène Adler est un personnage fictif de l'univers de Sherlock Holmes écrit par Sir Arthur Conan Doyle.",null,"fr:Irène_Adler","c:7/78/A_Scandal_in_Bohemia-06.jpg"],["Q206324",469,"film","Isildur","R","Isildur est un personnage de fiction appartenant à l'univers de la Terre du Milieu de l'écrivain britannique J. R. R. Tolkien.","Isildur est un personnage de fiction appartenant à l'univers de la Terre du Milieu de l'écrivain britannique J.","fr:Isildur","https://upload.wikimedia.org/wikipedia/en/thumb/5/5a/Isildur_played_by_Harry_Sinclair.jpg/330px-Isildur_played_by_Harry_Sinclair.jpg"],["Q2263741",470,"film","Izzie Stevens","L","Isobel «Izzie» Katherine Stevens, est un personnage de fiction de la série télévisée dramatique médicale Grey's Anatomy, diffusée sur l'American Broadcasting Company aux États-Unis. Le personnage a été créé par la productrice de série Shonda Rhimes, et a été interprété par l'actrice Katherine Heigl de 2005 à 2010.",111,"fr:Izzie_Stevens","c:a/ab/Katherine_Heigl_at_27_Dresses_Premiere_6.jpg"],["Q716835",471,"film","Jacob Black","PC","Jacob Black est un personnage de fiction des livres Fascination, Tentation, Hésitation et Révélation par Stephenie Meyer. Il est décrit comme étant un Amérindien de la tribu Quileute vivant dans la réserve de La Push, près de Forks, Washington. Durant Tentation, il subit une transformation qui lui permet de se changer en loup. Il a les cheveux longs dans le premier film et courts à partir du deuxième. Il est loup garou depuis le premier film.",114,"fr:Jacob_Black","c:4/4a/Taylor_Lautner_2011_Abduction_premiere_%28cropped%29.jpg"],["Q1915132",472,"film","Jake Sully","C","Jake Sully est un personnage de l'univers fictif Avatar.",null,"fr:Jake_Sully","https://upload.wikimedia.org/wikipedia/en/thumb/a/a9/Jake_Sully.jpg/330px-Jake_Sully.jpg"],["Q51329",473,"film","James Ford","C","James Ford, dit Sawyer est un personnage du feuilleton télévisé Lost: Les Disparus. Il est interprété par l'acteur Josh Holloway.","James Ford, dit Sawyer est un personnage du feuilleton télévisé Lost: Les Disparus.","fr:James_Ford_(Lost_:_Les_Disparus)","c:1/1b/Josh_Holloway_Comic-Con_cropped.jpg"],["Q1194074",474,"film","James Whistler","C","James Whistler, joué par Chris Vance, est un personnage fictif du feuilleton télévisé Prison Break. Il fait sa première apparition dans le premier épisode de la troisième saison.","James Whistler, joué par Chris Vance, est un personnage fictif du feuilleton télévisé Prison Break.","fr:James_Whistler_(Prison_Break)","c:b/b3/Chris_Vance.PNG"],["Q496902",475,"film","James Wilson","PC","James Evan Wilson est un personnage fictif de la série télévisée Dr House. Il est interprété par Robert Sean Leonard.","James Evan Wilson est un personnage fictif de la série télévisée Dr House.","fr:James_Wilson_(Dr_House)","c:4/47/Robert_Sean_Leonard.jpg"],["Q2463175",476,"film","Jennifer Melfi","R","Dr. Jennifer Melfi, M.D., interprétée par Lorraine Bracco, est un personnage fictif de la série télévisée d'HBO Les Soprano.","Dr.","fr:Jennifer_Melfi","c:f/f6/Jennifer_Melfi_%28The_Sopranos_Family_Tree%29.jpg"],["Q85769086",477,"film","Immortan Joe","C","Joe Immortel, aussi appelé colonel Joe Moore, est un personnage fictif et le principal antagoniste du film Mad Max: Fury Road de 2015. Il est interprété par Hugh Keays-Byrne.",115,"fr:Joe_Immortel","https://upload.wikimedia.org/wikipedia/en/thumb/c/c5/ImmortanJoeMadMax.jpeg/330px-ImmortanJoeMadMax.jpeg"],["Q12900597",478,"film","Joffrey Baratheon","R","Joffrey Baratheon est un personnage fictif de la série de livres Le Trône de fer écrite par George R. R. Martin et de son adaptation télévisuelle Game of Thrones, interprété par l'acteur irlandais Jack Gleeson.","Joffrey Baratheon est un personnage fictif de la série de livres Le Trône de fer écrite par George R.","fr:Joffrey_Baratheon","c:f/f9/Jack_Gleeson_%28August_2012%29_%28headshot%29.jpg"],["Q2489",479,"film","John Doggett","C","John Doggett, interprété par Robert Patrick, est un personnage de fiction de la série télévisée X-Files.",null,"fr:John_Doggett","c:2/25/Robert_Patrick.jpg"],["Q324322",480,"film","John Hammond","C","Le Dr John Alfred Hammond est un personnage fictif de la franchise Jurassic Park. Il apparaît pour la première fois dans le roman Jurassic Park de Michael Crichton, paru en 1990 et qui a lancé la franchise. Steven Spielberg a réalisé l'adaptation cinématographique du même nom en 1993, avec Richard Attenborough dans le rôle d'Hammond.","Le Dr John Alfred Hammond est un personnage fictif de la franchise Jurassic Park.","fr:John_Hammond_(Personnage_de_fiction)","c:c/c3/RichardAttenborough07TIFF.jpg"],["Q1088616",481,"film","John Winchester","C","John Winchester est le père de Sam et Dean dans la série américaine Supernatural. Après la mort de sa femme tuée par un démon, il devient chasseur de créatures surnaturelles et élève ses fils dans ce monde. Il est joué par Jeffrey Dean Morgan.","John Winchester est le père de Sam et Dean dans la série américaine Supernatural.","en:John_Winchester_(Supernatural)","https://upload.wikimedia.org/wikipedia/en/thumb/6/63/John_winchester.jpg/330px-John_winchester.jpg"],["Q2068759",482,"film","Jor-El","C","Jor-El est un personnage de fiction appartenant à l'univers de DC Comics. Jor-El est le père biologique de Superman, et le mari de Lara. Il était un scientifique fortement respecté sur la planète Krypton avant sa destruction, un destin qu'il avait prévu, mais dont il n'avait pas pu convaincre ses collègues à temps.","Jor-El est un personnage de fiction appartenant à l'univers de DC Comics.","fr:Jor-El","https://upload.wikimedia.org/wikipedia/en/thumb/5/5d/Jor-El_%28circa_2001%29.png/330px-Jor-El_%28circa_2001%29.png"],["Q65515261",483,"film","Joyce Byers","C","Joyce Byers est un personnage de la série Stranger Things de Netflix, jouée par Winona Ryder. Mère courageuse, elle ne renonce jamais à retrouver son fils Will, quitte à décorer sa maison de guirlandes lumineuses pour lui parler.","Joyce Byers est un personnage de la série Stranger Things de Netflix, jouée par Winona Ryder.","en:Joyce_Byers","https://upload.wikimedia.org/wikipedia/en/thumb/5/54/Joyce_Byers.png/330px-Joyce_Byers.png"],["Q3188107",484,"film","Jughead Jones","PC","Forsythe P. Jones, surnommé Jughead dans la version originale ou Doudingue Jones, surnommé Tout-Dingue dans la première version française, est un personnage de la bande dessinée Archie Comics, apparu en 1941. Jughead Jones est un personnage souvent représenté avec son burger et son bonnet. Ce sont les choses qui le représentent comme le rouge pour Cheryl Blossom.","Forsythe P.","fr:Jughead_Jones","https://upload.wikimedia.org/wikipedia/fr/thumb/3/3a/Jughead_%28logo_original%29.png/330px-Jughead_%28logo_original%29.png"],["Q102402376",485,"film","Jules Vaughn","PC","Jules Vaughn est un personnage de la série Euphoria, sur HBO, jouée par Hunter Schafer. Lycéenne transgenre arrivée en ville, elle se lie d'une relation forte avec Rue.","Jules Vaughn est un personnage de la série Euphoria, sur HBO, jouée par Hunter Schafer.","en:Jules_Vaughn","https://upload.wikimedia.org/wikipedia/en/thumb/6/65/Jules_Vaughn.png/330px-Jules_Vaughn.png"],["Q594679",486,"film","Julie Mayer","C","Julie Alexandra Mayer dite Julie Mayer est le nom d'un personnage fictif du feuilleton Desperate Housewives, joué par Andrea Bowen.",117,"fr:Julie_Mayer","c:9/97/Andrea_Bowen_%282010%29.jpg"],["Q2463141",487,"film","Junior Soprano","R","Corrado John Soprano, Jr., interprété par Dominic Chianese, est un personnage fictif de la série télévisée d'HBO Les Soprano. Il est né en 1922. Surnommé « Oncle Junior », il est l'oncle de Tony Soprano.",116,"fr:Junior_Soprano","c:3/34/Junior_Soprano_%28The_Sopranos_Family_Tree%29.jpg"],["Q51307",488,"film","Kate Austen","C","Katherine « Kate » Anne Austen est un personnage fictif du feuilleton télévisé Lost: Les Disparus, interprété par l'actrice Evangeline Lilly. Son patronyme fait référence à la romancière anglaise Jane Austen.",113,"fr:Kate_Austen","c:5/50/Evangeline_Lilly-D.jpg"],["Q614506",489,"film","Katherine Mayfair","C","Katherine Mayfair est le nom d'un personnage fictif du feuilleton Desperate Housewives, interprété par Dana Delany.",null,"fr:Katherine_Mayfair","c:a/a5/Dana_Delany_2009.jpg"],["Q2471541",490,"film","Kay Adams","PC","Kay Adams est un personnage du roman Le Parrain de Mario Puzo. Petite amie puis épouse de Michael Corleone, elle découvre peu à peu la vraie nature de sa famille. Elle est jouée par Diane Keaton dans la trilogie de Coppola.","Kay Adams est un personnage du roman Le Parrain de Mario Puzo.","fr:Kay_Adams-Corleone","https://upload.wikimedia.org/wikipedia/en/thumb/2/21/Dkeatongodfather.jpg/330px-Dkeatongodfather.jpg"],["Q547306",491,"film","Kitty Pryde","E","Katherine « Kitty » Pryde est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics. Créé par le scénariste Chris Claremont et le dessinateur John Byrne, le personnage de fiction apparaît pour la première fois dans le comic book X-Men #129 en janvier 1980.","Katherine « Kitty » Pryde est une super-héroïne évoluant dans l'univers Marvel de la maison d'édition Marvel Comics.","fr:Kitty_Pryde","c:3/3a/WonderCon_2015_-_Shadowcat_%2817048782621%29_%28cropped%29.jpg"],["Q592358",492,"film","Kyle Reese","R","Kyle Reese est un personnage de fiction créé par James Cameron dans le film Terminator sorti en 1984.",null,"fr:Kyle_Reese","https://upload.wikimedia.org/wikipedia/en/thumb/8/86/Kyle_Reese.png/330px-Kyle_Reese.png"],["Q1071461",493,"film","L'homme à la cigarette","R","L'homme à la cigarette ou le fumeur est un personnage de fiction de la série télévisée X-Files, correspondant à l'archétype de l'homme en noir. Il est interprété par l'acteur William B. Davis.",111,"fr:L'homme_à_la_cigarette","https://upload.wikimedia.org/wikipedia/en/thumb/3/34/The_Smoking_Man_%28X-Files%29.jpg/330px-The_Smoking_Man_%28X-Files%29.jpg"],["Q246870",494,"film","L'Oracle","C","L'Oracle est un personnage de fiction féminin dans la série de films The Matrix créé par les Wachowski, et interprété par Gloria Foster dans le premier et le second film et Mary Alice dans le troisième film. Le personnage apparait aussi dans le jeu vidéo Enter the Matrix et le jeu de rôle en ligne massivement multijoueur The Matrix Online.",117,"fr:L'Oracle_(Matrix)","c:e/ee/MaryAlice.jpg"],["Q1063165",495,"film","L. J. Burrows","C","Lincoln Burrows Junior est un personnage fictif du feuilleton télévisé Prison Break joué par Marshall Allman. Le rôle de L.J. enfant est quant à lui interprété par Nickolas Loquercico.","Lincoln Burrows Junior est un personnage fictif du feuilleton télévisé Prison Break joué par Marshall Allman.","fr:L._J._Burrows","c:7/7f/Marshall_Allman_01.jpg"],["Q1258231",496,"film","Lawrence Kutner","PC","Lawrence Kutner est un personnage de fiction de la série médicale de la chaîne de télévision américaine Fox, Dr House. Interprété par Kal Penn, il est médecin du sport avant d'intégrer l'équipe du service de médecine diagnostique du docteur Gregory House au cours de la saison 4. Dans l'épisode 20 de la saison 5, Kutner est retrouvé mort, apparemment des suites d'un suicide, l'interprète souhaitant s'orienter vers une carrière politique.","Lawrence Kutner est un personnage de fiction de la série médicale de la chaîne de télévision américaine Fox, Dr House.","fr:Lawrence_Kutner","c:4/45/Kal_Penn_at_UMD_2008.JPG"],["Q2136439",497,"film","Le Chiffre","R","Le Chiffre est un personnage de fiction créé par Ian Fleming pour être le méchant de son premier roman de James Bond, Casino Royale, publié en 1953.",117,"fr:Le_Chiffre","c:f/f2/Mads_Mikkelsen_Cannes_2013_2.jpg"],["Q6031395",498,"film","Le Gouverneur","PC","Le Gouverneur est un personnage principal de la série télévisée The Walking Dead. Il est interprété par David Morrissey et doublé en version française par Nicolas Marié.","Le Gouverneur est un personnage principal de la série télévisée The Walking Dead.","fr:Le_Gouverneur","c:7/77/David_Morrissey_by_Gage_Skidmore.jpg"],["Q2357164",499,"film","Le Maître","PC","Le Maître est un personnage fictif de la série Doctor Who. Le Maître est, comme le Docteur, un Seigneur du Temps, mais il a choisi de faire le mal. Ennemi récurrent du Docteur, il tente de prendre possession de la Terre à de nombreuses reprises.","Le Maître est un personnage fictif de la série Doctor Who.","fr:Le_Maître_(Doctor_Who)","https://upload.wikimedia.org/wikipedia/en/thumb/e/e8/Versions_of_the_Master.png/330px-Versions_of_the_Master.png"],["Q1358761",500,"film","Peter Clemenza","PC","Le Parrain est une saga de films dramatiques du cinéma américain réalisée par Francis Ford Coppola, d'après le roman éponyme de Mario Puzo.",116,"fr:Peter_Clemenza","https://upload.wikimedia.org/wikipedia/fr/thumb/3/30/Le_Parrain_%28film%29.png/330px-Le_Parrain_%28film%29.png"],["Q558508",501,"film","Al Neri","PC","Le Parrain est une saga de films dramatiques du cinéma américain réalisée par Francis Ford Coppola, d'après le roman éponyme de Mario Puzo.",116,"fr:Al_Neri","https://upload.wikimedia.org/wikipedia/fr/thumb/3/30/Le_Parrain_%28film%29.png/330px-Le_Parrain_%28film%29.png"],["Q519957",502,"film","Carlo Rizzi","C","Le Parrain est une saga de films dramatiques du cinéma américain réalisée par Francis Ford Coppola, d'après le roman éponyme de Mario Puzo.",116,"fr:Carlo_Rizzi_(Le_Parrain)","https://upload.wikimedia.org/wikipedia/fr/thumb/3/30/Le_Parrain_%28film%29.png/330px-Le_Parrain_%28film%29.png"],["Q55194580",503,"film","Le Professeur","C","Le Professeur, de son vrai nom Sergio Marquina, est le cerveau des braquages de la série espagnole La casa de papel, joué par Álvaro Morte. C'est lui qui réunit l'équipe aux noms de villes et prévoit tout, ou presque.",116,"en:Professor_(Money_Heist)","https://upload.wikimedia.org/wikipedia/en/thumb/d/d5/Professor_%28Money_Heist%29.jpg/330px-Professor_%28Money_Heist%29.jpg"],["Q512382",504,"film","Leonard Hofstadter","PC","Le Dr Leonard Leakey Hofstadter est l’un des personnages principaux de la série télévisée américaine The Big Bang Theory, diffusée depuis 2007 sur le réseau CBS. Il est joué par l'acteur américain Johnny Galecki. Il s'agit d'un physicien expérimental diplômé de l'Université de Princeton qui vit en colocation avec le Dr Sheldon Cooper dans un immeuble situé à Pasadena, en Californie.",113,"fr:Leonard_Hofstadter","c:8/83/Johnny_Galecki_at_PaleyFest_2013.jpg"],["Q304741",505,"film","Leto Atréides II","E","Leto II Atréides est un personnage de fiction appartenant à l'univers de Dune de l'écrivain Frank Herbert. Il apparaît brièvement à la fin du roman Le Messie de Dune, puis plus largement dans Les Enfants de Dune et L'Empereur-Dieu de Dune, ce dernier roman lui faisant référence.","Leto II Atréides est un personnage de fiction appartenant à l'univers de Dune de l'écrivain Frank Herbert.","fr:Leto_Atréides_II","https://upload.wikimedia.org/wikipedia/commons/thumb/8/87/Atreides_Hawk..svg/330px-Atreides_Hawk..svg.png"],["Q2467529",506,"film","Lexie Grey","R","Alexandra « Lexie » Caroline Grey est un personnage fictif de la série américaine Grey's Anatomy. Le rôle de Lexie Grey est tenu par Chyler Leigh.","Alexandra « Lexie » Caroline Grey est un personnage fictif de la série américaine Grey's Anatomy.","fr:Lexie_Grey","c:1/15/Chyler_Leigh_at_Gala.jpg"],["Q2337146",507,"film","Lily Aldrin","C","Lily Aldrin est un des cinq personnages principaux du feuilleton How I Met Your Mother, interprété par Alyson Hannigan.",null,"fr:Lily_Aldrin","c:4/49/Alyson_Hannigan.jpg"],["Q1058601",508,"film","Lisa Cuddy","PC","Lisa Cuddy est un personnage de fiction de la série télévisée américaine Dr House. Elle est interprétée par l'actrice américaine Lisa Edelstein. Elle est dans cette série la directrice de l'hôpital fictif de Princeton-Plainsboro, dans lequel officie le docteur Gregory House.","Lisa Cuddy est un personnage de fiction de la série télévisée américaine Dr House.","fr:Lisa_Cuddy","c:a/a1/Lisa_Edelstein_recadr%C3%A9_%28cropped%29.jpg"],["Q114900",509,"film","Lori Grimes","C","Lori Grimes est un personnage principal de la série télévisée The Walking Dead. Il est interprété par Sarah Wayne Callies et doublé en version française par Gaëlle Savary de la saison 1 à la saison 3.","Lori Grimes est un personnage principal de la série télévisée The Walking Dead.","fr:Lori_Grimes","c:6/6d/Sarah_Wayne_Callies_by_Gage_Skidmore.jpg"],["Q1159541",510,"film","Luca Brasi","PC","Luca Brasi est un personnage du roman Le Parrain de Mario Puzo et du film de 1972. Tueur redouté et d'une loyauté absolue envers Vito Corleone, il « dort avec les poissons ». Il est joué par Lenny Montana, un ancien catcheur.","Luca Brasi est un personnage du roman Le Parrain de Mario Puzo et du film de 1972.","en:Luca_Brasi","https://upload.wikimedia.org/wikipedia/en/thumb/2/27/Luca_Brasi.gif/330px-Luca_Brasi.gif"],["Q536140",511,"film","Lynette Scavo","PC","Lynette Scavo est l'un des personnages principaux du feuilleton Desperate Housewives, interprété par Felicity Huffman.",null,"fr:Lynette_Scavo","c:1/17/Finale_Walk_at_The_Heart_Truths_Red_Dress_Collection_2010_cropped.jpg"],["Q246154",512,"film","M","E","M est un personnage de fiction des romans de Ian Fleming et de la saga cinématographique des James Bond, M est le directeur du Secret Intelligence Service, donc le supérieur de Bond. Fleming s'est inspiré de la personnalité d'un grand nombre de personnes qu'il a côtoyé lorsqu'il faisait partie des renseignements britanniques. M apparaît dans tous les romans et sept acteurs se sont succédé au cinéma.",113,"fr:M_(James_Bond)","c:8/8b/Judi_Dench_at_the_BAFTAs_2007_%28cropped%29.jpg"],["Q55219964",513,"film","Maeve Millay","C","Maeve Millay est un personnage de la série de science-fiction Westworld, jouée par Thandiwe Newton. Androïde tenancière de saloon, elle se réveille et cherche à s'échapper du parc.","Maeve Millay est un personnage de la série de science-fiction Westworld, jouée par Thandiwe Newton.","en:Maeve_Millay","https://upload.wikimedia.org/wikipedia/en/thumb/0/04/Thandie_Newton_as_Maeve_Millay_in_Westworld.jpg/330px-Thandie_Newton_as_Maeve_Millay_in_Westworld.jpg"],["Q6730243",514,"film","Maggie Greene","PC","Maggie Rhee, née Maggie Greene est un personnage principal de la série télévisée The Walking Dead. Elle est interprétée par Lauren Cohan et doublée en version française par Marie Giraudon.","Maggie Rhee, née Maggie Greene est un personnage principal de la série télévisée The Walking Dead.","fr:Maggie_Greene","c:7/75/Lauren_Cohan_by_Gage_Skidmore.jpg"],["Q751192",515,"film","Mark Hoffman","PC","Mark Hoffman est un inspecteur de police et l'un des grands méchants de la saga d'horreur Saw. Complice puis successeur de Jigsaw, il est interprété par l'acteur australien Costas Mandylor.","Mark Hoffman est un inspecteur de police et l'un des grands méchants de la saga d'horreur Saw.","en:Mark_Hoffman","https://upload.wikimedia.org/wikipedia/en/thumb/2/24/Costas-mandylor-iv.jpg/330px-Costas-mandylor-iv.jpg"],["Q1081532",516,"film","Marshall Eriksen","C","Marshall Eriksen est l'un des cinq personnages principaux du feuilleton How I Met Your Mother, interprété par l'acteur américain Jason Segel.",118,"fr:Marshall_Eriksen","c:6/6e/Jason_Segel%2C_2011.jpg"],["Q1073372",517,"film","Mary Alice Young","C","Mary Alice Young est le nom d'un personnage fictif de la série télévisée Desperate Housewives, interprété par Brenda Strong. Narratrice du feuilleton, Mary Alice se suicide dès le pilote et commente désormais la vie de ses voisines et amies de Wisteria Lane, à l'aide d'une morale introduisant et concluant chaque épisode.",116,"fr:Mary_Alice_Young","c:5/5f/Brenda_Strong_2009.jpg"],["Q1141828",518,"film","Medb","C","Medb, Maeve ou Maëve, est, dans le cycle d’Ulster de la mythologie irlandaise, la reine de Connacht et l’épouse du roi Ailill mac Máta. Elle apparaît comme l’une des principales antagonistes des Ulaid et de leur héros Cú Chulainn, en particulier dans l’épopée Táin Bó Cúailnge. Sa résidence principale se situe à Crúachu.",118,"fr:Medb","c:3/31/Queen_Maev_by_J.C._Leyendecker_%281911%29.jpg"],["Q6819675",519,"film","Merle Dixon","C","Merle Dixon est un personnage principal de la série télévisée The Walking Dead. Il est interprété par Michael Rooker et doublé en version française par Patrick Floersheim.","Merle Dixon est un personnage principal de la série télévisée The Walking Dead.","fr:Merle_Dixon","c:e/e6/Michael_Rooker_2013_02_%28cropped%29.jpg"],["Q113870",520,"film","Michonne","PC","Michonne est un personnage principal de la série télévisée The Walking Dead. Elle est interprétée par Danai Gurira et doublée en version française par Laura Zichy.","Michonne est un personnage principal de la série télévisée The Walking Dead.","fr:Michonne","c:c/c8/Danai_Gurira_by_Gage_Skidmore.jpg"],["Q1088642",521,"film","Mike Delfino","C","Mike Delfino est le nom d'un personnage fictif du feuilleton Desperate Housewives, interprété par James Denton.",null,"fr:Mike_Delfino","c:c/c9/James_Denton_2009.jpg"],["Q65502940",522,"film","Mike Wheeler","C","Mike Wheeler est un personnage fictif de la série de science-fiction et d'horreur de Netflix Stranger Things, créée par Matt et Ross Duffer. Interprété par l'acteur canadien Finn Wolfhard, il est l'un des personnages principaux de la série, agissant comme le leader d'un groupe d'adolescents.",119,"fr:Mike_Wheeler","https://upload.wikimedia.org/wikipedia/en/thumb/9/91/Mike_Wheeler.png/330px-Mike_Wheeler.png"],["Q2400233",523,"film","Miranda Bailey","R","Dr Miranda Bailey un personnage fictif de la série télévisée Grey's Anatomy et de son spin-off Station 19, surnommée \"Le Tyran\" par ses internes et interprété par l'actrice Chandra Wilson qui a gagné en 2007 le \"Screen Actor's Guild Award\" pour ce rôle. Chandra Wilson a également été nommée aux Emmy Awards pour ce rôle.",116,"fr:Miranda_Bailey","c:b/b2/%22VOICE_AWARDS-2015%22_%2821415850790%29.jpg"],["Q211414",524,"film","Miss Moneypenny","R","Miss Moneypenny, personnage de fiction de la saga James Bond, est la secrétaire de M, le patron de James Bond.",null,"fr:Miss_Moneypenny","https://upload.wikimedia.org/wikipedia/en/thumb/9/9b/Miss_Moneypenny_by_Lois_Maxwell.jpg/330px-Miss_Moneypenny_by_Lois_Maxwell.jpg"],["Q2284305",525,"film","Moe Greene","R","Moe Greene est un personnage du roman Le Parrain de Mario Puzo et du film de 1972. Patron d'un casino à Las Vegas, il est inspiré du gangster Bugsy Siegel et refuse de vendre ses parts aux Corleone.","Moe Greene est un personnage du roman Le Parrain de Mario Puzo et du film de 1972.","fr:Moe_Greene","https://upload.wikimedia.org/wikipedia/en/thumb/4/48/Moe_Greene_2.png/330px-Moe_Greene_2.png"],["Q6911724",526,"film","Morgan Jones","PC","Morgan Jones est un personnage des séries télévisées The Walking Dead et Fear the Walking Dead. Il est interprété par Lennie James et doublé en version française par Thierry Desroses.","Morgan Jones est un personnage des séries télévisées The Walking Dead et Fear the Walking Dead.","fr:Morgan_Jones","c:8/8c/LennieJames2015.jpg"],["Q500727",527,"film","Morticia Addams","L","Morticia Addams est la mère de la famille Addams, créée par le dessinateur américain Charles Addams en 1933. Matriarche élégante et sombre, toujours vêtue d'une longue robe noire, elle a été jouée notamment par Carolyn Jones, Anjelica Huston et Catherine Zeta-Jones.","Morticia Addams est la mère de la famille Addams, créée par le dessinateur américain Charles Addams en 1933.","en:Morticia_Addams","c:5/5c/Morticia_Addams.jpg"],["Q2456753",528,"film","Mrs Hudson","C","Mrs Martha Hudson ou Mme Martha Hudson est un personnage de fiction des romans et nouvelles de Sir Arthur Conan Doyle. Elle est la logeuse de Sherlock Holmes à Londres, au 221B Baker Street.","Mrs Martha Hudson ou Mme Martha Hudson est un personnage de fiction des romans et nouvelles de Sir Arthur Conan Doyle.","fr:Mrs_Hudson",""],["Q1616457",529,"film","Mycroft Holmes","PC","Mycroft Holmes est un personnage de fiction créé par Conan Doyle. Il est le frère aîné de Sherlock Holmes. Il apparaît pour la première fois dans la nouvelle intitulée L'Interprète grec.","Mycroft Holmes est un personnage de fiction créé par Conan Doyle.","fr:Mycroft_Holmes","c:3/3b/Gree-02.jpg"],["Q66563368",530,"film","Nairobi","C","Nairobi, de son vrai nom Ágata Jiménez, est un personnage de la série espagnole La casa de papel, jouée par Alba Flores. Experte en contrefaçon, elle supervise l'impression des billets lors du braquage de la Fabrique nationale de la monnaie.","Nairobi, de son vrai nom Ágata Jiménez, est un personnage de la série espagnole La casa de papel, jouée par Alba Flores.","en:Nairobi_(Money_Heist)","c:7/78/Wandgem%C3%A4lde_Alba_Flores_-_Nairobi_-_Venloer_Stra%C3%9Fe_274%2C_K%C3%B6ln-Ehrenfeld-7360.jpg"],["Q65515695",531,"film","Nancy Wheeler","C","Nancy Wheeler est un personnage de la série Stranger Things de Netflix, jouée par Natalia Dyer. Grande sœur de Mike, elle enquête sans relâche sur les mystères de Hawkins et rêve de devenir journaliste.","Nancy Wheeler est un personnage de la série Stranger Things de Netflix, jouée par Natalia Dyer.","en:Nancy_Wheeler","https://upload.wikimedia.org/wikipedia/en/thumb/7/73/Nancy_Wheeler.png/330px-Nancy_Wheeler.png"],["Q2662867",532,"film","Neuvième Docteur","C","Le Neuvième Docteur est la neuvième incarnation du Docteur, personnage central de la série télévisée de science-fiction Doctor Who, produite par la BBC. Il est interprété par Christopher Eccleston. Le Neuvième Docteur est le seul à n'être apparu qu'une seule saison. Par ailleurs, il est celui qui a marqué le retour de la série à la télévision, seize ans après la mise en hiatus de cette dernière en 1989, mise à part le téléfilm de 1996. Il voyage avec Rose Tyler, vendeuse dans une boutique de vêtements.",119,"fr:Neuvième_Docteur","c:c/c1/Christopher_Eccleston_London.jpg"],["Q3875745",533,"film","Neytiri","C","Neytiri te Tskaha Mo'at'ite est un personnage de l'univers fictif Avatar. Elle est la princesse Na'vi du clan Omaticaya. Elle est la deuxième fille d'Eytukan et Mo'at.","Neytiri te Tskaha Mo'at'ite est un personnage de l'univers fictif Avatar.","fr:Neytiri","c:e/e2/Portrait_of_Neytiri.jpg"],["Q1113573",534,"film","Niklaus Mikaelson","PC","Klaus Mikaelson est un personnage de Vampire Diaries, d'abord dans les romans puis dans la série, où il est joué par Joseph Morgan. Vampire originel et loup-garou à la fois, il a ensuite sa propre série, The Originals.",116,"en:Klaus_Mikaelson","https://upload.wikimedia.org/wikipedia/en/thumb/f/f3/Klaus_The_Originals.jpg/330px-Klaus_The_Originals.jpg"],["Q1190608",535,"film","Norbert Dragonneau","R","Norbert Artemis Fido Dragonneau est le personnage principal de la série de films Les Animaux fantastiques, écrite par J. K. Rowling et réalisée par David Yates. Il est également mentionné à quelques reprises dans la série romanesque Harry Potter, en tant qu'auteur du livre Vie et habitat des animaux fantastiques.","Norbert Artemis Fido Dragonneau est le personnage principal de la série de films Les Animaux fantastiques, écrite par J.","fr:Norbert_Dragonneau","c:f/f1/Newt_Scamander.jpg"],["Q3880820",536,"film","Oddjob","PC","Oddjob est un personnage fictif de l'univers de James Bond. Il est l'allié le plus fiable d'Auric Goldfinger.","Oddjob est un personnage fictif de l'univers de James Bond.","fr:Oddjob","https://upload.wikimedia.org/wikipedia/en/thumb/d/dc/OddJob_-_Goldfinger_%281964%29.jpg/330px-OddJob_-_Goldfinger_%281964%29.jpg"],["Q500471",537,"film","Oncle Fétide","E","L'oncle Fétide est un membre de la famille Addams : crâne chauve, teint blafard, il adore les explosions et peut allumer une ampoule en la mettant dans sa bouche. Il a été joué notamment par Jackie Coogan et Christopher Lloyd.",112,"en:Uncle_Fester","c:1/11/Jackie_Coogan_as_Uncle_Fester_%28The_Addams_Family%2C_1966%29.jpg"],["Q2667397",538,"film","Onzième Docteur","PC","Le Onzième Docteur est la onzième incarnation du Docteur, personnage principal de la série télévisée de science-fiction Doctor Who, produite par la BBC. Il est interprété par Matt Smith, qui est le plus jeune acteur à avoir interprété le Docteur depuis 1963.",119,"fr:Onzième_Docteur","c:6/63/Matt_Smith_%28series_7_filming%29.jpg"],["Q1048135",539,"film","Orson Hodge","PC","Orson Hodge est le nom d'un personnage du feuilleton Desperate Housewives, joué par Kyle MacLachlan.",null,"fr:Orson_Hodge","c:d/d7/Kyle_MacLachlan_2009.jpg"],["Q20890036",540,"film","Owen Grady","C","Owen Grady est un personnage de fiction de la franchise Jurassic Park. Il est introduit dans le quatrième film Jurassic World, qui est également le premier volet de la trilogie Jurassic World. Colin Trevorrow réalise et co-écrit le film, retenant Chris Pratt dans le rôle d'Owen. Il est l'un des trois principaux protagonistes de la trilogie, avec sa compagne Claire Dearing et sa fille adoptive, Maisie Lockwood, qui a fait ses débuts dans Jurassic World: Fallen Kingdom.","Owen Grady est un personnage de fiction de la franchise Jurassic Park.","fr:Owen_Grady","c:9/96/Jurassic_World_Fallen_Kingdom_Japan_Premiere_Red_Carpet_Chris_Pratt_%2841294369590%29.jpg"],["Q60685",541,"film","Paige Matthews","C","Paige Matthews est un personnage de fiction et une des trois héroïnes de la série télévisée Charmed. Elle est interprétée par Rose McGowan, du 4 octobre 2001 au 21 mai 2006. Le personnage a été créé par le producteur exécutif Brad Kern en remplaçant le personnage principal Prue Halliwell, à la suite du départ de l'actrice Shannen Doherty.","Paige Matthews est un personnage de fiction et une des trois héroïnes de la série télévisée Charmed.","fr:Paige_Matthews","c:2/22/Rose_McGowan.jpg"],["Q938265",542,"film","Paul Kellerman","C","Paul Kellerman est un personnage du feuilleton télévisé Prison Break joué par Paul Adelstein.",null,"fr:Paul_Kellerman","c:0/08/Paul_Adelstein_2008.jpg"],["Q2326044",543,"film","Paulie Gualtieri","E","Peter Paul « Paulie Walnuts » Gualtieri, interprété par Tony Sirico, est un personnage fictif de la série télévisée d'HBO Les Soprano. Il est un des principaux hommes de main du principal protagoniste de la série, en l'occurrence Tony Soprano. Sirico est auditionné pour le rôle d'Oncle Junior avec Frank Vincent, mais Dominic Chianese récupère le rôle. David Chase lui propose celui de Paulie Gualtieri, mais Sirico accepte à la condition que son personnage ne devienne pas un informateur.",115,"fr:Paulie_Gualtieri","c:6/63/Paulie_Gualtieri_%28The_Sopranos_Family_Tree%29.jpg"],["Q2362493",544,"film","Peeta Mellark","PC","Peeta Mellark est un personnage de fiction de la trilogie Hunger Games, interprété par Josh Hutcherson dans l'adaptation cinématographique.",107,"fr:Peeta_Mellark","c:f/f9/Peeta_Mellark_dans_l%27ar%C3%A8ne_des_74e_Hunger_Games.jpg"],["Q4360302",545,"film","Petyr Baelish","PC","Petyr Baelish, dit « Littlefinger », est un personnage de fiction de la série de romans Le Trône de fer de George R. R. Martin, adaptée pour la télévision sous le titre Game of Thrones, dans laquelle le personnage est interprété par Aidan Gillen.","Petyr Baelish, dit « Littlefinger », est un personnage de fiction de la série de romans Le Trône de fer de George R.","fr:Petyr_Baelish","c:c/c4/Aidan_Gillen_%28headshot%29.jpg"],["Q1639574",546,"film","Phoebe Halliwell","C","Phoebe Halliwell est un personnage de fiction issu de la série télévisée Charmed. Elle est interprétée par Alyssa Milano du 7 octobre 1998 au 21 mai 2006. Le personnage a été créé par Constance M. Burge. Phoebe est introduite dans Charmed en tant que sœur cadette de Prue et de Piper Halliwell; ainsi que la demi-sœur aînée de Paige Matthews. Elle est plus spécifiquement une charmante et puissante sorcière. Phoebe possède initialement le pouvoir de la prémonition, ce qui lui permet de voir l'avenir et le passé.","Phoebe Halliwell est un personnage de fiction issu de la série télévisée Charmed.","fr:Phoebe_Halliwell","c:d/de/Alyssa_Milano_2011_cropped.jpg"],["Q1647226",547,"film","Piper Halliwell","C","Piper Halliwell est un personnage de fiction issu de la série télévisée Charmed. Elle est interprétée par Holly Marie Combs. Elle fait sa première apparition le 7 octobre 1998 dans le premier épisode de la série. Le personnage a été créé par Constance M. Burge. Piper est introduite dans la série en tant que sœur cadette de Prue et sœur aînée de Phoebe. Piper possède initialement le pouvoir d'arrêter le temps dans son environnement à l'aide de ses mains.","Piper Halliwell est un personnage de fiction issu de la série télévisée Charmed.","fr:Piper_Halliwell","c:9/91/Holly_Marie_Combs_2%2C_2012.jpg"],["Q2989412",548,"film","Premier Docteur","C","Le Premier Docteur est la première incarnation du Docteur, personnage principal de la série télévisée de science-fiction britannique, Doctor Who, produite par la BBC. Il a été interprété par l'acteur William Hartnell de 1963 à 1966. Hartnell a repris ce rôle une seule fois, pour l'épisode du dixième anniversaire de la série, Les Trois Docteurs. Cependant, il n'est apparu que très peu de fois dans cet épisode à cause de ses problèmes de santé.",104,"fr:Premier_Docteur","c:2/2f/William_Hartnell%2C_1946_%28halftone_filtered%29.jpg"],["Q15695359",549,"film","Hanna Marin","C","Pretty Little Liars, ou Les Menteuses au Québec, est une série télévisée américaine en 161 épisodes d'environ 44 minutes, développée par I. Marlene King et diffusée entre le 8 juin 2010 et le 27 juin 2017 sur ABC Family/Freeform et en simultané au Canada sur MuchMore/M3 pour les six premières saisons puis sur Bravo!.",112,"fr:Hanna_Marin","https://upload.wikimedia.org/wikipedia/en/thumb/8/84/Hanna_Marin.jpeg/330px-Hanna_Marin.jpeg"],["Q1750877",550,"film","Prudence Halliwell","C","Prudence « Prue » Halliwell, interprétée par Shannen Doherty, est un personnage de fiction qui apparaît dans les trois premières saisons de la série télévisée Charmed. Le personnage a été créé par Constance M. Burge. Prue figure dans la série en tant que sœur aînée de Piper et de Phoebe. Elle fait sa première apparition le 7 octobre 1998 dans le premier épisode de la série ''Le Livre des Ombres'' et sa dernière apparition le 17 mai 2001 dans le dernier épisode de la troisième saison, ''Adieux''.",118,"fr:Prudence_Halliwell","c:a/a0/Shannen_Doherty_2015_%28cropped2%29.jpg"],["Q287297",551,"film","Q","R","Q est un personnage fictif de la série James Bond créé par Ian Fleming. Il est le responsable de la section « Q », division recherche et développement du MI6 qui invente et fournit les célèbres gadgets de James Bond.","Q est un personnage fictif de la série James Bond créé par Ian Fleming.","fr:Q_(James_Bond)","c:6/65/Desmond_Llewelyn_01.jpg"],["Q13520213",552,"film","Ragnar Lothbrok","C","Ragnar Lothbrok est le héros de la série historique Vikings, joué par Travis Fimmel. Inspiré du chef viking légendaire Ragnar Lodbrok, ce simple fermier devient roi et part piller l'Angleterre et la France.","Ragnar Lothbrok est le héros de la série historique Vikings, joué par Travis Fimmel.","en:Ragnar_Lothbrok_(Vikings)","c:1/16/Drawing_of_Travis_Fimmel_as_Ragnar_Lothbrok.jpg"],["Q653748",553,"film","Rajesh Koothrappali","PC","Dr Rajesh Ramayan Koothrappali est un personnage de fiction de la série télévisée américaine The Big Bang Theory, diffusée depuis 2007 sur le réseau CBS. Il est joué par l'acteur anglais d'origine indienne, Kunal Nayyar. Il est le meilleur ami de Howard Wolowitz, et un des personnages principaux.",113,"fr:Rajesh_Koothrappali","c:f/f8/Kunal_Nayyar.png"],["Q55196423",554,"film","Raquel Murillo","C","Raquel Murillo est un personnage de la série espagnole La casa de papel, jouée par Itziar Ituño. Inspectrice chargée de l'enquête sur le braquage, elle finit par rejoindre l'équipe sous le nom de Lisbonne.","Raquel Murillo est un personnage de la série espagnole La casa de papel, jouée par Itziar Ituño.","en:Raquel_Murillo","https://upload.wikimedia.org/wikipedia/en/thumb/9/9f/Raquel_Murillo.jpg/330px-Raquel_Murillo.jpg"],["Q2559996",555,"film","Ray Stantz","C","Ray Stantz est l'un des chasseurs de fantômes de la saga SOS Fantômes (Ghostbusters). Passionné et enthousiaste, c'est lui qui pense par erreur au Bibendum Chamallow. Il est joué par Dan Aykroyd.","Ray Stantz est l'un des chasseurs de fantômes de la saga SOS Fantômes (Ghostbusters).","en:Ray_Stantz","https://upload.wikimedia.org/wikipedia/en/thumb/6/60/Ray_Stantz_%28Dan_Aykroyd%29.jpg/330px-Ray_Stantz_%28Dan_Aykroyd%29.jpg"],["Q496852",556,"film","Remy Hadley","R","Remy Hadley, plus connue sous son surnom de « Numéro Treize », est un personnage de fiction de la série médicale de la FOX, Dr House. C'est une médecin, interprétée par Olivia Wilde, qui intègre l'équipe du service de médecine diagnostique du docteur Gregory House au cours de la saison 4.",118,"fr:Remy_Hadley","c:4/43/Olivia_Wilde%2C_ROMY_2010.jpg"],["Q18920105",557,"film","Renly Baratheon","C","Renly Baratheon est un personnage de la saga Le Trône de fer de George R. R. Martin et de son adaptation Game of Thrones. Plus jeune frère du roi Robert, il se proclame roi à la mort de celui-ci.","Renly Baratheon est un personnage de la saga Le Trône de fer de George R.","en:Renly_Baratheon","https://upload.wikimedia.org/wikipedia/en/thumb/a/a9/Renly_Baratheon_Profile_Gethin_Anthony.jpg/330px-Renly_Baratheon_Profile_Gethin_Anthony.jpg"],["Q55452801",558,"film","Rhaenyra Targaryen","R","Rhaenyra Targaryen est un personnage de l'univers du Trône de fer de George R. R. Martin, héroïne de la série House of the Dragon. Héritière désignée du trône de fer, elle affronte sa propre famille lors de la guerre civile appelée la Danse des dragons.","Rhaenyra Targaryen est un personnage de l'univers du Trône de fer de George R.","en:Rhaenyra_Targaryen","https://upload.wikimedia.org/wikipedia/en/thumb/f/fa/Rhaenyra_Targaryen.webp/330px-Rhaenyra_Targaryen.webp"],["Q2665317",559,"film","River Song","C","River Song est un personnage fictif de la série de science-fiction britannique Doctor Who, interprété par Alex Kingston. Le personnage a été inventé par le scénariste et producteur exécutif Steven Moffat, qui a écrit tous les épisodes ou scènes dans lesquels elle apparaît.","River Song est un personnage fictif de la série de science-fiction britannique Doctor Who, interprété par Alex Kingston.","fr:River_Song","c:6/66/Alex_Kingston_July_2017.jpg"],["Q13634884",560,"film","Robb Stark","PC","Robb Stark, surnommé « le Jeune Loup », est un personnage de la saga Le Trône de fer de George R. R. Martin et de son adaptation télévisée Game of Thrones, où il est joué par Richard Madden. Fils aîné de Ned Stark, il devient roi du Nord.","Robb Stark, surnommé « le Jeune Loup », est un personnage de la saga Le Trône de fer de George R.","en:Robb_Stark","https://upload.wikimedia.org/wikipedia/en/thumb/c/ce/Robb_Stark-Richard_Madden.jpg/330px-Robb_Stark-Richard_Madden.jpg"],["Q13634885",561,"film","Robert Baratheon","PC","Robert Baratheon est un personnage de fiction de la série Le Trône de fer, écrite par George R. R. Martin.","Robert Baratheon est un personnage de fiction de la série Le Trône de fer, écrite par George R.","fr:Robert_Baratheon","c:3/35/Mark_Addy.JPG"],["Q1051954",562,"film","Robert Chase","C","Dr Robert Chase est un personnage de fiction de la série Dr House diffusée sur le réseau FOX, et en France sur TF6 puis TF1. Ce personnage est interprété par Jesse Spencer, sa voix française par Guillaume Lebon.",119,"fr:Robert_Chase","c:0/01/Jesse_Spencer_cropped.jpg"],["Q97441222",563,"film","Robin Buckley","C","Robin Buckley est un personnage de la série Stranger Things de Netflix, jouée par Maya Hawke. Collègue de Steve chez le glacier Scoops Ahoy, elle est aussi douée pour décoder les messages secrets que pour les répliques cinglantes.","Robin Buckley est un personnage de la série Stranger Things de Netflix, jouée par Maya Hawke.","en:Robin_Buckley","https://upload.wikimedia.org/wikipedia/en/thumb/0/02/Robin_Buckley.jpg/330px-Robin_Buckley.jpg"],["Q2347474",564,"film","Robin Scherbatsky","PC","Robin Scherbatsky est l'un des cinq personnages principaux de la série How I Met Your Mother, interprété par l'actrice canadienne Cobie Smulders.",118,"fr:Robin_Scherbatsky","c:9/99/Cobie_Smulders_by_Gage_Skidmore_2.jpg"],["Q2716380",565,"film","Rosalie Hale","C","Rosalie Lilian Hale est un personnage de fiction de la saga Twilight de Stephenie Meyer.",null,"fr:Rosalie_Hale","c:0/0b/Nikki_Reed_Oct_%28cropped%29.jpg"],["Q2071982",566,"film","Rose Tyler","C","Rose Tyler est un personnage fictif interprété par Billie Piper dans la série télévisée britannique de science-fiction Doctor Who, créé par le producteur Russell T Davies.",118,"fr:Rose_Tyler","c:5/5e/Billie_Piper_%2816%29_edited.jpg"],["Q102402667",567,"film","Rue Bennett","PC","Rue Bennett est l'héroïne et la narratrice de la série Euphoria, sur HBO, jouée par Zendaya. Lycéenne qui lutte contre la drogue, elle raconte la vie de ses amis avec un humour noir.","Rue Bennett est l'héroïne et la narratrice de la série Euphoria, sur HBO, jouée par Zendaya.","en:Rue_Bennett","https://upload.wikimedia.org/wikipedia/en/thumb/7/72/Rue_Bennett.png/330px-Rue_Bennett.png"],["Q1342302",568,"film","Salvatore Tessio","PC","Salvatore Tessio est un personnage du roman Le Parrain de Mario Puzo et des deux premiers films de Francis Ford Coppola. Vieux capo de la famille Corleone, il finit par trahir Michael. Il est joué par Abe Vigoda.","Salvatore Tessio est un personnage du roman Le Parrain de Mario Puzo et des deux premiers films de Francis Ford Coppola.","en:Salvatore_Tessio","https://upload.wikimedia.org/wikipedia/en/thumb/5/5c/Salvatore_Tessio.jpg/330px-Salvatore_Tessio.jpg"],["Q900737",569,"film","Sam Winchester","PC","Sam Winchester est l'un des deux héros de la série américaine Supernatural, avec son grand frère Dean. Étudiant brillant devenu chasseur de créatures surnaturelles, il est interprété par Jared Padalecki.","Sam Winchester est l'un des deux héros de la série américaine Supernatural, avec son grand frère Dean.","en:Sam_Winchester","https://upload.wikimedia.org/wikipedia/en/thumb/8/84/Jared_Padalecki_as_Sam_Winchester.png/330px-Jared_Padalecki_as_Sam_Winchester.png"],["Q51328",570,"film","Sayid Jarrah","C","Sayid Jarrah est un personnage fictif du feuilleton télévisé Lost: Les Disparus. Il est interprété par l'acteur Naveen Andrews.","Sayid Jarrah est un personnage fictif du feuilleton télévisé Lost: Les Disparus.","fr:Sayid_Jarrah","c:8/8a/Naveen_Andrews.jpg"],["Q2254504",571,"film","Serena Van Der Woodsen","C","Serena van der Woodsen est l'héroïne de Gossip Girl, d'abord dans les romans puis dans la série, où elle est jouée par Blake Lively. « It girl » de Manhattan, elle est la meilleure amie, et parfois la rivale, de Blair Waldorf.",118,"en:Serena_van_der_Woodsen","https://upload.wikimedia.org/wikipedia/en/thumb/8/86/Serenavanderwoodsen.jpg/330px-Serenavanderwoodsen.jpg"],["Q2604786",572,"film","Shane Walsh","PC","Shane Walsh est un personnage principal de la série télévisée The Walking Dead. Il est interprété par Jon Bernthal et doublé en version française par Jérôme Pauwels.","Shane Walsh est un personnage principal de la série télévisée The Walking Dead.","fr:Shane_Walsh","c:7/77/Jon_Bernthal_by_Gage_Skidmore.jpg"],["Q478507",573,"film","Skynet","L","Skynet est un personnage de science-fiction présent dans la série de films Terminator. Intelligence artificielle créée à l'origine pour automatiser la riposte nucléaire américaine, il est le principal antagoniste de la série. Après son effacement, il sera remplacé par « Légion », une intelligence artificielle tout aussi cruelle que lui.","Skynet est un personnage de science-fiction présent dans la série de films Terminator.","fr:Skynet_(Terminator)","c:4/4d/Skynet_Terminator_logo.png"],["Q575889",574,"film","Sonny Corleone","R","Santino Corleone, dit Sonny, est un personnage de fiction de la série de romans Le Parrain interprété par James Caan dans le film homonyme. Né en 1916, il est le fils aîné de Vito Corleone et à ce titre est préparé à prendre sa succession à la tête des affaires de la famille Corleone.",116,"fr:Sonny_Corleone","https://upload.wikimedia.org/wikipedia/en/thumb/9/9d/Santino_corleone_2.jpg/330px-Santino_corleone_2.jpg"],["Q2076468",575,"film","Soundwave","C","Soundwave est un robot de la franchise Transformers. Fidèle lieutenant de Megatron, le chef des Decepticons, il est leur officier des communications et se transforme le plus souvent en lecteur de cassettes.","Soundwave est un robot de la franchise Transformers.","en:Soundwave_(Transformers)","https://upload.wikimedia.org/wikipedia/en/thumb/c/ce/Transformers-Soundwave-IDWArtwork.png/330px-Transformers-Soundwave-IDWArtwork.png"],["Q7576069",576,"film","Spencer Hastings","C","Spencer Hastings est l'un des quatre personnages principaux de la série de romans Les Menteuses, de Sara Shepard. Dans la série télévisée, Spencer est interprétée par l'actrice Troian Bellisario, tandis que sur la couverture des romans, elle est interprétée par Alexandra Bowen. Pour ce rôle, Shay Mitchell et Janel Parrish avaient auditionné, mais les producteurs l'ont donné à Troian Bellisario.","Spencer Hastings est l'un des quatre personnages principaux de la série de romans Les Menteuses, de Sara Shepard.","fr:Spencer_Hastings","https://upload.wikimedia.org/wikipedia/en/thumb/0/01/Spencer_Hastings_from_Pretty_Little_Liars.png/330px-Spencer_Hastings_from_Pretty_Little_Liars.png"],["Q2276742",577,"film","Spike","PC","Spike est un personnage fictif créé par Joss Whedon pour les séries télévisées Buffy contre les vampires et Angel, interprété par James Marsters et doublé en version française par Serge Faliu. C'est un vampire, connu pour avoir éliminé deux Tueuses, qui apparaît dans la saison 2 de Buffy contre les vampires.",114,"fr:Spike_(Buffy_contre_les_vampires)","c:9/96/James_Marsters.jpg"],["Q1038555",578,"film","Stefan Salvatore","PC","Stefan Salvatore est un personnage de fiction créé par L. J. Smith dans la série de romans The Vampire Diaries. Il est interprété par Paul Wesley dans la série télévisée homonyme. Stefan a été transformé en vampire, en 1864, à l'âge de 17 ans, par Katherine Pierce, avec son frère Damon Salvatore. À la fin de la saison 8, il redevient humain, étant donné que Bonnie lui a injecté contre son gré le remède au vampirisme.","Stefan Salvatore est un personnage de fiction créé par L.","fr:Stefan_Salvatore","c:4/43/Paul_Wesley_by_Gage_Skidmore_4.jpg"],["Q65515753",579,"film","Steve Harrington","PC","Steve Harrington est un personnage de la série Stranger Things de Netflix, joué par Joe Keery. D'abord présenté comme le beau gosse arrogant du lycée, il devient au fil des saisons le grand frère protecteur de la bande, batte à clous à la main.","Steve Harrington est un personnage de la série Stranger Things de Netflix, joué par Joe Keery.","en:Steve_Harrington","https://upload.wikimedia.org/wikipedia/en/thumb/8/8b/ST3_Steve_Harrington_portrait.jpg/330px-ST3_Steve_Harrington_portrait.jpg"],["Q617179",580,"film","Susan Mayer","PC","Susan Delfino est l'un des personnages principaux du feuilleton Desperate Housewives, interprété par Teri Hatcher.",null,"fr:Susan_Mayer","c:3/3d/Teri_Hatcher-_World_of_Color_Premiere_21.jpg"],["Q2341891",581,"film","T-X","C","Le T-X est un personnage de fiction créé par John D. Brancato, Michael Ferris et Tedi Sarafian dans le film Terminator 3: Le Soulèvement des machines, réalisé par Jonathan Mostow, sorti en 2003. Le modèle T-X est un assassin humanoïde ayant l'apparence d'une femme. Le personnage a été présenté comme le principal antagoniste du troisième film de la saga Terminator, interprété par l'actrice Kristanna Loken.","Le T-X est un personnage de fiction créé par John D.","fr:T-X","https://upload.wikimedia.org/wikipedia/en/thumb/3/32/T-X_%28Kristanna_Loken%29.jpg/330px-T-X_%28Kristanna_Loken%29.jpg"],["Q3297949",582,"film","Tauriel","PC","Tauriel est un personnage de fiction apparaissant dans la saga cinématographique de fantasy Le Hobbit de Peter Jackson, adaptation du roman éponyme de l'écrivain britannique J. R. R. Tolkien. Ce personnage n'existe pas dans le livre original de Tolkien. Peter Jackson a décidé d'incorporer un personnage féminin dans le deuxième volet de la trilogie cinématographique. Ce changement a engendré une polémique parmi les fans du roman.",119,"fr:Tauriel","c:1/12/Tauriel_elf.jpg"],["Q116764604",583,"film","The Deep","C","The Deep est un super-héros de The Boys, membre des Sept, le groupe de héros corrompus de Vought. Capable de parler aux animaux marins, il est surtout ridicule et prétentieux. Dans la série, il est joué par Chace Crawford.","The Deep est un super-héros de The Boys, membre des Sept, le groupe de héros corrompus de Vought.","en:The_Deep_(The_Boys)","https://upload.wikimedia.org/wikipedia/en/thumb/7/72/The-Deep-comic-vs-tv-series.jpg/330px-The-Deep-comic-vs-tv-series.jpg"],["Q756787",584,"film","Theodore Bagwell","C","Theodore Bagwell, dit « T-Bag », est un personnage de fiction de la série télévisée américaine Prison Break. Interprété par Robert Knepper, il est l'un des détenus de la prison de Fox River.","Theodore Bagwell, dit « T-Bag », est un personnage de fiction de la série télévisée américaine Prison Break.","fr:Theodore_Bagwell","c:5/54/Robert_Knepper_Brussels_2016.jpg"],["Q1120793",585,"film","Theon Greyjoy","R","Theon Greyjoy est l'un des personnages de la saga Le Trône de fer écrite par George R. R. Martin. Il est le fils du seigneur Balon Greyjoy des Îles de fer.","Theon Greyjoy est l'un des personnages de la saga Le Trône de fer écrite par George R.","fr:Theon_Greyjoy","c:1/1b/Alfie_Allen_by_Gage_Skidmore_2.jpg"],["Q746840",586,"film","Thranduil","R","Thranduil est un personnage de l'œuvre de J. R. R. Tolkien.","Thranduil est un personnage de l'œuvre de J.","fr:Thranduil","c:0/09/Elvenking_by_Nolwyn.jpg"],["Q798823",587,"film","Tom Hagen","R","Tom Hagen est un personnage de fiction dans le roman Le Parrain, joué par Robert Duvall dans les films Le Parrain et Le Parrain, 2e partie, réalisés par Francis Ford Coppola. Il est le fils adoptif de Don Vito Corleone.",119,"fr:Tom_Hagen","https://upload.wikimedia.org/wikipedia/en/thumb/6/67/Tom_Hagen.jpg/330px-Tom_Hagen.jpg"],["Q1076692",588,"film","Tom Scavo","C","Thomas Scavo alias Tom est le nom d'un personnage fictif du feuilleton Desperate Housewives joué par Doug Savant, il est l'époux de Lynette Scavo.",116,"fr:Tom_Scavo","c:f/f3/Doug_Savant_2009.jpg"],["Q12902445",589,"film","Tywin Lannister","PC","Tywin Lannister est un personnage de la saga Le Trône de fer de George R. R. Martin et l'un des grands antagonistes de la série Game of Thrones, où il est joué par Charles Dance. Seigneur de Castral Roc, il est le père de Cersei, Jaime et Tyrion.","Tywin Lannister est un personnage de la saga Le Trône de fer de George R.","en:Tywin_Lannister","https://upload.wikimedia.org/wikipedia/en/thumb/b/b9/Tywin_Lannister_Profile_Charles_Dance.jpg/330px-Tywin_Lannister_Profile_Charles_Dance.jpg"],["Q1063148",590,"film","Veronica Donovan","C","Veronica Donovan, jouée par Robin Tunney, est un personnage du feuilleton télévisé Prison Break. Veronica enfant n'est apparue que dans un seul épisode, lors d'un flashback, et est interprétée par Annie Yokom.","Veronica Donovan, jouée par Robin Tunney, est un personnage du feuilleton télévisé Prison Break.","fr:Veronica_Donovan","c:f/f6/RobinTunneyHWOFFeb2013.jpg"],["Q3564252",591,"film","Veronica Lodge","C","Veronica Lodge, ou Véronica Lasalle dans la première version française, est un personnage fictif de la série de bande-dessinée Archie Comics, elle est l'un des principaux personnages de la bande d'Archie.",111,"fr:Veronica_Lodge","https://upload.wikimedia.org/wikipedia/fr/thumb/9/90/Veronica_%28logo_original%29.png/330px-Veronica_%28logo_original%29.png"],["Q2608715",592,"film","Vesper Lynd","E","Vesper Lynd est un personnage de fiction, apparu en 1953 dans Casino Royale, l'un des romans de la série des James Bond écrite par Ian Fleming et adapté au cinéma.",119,"fr:Vesper_Lynd","c:5/59/Eva_Green_%28Headshot%29.jpg"],["Q763903",593,"film","Vincent Mancini-Corleone","PC","Vincent Santino Mancini-Corleone, parfois simplement appelé Vincenzo Corleone est un personnage de fiction de la série de romans Le Parrain, interprété par Andy Garcia dans Le Parrain 3. C’est un amalgame de cinq hommes de la famille Corleone: il a la ruse de Vito, la détermination impitoyable de Michael, la sensibilité de Fredo, le tempérament fougueux de Sonny et l'absolue loyauté de Tom Hagen.",118,"fr:Vincent_Mancini-Corleone","c:d/d2/Andy_Garcia_at_the_2009_Deauville_American_Film_Festival-01A.jpg"],["Q1051419",594,"film","Vladimir Harkonnen","R","Le baron Vladimir Harkonnen est un personnage de fiction issu du cycle de Dune de l'écrivain Frank Herbert, apparaissant dans les romans Dune et Les Enfants de Dune.",107,"fr:Vladimir_Harkonnen","https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/HarkonnenHeraldic.svg/330px-HarkonnenHeraldic.svg.png"],["Q65505002",595,"film","Will Byers","C","Will Byers est un personnage de la série Stranger Things de Netflix, joué par Noah Schnapp. Sa mystérieuse disparition à Hawkins, en 1983, déclenche toute l'histoire de la série.","Will Byers est un personnage de la série Stranger Things de Netflix, joué par Noah Schnapp.","en:Will_Byers","https://upload.wikimedia.org/wikipedia/en/thumb/f/f9/Will_Byers_ST5.png/330px-Will_Byers_ST5.png"],["Q2760369",596,"film","Will Graham","E","Will Graham est le héros du roman Dragon rouge de Thomas Harris. Profileur du FBI capable de se mettre dans la tête des tueurs, il affronte Hannibal Lecter. Dans la série Hannibal, il est joué par Hugh Dancy.","Will Graham est le héros du roman Dragon rouge de Thomas Harris.","en:Will_Graham_(character)","https://upload.wikimedia.org/wikipedia/en/thumb/9/9b/Will_Graham.jpg/330px-Will_Graham.jpg"],["Q1042244",597,"film","Willow Rosenberg","C","Willow Rosenberg est un personnage fictif de la série télévisée Buffy contre les vampires interprété par Alyson Hannigan. C'est l'un des personnages principaux de la série, étant la seule avec sa meilleure amie Buffy Summers, l'héroïne, à être présente à l'écran dans tous les épisodes de la série. D'abord présentée comme une lycéenne brillante mais peu sûre d'elle, son personnage quitte peu à peu le rôle de faire-valoir de Buffy pour devenir une sorcière d'une grande puissance.",111,"fr:Willow_Rosenberg","c:4/49/Alyson_Hannigan.jpg"],["Q664182",598,"film","Winston Zeddemore","C","Winston Zeddemore est le quatrième membre des chasseurs de fantômes de la saga SOS Fantômes (Ghostbusters). Recruté par petite annonce, il est joué par Ernie Hudson.","Winston Zeddemore est le quatrième membre des chasseurs de fantômes de la saga SOS Fantômes (Ghostbusters).","en:Winston_Zeddemore","https://upload.wikimedia.org/wikipedia/en/thumb/5/53/Winston_Zeddemore_%28Ernie_Hudson%29.jpg/330px-Winston_Zeddemore_%28Ernie_Hudson%29.jpg"],["Fhp_dobby",599,"litterature","Dobby","E","Dobby est un elfe de maison de la saga Harry Potter, d'abord au service des Malefoy puis libéré grâce à une chaussette offerte par Harry. « Dobby est un elfe libre ! »",107,"https://harrypotter.fandom.com/wiki/Dobby","https://static.wikia.nocookie.net/harrypotter/images/8/82/Dobby.jpg/revision/latest/scale-to-width-down/400"],["Fhp_fred_weasley",600,"litterature","Fred Weasley","R","Fred Weasley est l'un des jumeaux farceurs de la famille Weasley dans Harry Potter, cofondateur avec George de la boutique de farces « Weasley, Farces pour sorciers facétieux ».",113,"https://harrypotter.fandom.com/wiki/Fred_Weasley","https://static.wikia.nocookie.net/harrypotter/images/9/9e/Fred_Weasley_promo_DHF1.jpg/revision/latest/scale-to-width-down/400"],["Fhp_george_weasley",601,"litterature","George Weasley","R","George Weasley est l'un des jumeaux farceurs de la famille Weasley dans Harry Potter, cofondateur avec Fred de la boutique de farces du Chemin de Traverse.",113,"https://harrypotter.fandom.com/wiki/George_Weasley","https://static.wikia.nocookie.net/harrypotter/images/b/b5/George_Weasley_promo_DHF1.jpg/revision/latest/scale-to-width-down/400"],["Fhp_molly_weasley",602,"litterature","Molly Weasley","R","Molly Weasley est la mère de la famille Weasley dans Harry Potter, chaleureuse et redoutable : c'est elle qui vainc Bellatrix Lestrange lors de la bataille de Poudlard.",115,"https://harrypotter.fandom.com/wiki/Molly_Weasley","https://static.wikia.nocookie.net/harrypotter/images/3/3c/Molly_Weasley_Deathly_Hallows.jpg/revision/latest/scale-to-width-down/400"],["Fhp_arthur_weasley",603,"litterature","Arthur Weasley","PC","Arthur Weasley est le père de Ron dans Harry Potter, employé du ministère de la Magie passionné par les objets moldus et les prises électriques.",110,"https://harrypotter.fandom.com/wiki/Arthur_Weasley","https://static.wikia.nocookie.net/harrypotter/images/0/02/Arthur_Weasley_profile.jpg/revision/latest/scale-to-width-down/400"],["Fhp_percy_weasley",604,"litterature","Percy Weasley","C","Percy Weasley est le troisième fils de la famille Weasley dans Harry Potter, préfet ambitieux et très attaché au règlement.",112,"https://harrypotter.fandom.com/wiki/Percy_Weasley","https://static.wikia.nocookie.net/harrypotter/images/b/bc/Percy_WeasleyDH.jpg/revision/latest/scale-to-width-down/400"],["Fhp_bill_weasley",605,"litterature","Bill Weasley","C","Bill Weasley est l'aîné des enfants Weasley dans Harry Potter, briseur de sorts pour la banque Gringotts et mari de Fleur Delacour.",115,"https://harrypotter.fandom.com/wiki/Bill_Weasley","https://static.wikia.nocookie.net/harrypotter/images/6/66/BillWeasleyDH2.png/revision/latest/scale-to-width-down/400"],["Fhp_charlie_weasley",606,"litterature","Charlie Weasley","C","Charlie Weasley est le deuxième fils de la famille Weasley dans Harry Potter, qui étudie les dragons en Roumanie.",null,"https://harrypotter.fandom.com/wiki/Charlie_Weasley","https://static.wikia.nocookie.net/harrypotter/images/d/d0/Charlie_PM.jpg/revision/latest/scale-to-width-down/400"],["Fhp_lucius_malfoy",607,"litterature","Lucius Malefoy","R","Lucius Malefoy est le père de Drago dans Harry Potter, riche sang-pur arrogant et Mangemort fidèle à Voldemort.",null,"https://harrypotter.fandom.com/wiki/Lucius_Malfoy","https://static.wikia.nocookie.net/harrypotter/images/b/b4/Lucius_Malfoy_BoH.png/revision/latest/scale-to-width-down/400"],["Fhp_narcissa_malfoy",608,"litterature","Narcissa Malefoy","PC","Narcissa Malefoy est la mère de Drago dans Harry Potter, sœur de Bellatrix, qui ment à Voldemort pour sauver son fils.",null,"https://harrypotter.fandom.com/wiki/Narcissa_Malfoy","https://static.wikia.nocookie.net/harrypotter/images/7/78/Narcissa_Malfoy.png/revision/latest/scale-to-width-down/400"],["Fhp_peter_pettigrew",609,"litterature","Peter Pettigrow","R","Peter Pettigrow, alias Queudver, est l'ancien ami des parents de Harry qui les a trahis au profit de Voldemort. Il s'est caché douze ans sous la forme du rat Croûtard.",114,"https://harrypotter.fandom.com/wiki/Peter_Pettigrew","https://static.wikia.nocookie.net/harrypotter/images/5/5a/Peter_Pettigrew_GOFF.webp/revision/latest/scale-to-width-down/400"],["Fhp_alastor_moody",610,"litterature","Maugrey Fol Œil","R","Alastor Maugrey, dit « Fol Œil », est un Auror légendaire de Harry Potter, reconnaissable à son œil magique. « Vigilance constante ! »",110,"https://harrypotter.fandom.com/wiki/Alastor_Moody","https://static.wikia.nocookie.net/harrypotter/images/4/4d/MoodyProfile.png/revision/latest/scale-to-width-down/400"],["Fhp_nymphadora_tonks",611,"litterature","Nymphadora Tonks","PC","Nymphadora Tonks est une Auror métamorphomage de l'Ordre du Phénix dans Harry Potter, qui déteste son prénom et change de couleur de cheveux à volonté.",111,"https://harrypotter.fandom.com/wiki/Nymphadora_Tonks","https://static.wikia.nocookie.net/harrypotter/images/c/c8/Nymphadora_Tonks_DH_promo_headshot_.jpg/revision/latest/scale-to-width-down/400"],["Fhp_kingsley_shacklebolt",612,"litterature","Kingsley Shacklebolt","PC","Kingsley Shacklebolt est un Auror de l'Ordre du Phénix dans Harry Potter, qui devient ministre de la Magie après la chute de Voldemort.",115,"https://harrypotter.fandom.com/wiki/Kingsley_Shacklebolt","https://static.wikia.nocookie.net/harrypotter/images/5/5e/Kingsley_Shacklebolt_DHF1_promo.jpg/revision/latest/scale-to-width-down/400"],["Fhp_cedric_diggory",613,"litterature","Cedric Diggory","R","Cedric Diggory est le champion de Poudlard lors du Tournoi des Trois Sorciers dans Harry Potter, attrapeur de Poufsouffle tué par Peter Pettigrow.",109,"https://harrypotter.fandom.com/wiki/Cedric_Diggory","https://static.wikia.nocookie.net/harrypotter/images/9/90/Cedric_Diggory_Profile.png/revision/latest/scale-to-width-down/400"],["Fhp_cho_chang",614,"litterature","Cho Chang","PC","Cho Chang est une élève de Serdaigle dans Harry Potter, attrapeuse de Quidditch et premier amour de Harry.",null,"https://harrypotter.fandom.com/wiki/Cho_Chang","https://static.wikia.nocookie.net/harrypotter/images/1/1e/Cho_Chang.jpg/revision/latest/scale-to-width-down/400"],["Fhp_gilderoy_lockhart",615,"litterature","Gilderoy Lockhart","PC","Gilderoy Lockhart est le professeur de défense contre les forces du mal de Harry Potter en deuxième année : écrivain vaniteux qui s'attribue les exploits des autres.",116,"https://harrypotter.fandom.com/wiki/Gilderoy_Lockhart","https://static.wikia.nocookie.net/harrypotter/images/7/7b/Gilderoy_Lockhart_promotional_image_COSF.jpg/revision/latest/scale-to-width-down/400"],["Fhp_quirinus_quirrell",616,"litterature","Quirinus Quirrell","PC","Quirinus Quirrell est le professeur bègue de défense contre les forces du mal en première année de Harry Potter, qui cache Voldemort sous son turban.",116,"https://harrypotter.fandom.com/wiki/Quirinus_Quirrell","https://static.wikia.nocookie.net/harrypotter/images/d/d2/Quirinus_Quirrell_PS_promo.jpg/revision/latest/scale-to-width-down/400"],["Fhp_myrtle_warren",617,"litterature","Mimi Geignarde","PC","Mimi Geignarde est le fantôme qui hante les toilettes des filles de Poudlard dans Harry Potter, tuée des années plus tôt par le Basilic.",116,"https://harrypotter.fandom.com/wiki/Myrtle_Warren","https://static.wikia.nocookie.net/harrypotter/images/b/b8/Myrtle_Warren_profile.png/revision/latest/scale-to-width-down/400"],["Fhp_hedwig",618,"litterature","Hedwige","R","Hedwige est la chouette des neiges de Harry Potter, offerte par Hagrid pour ses onze ans et fidèle messagère du jeune sorcier.",111,"https://harrypotter.fandom.com/wiki/Hedwig","https://static.wikia.nocookie.net/harrypotter/images/1/1e/Hedwig_Snowy_Owl_PM.png/revision/latest/scale-to-width-down/400"],["Fhp_argus_filch",619,"litterature","Argus Rusard","PC","Argus Rusard est le concierge cracmol de Poudlard dans Harry Potter, toujours flanqué de sa chatte Miss Teigne et rêvant de pendre les élèves par les pouces.",113,"https://harrypotter.fandom.com/wiki/Argus_Filch","https://static.wikia.nocookie.net/harrypotter/images/c/c9/Filch-GOF.jpg/revision/latest/scale-to-width-down/400"],["Fhp_pomona_sprout",620,"litterature","Pomona Chourave","C","Pomona Chourave est la professeure de botanique et directrice de Poufsouffle à Poudlard dans Harry Potter, spécialiste des mandragores.",106,"https://harrypotter.fandom.com/wiki/Pomona_Sprout","https://static.wikia.nocookie.net/harrypotter/images/6/6e/Pomona_Sprout_DHF2.jpg/revision/latest/scale-to-width-down/400"],["Fhp_filius_flitwick",621,"litterature","Filius Flitwick","PC","Filius Flitwick est le petit professeur d'enchantements et directeur de Serdaigle à Poudlard dans Harry Potter. « Wingardium Leviosa ! »",113,"https://harrypotter.fandom.com/wiki/Filius_Flitwick","https://static.wikia.nocookie.net/harrypotter/images/4/4b/Flitwickarmourbattle.png/revision/latest/scale-to-width-down/400"],["Fhp_sybill_trelawney",622,"litterature","Sibylle Trelawney","PC","Sibylle Trelawney est la professeure de divination de Poudlard dans Harry Potter, souvent à côté de la plaque… sauf pour deux vraies prophéties.",115,"https://harrypotter.fandom.com/wiki/Sybill_Trelawney","https://static.wikia.nocookie.net/harrypotter/images/5/5d/Sybill_Trelawney.JPG/revision/latest/scale-to-width-down/400"],["Fhp_horace_slughorn",623,"litterature","Horace Slughorn","PC","Horace Slughorn est le professeur de potions de Harry Potter en sixième année, collectionneur d'élèves prometteurs et ancien professeur de Tom Jedusor.",114,"https://harrypotter.fandom.com/wiki/Horace_Slughorn","https://static.wikia.nocookie.net/harrypotter/images/a/a1/Horace_Slughorn_%28HBP_promo%29_1-1.jpg/revision/latest/scale-to-width-down/400"],["Fhp_gellert_grindelwald",624,"litterature","Gellert Grindelwald","E","Gellert Grindelwald est un mage noir de l'univers de Harry Potter, ancien ami d'Albus Dumbledore et grand méchant des Animaux fantastiques.",113,"https://harrypotter.fandom.com/wiki/Gellert_Grindelwald","https://static.wikia.nocookie.net/harrypotter/images/4/40/Gellert_Grindelwald_SODM.jpeg/revision/latest/scale-to-width-down/400"],["Fhp_kreacher",625,"litterature","Kreattur","PC","Kreattur est le vieil elfe de maison grincheux de la famille Black dans Harry Potter, qui finit par se battre aux côtés de Harry.",113,"https://harrypotter.fandom.com/wiki/Kreacher","https://static.wikia.nocookie.net/harrypotter/images/d/d4/Kreacher_HPE.jpg/revision/latest/scale-to-width-down/400"],["Fhp_buckbeak",626,"litterature","Buck","R","Buck est l'hippogriffe de Hagrid dans Harry Potter, condamné à mort après avoir blessé Drago Malefoy, puis sauvé par Harry et Hermione.",116,"https://harrypotter.fandom.com/wiki/Buckbeak","https://static.wikia.nocookie.net/harrypotter/images/c/c7/B3C14M1_cropped_Buckbeak_PM.png/revision/latest/scale-to-width-down/400"],["Fhp_fawkes",627,"litterature","Fumseck","E","Fumseck est le phénix d'Albus Dumbledore dans Harry Potter : ses larmes guérissent et ses plumes servent de cœur aux baguettes de Harry et de Voldemort.",116,"https://harrypotter.fandom.com/wiki/Fawkes","https://static.wikia.nocookie.net/harrypotter/images/f/f8/Fawkes_WB_F2_FawkesCloseUpIllustration_Illust_100615_Port.jpg/revision/latest/scale-to-width-down/400"],["Fhp_nagini",628,"litterature","Nagini","R","Nagini est le serpent de Voldemort dans Harry Potter, l'un de ses Horcruxes, tué par Neville Londubat avec l'épée de Gryffondor.",116,"https://harrypotter.fandom.com/wiki/Nagini","https://static.wikia.nocookie.net/harrypotter/images/7/70/Nagini_PM.png/revision/latest/scale-to-width-down/400"],["Fhp_vernon_dursley",629,"litterature","Vernon Dursley","PC","Vernon Dursley est l'oncle moldu de Harry Potter, vendeur de perceuses qui déteste tout ce qui est anormal… surtout son neveu.",115,"https://harrypotter.fandom.com/wiki/Vernon_Dursley","https://static.wikia.nocookie.net/harrypotter/images/9/9e/Vernon_Dursley_HP5.jpg/revision/latest/scale-to-width-down/400"],["Fhp_petunia_dursley",630,"litterature","Pétunia Dursley","C","Pétunia Dursley est la tante moldue de Harry Potter et la sœur de Lily, jalouse depuis toujours du monde des sorciers.",null,"https://harrypotter.fandom.com/wiki/Petunia_Dursley","https://static.wikia.nocookie.net/harrypotter/images/6/64/Petunia_DH1.png/revision/latest/scale-to-width-down/400"],["Fhp_dudley_dursley",631,"litterature","Dudley Dursley","C","Dudley Dursley est le cousin gâté de Harry Potter, qui compte ses cadeaux d'anniversaire et finit avec une queue de cochon grâce à Hagrid.",115,"https://harrypotter.fandom.com/wiki/Dudley_Dursley","https://static.wikia.nocookie.net/harrypotter/images/1/19/Dudley_DH.png/revision/latest/scale-to-width-down/400"],["Fhp_lily_j_potter",632,"litterature","Lily Potter","R","Lily Potter est la mère de Harry dans la saga, une sorcière née moldue dont le sacrifice a protégé son fils du sortilège de Voldemort.",110,"https://harrypotter.fandom.com/wiki/Lily_J._Potter","https://static.wikia.nocookie.net/harrypotter/images/5/53/Lily_Potter_%28I%29_DHF2.jpg/revision/latest/scale-to-width-down/400"],["Fhp_james_potter_i",633,"litterature","James Potter","R","James Potter est le père de Harry dans la saga, ancien maraudeur farceur de Gryffondor capable de se transformer en cerf.",115,"https://harrypotter.fandom.com/wiki/James_Potter_I","https://static.wikia.nocookie.net/harrypotter/images/1/10/James_Potter_I_Deathly_Hallows.jpg/revision/latest/scale-to-width-down/400"],["Fhp_vincent_crabbe",634,"litterature","Vincent Crabbe","C","Vincent Crabbe est l'un des deux gros bras de Drago Malefoy à Serpentard dans Harry Potter.",null,"https://harrypotter.fandom.com/wiki/Vincent_Crabbe","https://static.wikia.nocookie.net/harrypotter/images/b/ba/Vincent_Crabbe.jpg/revision/latest/scale-to-width-down/400"],["Fhp_gregory_goyle",635,"litterature","Gregory Goyle","C","Gregory Goyle est l'autre gros bras de Drago Malefoy à Serpentard dans Harry Potter, inséparable de Crabbe.",null,"https://harrypotter.fandom.com/wiki/Gregory_Goyle","https://static.wikia.nocookie.net/harrypotter/images/e/e7/Gregory_Goyle_DH2.jpg/revision/latest/scale-to-width-down/400"],["Fhp_viktor_krum",636,"litterature","Viktor Krum","PC","Viktor Krum est l'attrapeur vedette de l'équipe de Bulgarie et le champion de Durmstrang au Tournoi des Trois Sorciers dans Harry Potter.",109,"https://harrypotter.fandom.com/wiki/Viktor_Krum","https://static.wikia.nocookie.net/harrypotter/images/9/93/Viktor_Krum_promo_Yule_Ball.png/revision/latest/scale-to-width-down/400"],["Fhp_fleur_delacour",637,"litterature","Fleur Delacour","PC","Fleur Delacour est la championne de Beauxbâtons au Tournoi des Trois Sorciers dans Harry Potter, en partie Vélane, qui épouse Bill Weasley.",114,"https://harrypotter.fandom.com/wiki/Fleur_Delacour","https://static.wikia.nocookie.net/harrypotter/images/1/1e/Fleur_Delacour.jpg/revision/latest/scale-to-width-down/400"],["Fhp_olympe_maxime",638,"litterature","Olympe Maxime","C","Olympe Maxime est la directrice géante de l'Académie de magie Beauxbâtons dans Harry Potter.",null,"https://harrypotter.fandom.com/wiki/Olympe_Maxime","https://static.wikia.nocookie.net/harrypotter/images/f/f9/Maxime_1.png/revision/latest/scale-to-width-down/400"],["Fhp_cornelius_fudge",639,"litterature","Cornelius Fudge","C","Cornelius Fudge est le ministre de la Magie dans Harry Potter, qui refuse de croire au retour de Voldemort.",null,"https://harrypotter.fandom.com/wiki/Cornelius_Fudge","https://static.wikia.nocookie.net/harrypotter/images/6/6d/Corneliushogwarts.jpg/revision/latest/scale-to-width-down/400"],["Fhp_bartemius_crouch_junior",640,"litterature","Barty Croupton Jr","PC","Barty Croupton Jr est un Mangemort de Harry Potter qui se fait passer pour Maugrey Fol Œil pendant toute une année grâce au Polynectar.",114,"https://harrypotter.fandom.com/wiki/Bartemius_Crouch_Junior","https://static.wikia.nocookie.net/harrypotter/images/f/f4/Barty_Crouch_Junior.jpg/revision/latest/scale-to-width-down/400"],["Fhp_seamus_finnigan",641,"litterature","Seamus Finnigan","C","Seamus Finnigan est un camarade de dortoir de Harry à Gryffondor, célèbre pour faire exploser ses sortilèges.",null,"https://harrypotter.fandom.com/wiki/Seamus_Finnigan","https://static.wikia.nocookie.net/harrypotter/images/a/a7/Seamus_Finnigan_GOFF_promo.png/revision/latest/scale-to-width-down/400"],["Fhp_dean_thomas",642,"litterature","Dean Thomas","C","Dean Thomas est un élève de Gryffondor dans Harry Potter, camarade de dortoir de Harry et fan de football.",null,"https://harrypotter.fandom.com/wiki/Dean_Thomas","https://static.wikia.nocookie.net/harrypotter/images/9/93/Dean_Thomas_DHF2.jpg/revision/latest/scale-to-width-down/400"],["Fhp_lavender_brown",643,"litterature","Lavande Brown","C","Lavande Brown est une élève de Gryffondor dans Harry Potter, petite amie collante de Ron qui l'appelle « Ron-Ron ».",null,"https://harrypotter.fandom.com/wiki/Lavender_Brown","https://static.wikia.nocookie.net/harrypotter/images/b/b6/Lavender_Brown_HBP.jpg/revision/latest/scale-to-width-down/400"],["Fhp_oliver_wood",644,"litterature","Olivier Dubois","C","Olivier Dubois est le capitaine passionné de l'équipe de Quidditch de Gryffondor dans Harry Potter, gardien de but.",null,"https://harrypotter.fandom.com/wiki/Oliver_Wood","https://static.wikia.nocookie.net/harrypotter/images/2/2f/Oliver_WoodDH2.jpg/revision/latest/scale-to-width-down/400"],["Fhp_aberforth_dumbledore",645,"litterature","Abelforth Dumbledore","PC","Abelforth Dumbledore est le frère d'Albus dans Harry Potter, patron du pub La Tête de Sanglier à Pré-au-Lard, qui aime beaucoup les chèvres.",113,"https://harrypotter.fandom.com/wiki/Aberforth_Dumbledore","https://static.wikia.nocookie.net/harrypotter/images/4/40/Aberforth_Dumbledore.jpg/revision/latest/scale-to-width-down/400"],["Fhp_garrick_ollivander",646,"litterature","Garrick Ollivander","PC","Garrick Ollivander est le fabricant de baguettes du Chemin de Traverse dans Harry Potter. « C'est la baguette qui choisit son sorcier. »",113,"https://harrypotter.fandom.com/wiki/Garrick_Ollivander","https://static.wikia.nocookie.net/harrypotter/images/6/6f/Garrick_Ollivander.png/revision/latest/scale-to-width-down/400"],["Fhp_sorting_hat",647,"litterature","Choixpeau magique","R","Le Choixpeau magique est le vieux chapeau parlant de Poudlard dans Harry Potter, qui répartit les nouveaux élèves dans les quatre maisons.",113,"https://harrypotter.fandom.com/wiki/Sorting_Hat","https://static.wikia.nocookie.net/harrypotter/images/6/62/Sorting_Hat.png/revision/latest/scale-to-width-down/400"],["Fhp_nearly_headless_nick",648,"litterature","Nick Quasi-Sans-Tête","C","Nick Quasi-Sans-Tête est le fantôme de la tour de Gryffondor dans Harry Potter, décapité… presque complètement.",null,"https://harrypotter.fandom.com/wiki/Nearly_Headless_Nick","https://static.wikia.nocookie.net/harrypotter/images/6/6d/Nicholas_de_Mimsy-Porpington.png/revision/latest/scale-to-width-down/400"],["Fhp_mrs_norris",649,"litterature","Miss Teigne","C","Miss Teigne est la chatte d'Argus Rusard dans Harry Potter, qui surveille les couloirs de Poudlard et prévient son maître de chaque bêtise.",114,"https://harrypotter.fandom.com/wiki/Mrs_Norris","https://static.wikia.nocookie.net/harrypotter/images/f/f7/Mrs_Norris_PS.png/revision/latest/scale-to-width-down/400"],["Fhp_aragog",650,"litterature","Aragog","PC","Aragog est l'acromantule géante élevée par Hagrid dans Harry Potter, qui vit avec sa colonie dans la Forêt interdite.",null,"https://harrypotter.fandom.com/wiki/Aragog","https://static.wikia.nocookie.net/harrypotter/images/2/2c/Aragog_in_his_lair_COSF.jpg/revision/latest/scale-to-width-down/400"],["Fhp_fluffy",651,"litterature","Touffu","PC","Touffu est le chien à trois têtes de Hagrid dans Harry Potter, qui garde la pierre philosophale et s'endort dès qu'on joue de la musique.",111,"https://harrypotter.fandom.com/wiki/Fluffy","https://static.wikia.nocookie.net/harrypotter/images/1/11/B1C9M3_cropped_Fluffy.png/revision/latest/scale-to-width-down/400"],["Fhp_norberta",652,"litterature","Norbert","PC","Norbert est le bébé dragon de race Norvégien à crête que Hagrid fait éclore dans sa cabane, dans Harry Potter à l'école des sorciers.",111,"https://harrypotter.fandom.com/wiki/Norberta","https://static.wikia.nocookie.net/harrypotter/images/c/c1/Norberta_Norwegian_Ridgeback.jpg/revision/latest/scale-to-width-down/400"],["Fhp_grawp",653,"litterature","Graup","C","Graup est le demi-frère géant de Hagrid dans Harry Potter, caché dans la Forêt interdite.",null,"https://harrypotter.fandom.com/wiki/Grawp","https://static.wikia.nocookie.net/harrypotter/images/e/e6/Grawp.png/revision/latest/scale-to-width-down/400"],["Fhp_firenze",654,"litterature","Firenze","C","Firenze est un centaure de la Forêt interdite dans Harry Potter, qui devient professeur de divination à Poudlard.",null,"https://harrypotter.fandom.com/wiki/Firenze","https://static.wikia.nocookie.net/harrypotter/images/7/70/B5C27_Firenze_PM_cropped.jpg/revision/latest/scale-to-width-down/400"],["Fhp_griphook",655,"litterature","Gripsec","C","Gripsec est le gobelin de la banque Gringotts dans Harry Potter, qui aide Harry, Ron et Hermione à cambrioler la banque.",null,"https://harrypotter.fandom.com/wiki/Griphook","https://static.wikia.nocookie.net/harrypotter/images/5/53/Griphook_TDH_SF.png/revision/latest/scale-to-width-down/400"],["Fhp_winky",656,"litterature","Winky","C","Winky est l'elfe de maison de la famille Croupton dans Harry Potter, renvoyée et inconsolable.",null,"https://harrypotter.fandom.com/wiki/Winky","https://static.wikia.nocookie.net/harrypotter/images/9/95/Winky_jim_kay.webp/revision/latest/scale-to-width-down/400"],["Fhp_regulus_black",657,"litterature","Regulus Black","PC","Regulus Black est le frère de Sirius dans Harry Potter, ancien Mangemort qui a volé l'un des Horcruxes de Voldemort.",null,"https://harrypotter.fandom.com/wiki/Regulus_Black","https://static.wikia.nocookie.net/harrypotter/images/7/73/Regulus_PM.png/revision/latest/scale-to-width-down/400"],["Fhp_crookshanks",658,"litterature","Pattenrond","C","Pattenrond est le chat roux à tête aplatie d'Hermione dans Harry Potter, qui démasque très vite le rat Croûtard.",null,"https://harrypotter.fandom.com/wiki/Crookshanks","https://static.wikia.nocookie.net/harrypotter/images/f/ff/Crookshanks_FH.png/revision/latest/scale-to-width-down/400"],["Q1750813",659,"mechant","Erik (Le Fantôme de l'Opéra)","C","Erik, le Fantôme de l'Opéra, est le héros tragique du roman de Gaston Leroux (1910). Génie défiguré caché sous un masque dans les souterrains de l'Opéra de Paris, il est éperdument amoureux de la chanteuse Christine Daaé.",113,"en:Erik_(The_Phantom_of_the_Opera)","c:c/c2/ChaneyPhantomoftheOpera.jpg"],["Q936278",660,"mechant","Imhotep (La Momie)","PC","Imhotep est un personnage de fiction créé par John L. Balderston, Nina Wilcox Putnam et Richard Schayer dans le film La Momie réalisé par Karl Freund en 1932.","Imhotep est un personnage de fiction créé par John L.","fr:Imhotep_(La_Momie)","c:6/64/Boris_Karloff_The_Mummy.jpg"],["Q4006190",661,"mechant","Larry Talbot","PC","Larry Talbot est le Loup-Garou des films Universal, apparu en 1941 dans The Wolf Man. Mordu par un loup-garou, il se transforme les nuits de pleine lune. Il a été incarné par Lon Chaney Jr. puis par Benicio del Toro en 2010.",116,"en:Larry_Talbot","c:e/e8/HorrorMonstersNo1Pg1Crop_%28black_and_white%29.png"],["Q669485",662,"mechant","Sweeney Todd","R","Sweeney Todd est le nom d'un tueur en série du folklore anglais dont l'histoire a donné lieu à des adaptations au théâtre et au cinéma.",113,"fr:Sweeney_Todd","c:d/d5/Todd_murdering_a_victim.png"],["Q85762489",663,"mechant","Gage Creed","C","Gage Creed est le petit garçon de Simetierre, le roman de Stephen King (1983). Tué par un camion, il est enterré dans un ancien cimetière indien par son père, et revient à la vie sous une forme meurtrière.",112,"en:Gage_Creed",""],["Q2485929",664,"litterature","Baie d'Or (Tolkien)","C","Baie d'Or est un personnage secondaire du Seigneur des anneaux de J. R. R. Tolkien, qui apparaît également dans les poèmes « Les Aventures de Tom Bombadil » et « Once Upon a Time ». Surnommée « fille de la Rivière » et étroitement liée à l'élément aquatique, elle est la femme de Tom Bombadil. Sa nature exacte est tout aussi mystérieuse que celle de son époux.",115,"fr:Baie_d'Or",""],["Q1750830",665,"litterature","Beorn","C","Beorn est un personnage du roman Le Hobbit de J. R. R. Tolkien.",null,"fr:Beorn","c:f/f3/Beorn_by_JMKilpatrick.jpg"],["Q3502914",666,"litterature","Bolg","C","Bolg est un chef orque du Hobbit, fils d'Azog, qui mène les gobelins à la bataille des Cinq Armées.",null,"en:Bolg",""],["Q4940810",667,"litterature","Bombur","C","Bombur est le nain le plus gros de la compagnie de Thorin dans Le Hobbit, connu pour son appétit et sa tendance à s'endormir.",113,"en:Bombur",""],["Q718380",668,"litterature","Denethor II","C","Denethor II est un personnage du légendaire de l'écrivain britannique J. R. R. Tolkien, apparaissant dans le troisième tome du roman Le Seigneur des anneaux, Le Retour du roi.",108,"fr:Denethor",""],["Q719736",669,"litterature","Elendil","C","Elendil est un personnage de fiction faisant partie de l'univers de la Terre du Milieu de l'écrivain britannique J. R. R. Tolkien. Il apparaît dans les romans Le Seigneur des anneaux, Le Silmarillion et les Contes et légendes inachevés.",115,"fr:Elendil",""],["Q462760",670,"litterature","Guetteur des Eaux","C","Le Guetteur des Eaux est une créature de fiction présente sur la Terre du Milieu dans le légendaire de J. R. R. Tolkien; elle apparaît dans La Fraternité de l'anneau, le premier volume du Seigneur des anneaux.",111,"fr:Guetteur_des_Eaux",""],["Q423759",671,"litterature","Kíli","C","Kíli est l'un des plus jeunes nains de la compagnie de Thorin dans Le Hobbit, neveu de Thorin et frère de Fíli, excellent archer.",111,"en:Kili",""],["Q1095530",672,"litterature","Mûmak (Seigneur des anneaux)","C","Le mûmak ou oliphant est une créature fictive inventée par J. R. R. Tolkien, qui apparaît principalement dans Le Seigneur des anneaux. Semblable à un gigantesque pachyderme, cet animal, qui provient du sud de la Terre du Milieu, est employé par les Haradrim comme éléphant de guerre.",112,"fr:Mûmak","c:9/9d/M%C3%BBmak.jpg"],["Q397148",673,"litterature","Óin","C","OIN est un sigle, qui peut signifier:",null,"fr:OIN",""],["Q7460721",674,"litterature","Gripoil","C","Gripoil (Shadowfax) est le seigneur des Mearas dans Le Seigneur des anneaux, le cheval blanc le plus rapide de la Terre du Milieu, monture de Gandalf.",113,"en:Shadowfax",""],["Q2291020",675,"litterature","Vieil Homme-Saule","C","Le Vieil Homme-Saule est un personnage du légendaire de l'écrivain britannique J. R. R. Tolkien qui apparaît dans La Communauté de l'Anneau, le premier volume du Seigneur des anneaux,.",116,"fr:Vieil_Homme-Saule","https://upload.wikimedia.org/wikipedia/en/thumb/c/c9/Old_Man_Willow.jpg/330px-Old_Man_Willow.jpg"],["Q216605",676,"litterature","Éomer","C","Éomer est un personnage du Seigneur des anneaux de J. R. R. Tolkien.",null,"fr:Éomer",""]]]);